TURATH_CHUNK(54,[{"num":10800,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: أَخَذَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِنْتًا لَهُ تَقْضِي، فَاحْتَضَنَهَا، فَوَضَعَهَا بَيْنَ ثَدْيَيْهِ فَمَاتَتْ وَهِيَ بَيْنَ ثَدْيَيْهِ، فَصَاحَتْ أُمُّ أَيْمَنَ، فَقِيلَ: أَتَبْكِي عِنْدَ رَسُولِ اللَّهِ؟ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَتْ: أَلَسْتُ أَرَاكَ تَبْكِي يَا رَسُولَ اللَّهِ؟ قَالَ: لَسْتُ أَبْكِي، إِنَّمَا هِيَ رَحْمَةٌ، إِنَّ الْمُؤْمِنَ بِكُلِّ خَيْرٍ عَلَى كُلِّ حَالٍ، إِنَّ نَفْسَهُ تَخْرُجُ مِنْ بَيْنِ جَنْبَيْهِ، وَهُوَ يَحْمَدُ اللهَ عَزَّ وَجَلَّ."],"takhrij":"صحيح: رواه أحمد (2475) عن أبي أحمد، حدثنا سفيان، عن عطاء بن السائب، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب أن المؤمن يحمد اللّٰه على كل حال","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (2475).","chapter_en":"The Believer Praises Allah in Every Circumstance","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Prophet ﷺ took one of his daughters while she was dying, embraced her, and placed her against his chest. She died while resting against his chest. Umm Ayman cried out, and she was asked: “Are you weeping in the presence of the Messenger of Allah ﷺ?” She replied: “Do I not see you weeping, O Messenger of Allah?” He said: “I am not weeping; this is only mercy. The believer remains in goodness under every circumstance. Even as his soul departs from between his sides, he continues praising Allah, Mighty and Majestic.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3590],"tks":"صحيح: رواه أحمد (2475)."},{"num":10801,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ: إِنَّ عَبْدِي الْمُؤْمِنَ عِنْدِي بِمَنْزِلَةِ كُلِّ خَيْرٍ، يَحْمَدُنِي وَأَنَا أَنْزِعُ نَفْسَهُ مِنْ بَيْنِ جَنْبَيْهِ."],"takhrij":"حسن: رواه أحمد (4892)، والبيهقي في الشعب (4175) كلاهما من طريق يزيد بن الهاد، عن عمرو، عن المقبري، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب أن المؤمن يحمد اللّٰه على كل حال","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (4892) and al-Bayhaqī in Shuʿab al-Īmān (4175).","chapter_en":"The Believer Praises Allah in Every Circumstance","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah said: I heard the Messenger of Allah ﷺ say: “Allah, Mighty and Majestic, says: ‘My believing servant occupies with Me a position of complete goodness. He praises Me even as I draw his soul from between his sides.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (4892)، والبيهقي في شعب الإيمان (4175)."},{"num":10802,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بن حُصَيْنٍ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أَفْضَلَ عِبَادِ اللَّهِ يَوْمَ الْقِيَامَةِ الْحَمَّادُونَ، ثُمَّ لا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي يُقَاتِلُونَ مَنْ نَاوَأَهُمْ مِنْ أَهْلِ الشِّرْكِ حَتَّى يُقَاتِلُونَ الدَّجَّالَ."],"takhrij":"حسن: رواه الطبراني في الكبير (18/ح 254) عن محمد بن حمويه الجوهري الأهوازي، حدثنا أبو يوسف يعقوب بن إسحاق العلوي، حدثنا بكر بن يحيى بن زبان، حدثنا حسان بن إبراهيم، عن محمد بن عبد الله، عن عبد الرحمن بن مورق، عن ابن الشخير، عن عمران بن حصين فذكره.","grade":"حسن","chapter_ar":"باب أن المؤمن يحمد اللّٰه على كل حال","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (18/124) and Imam Aḥmad (19895).","chapter_en":"The Believer Praises Allah in Every Circumstance","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn narrated that the Messenger of Allah ﷺ said: “The best servants of Allah on the Day of Resurrection will be those who frequently praise Him. A group from my nation will continue fighting those who oppose them from among the polytheists until they fight the Antichrist.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (18/ح 254)، والإمام أحمد (19895)."},{"num":10803,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَوَّلُ مَنْ يُدْعَى إِلَى الْجَنَّةِ الْحَمَّادُونَ، الَّذِينَ يَحْمَدُونَ اللَّهَ فِي السَّرَّاءِ وَالضَّرَّاءِ."],"takhrij":"حسن: رواه الطبراني في الكبير (12/19)، وفي الأوسط –مجمع البحرين (4548) من طرقٍ عن عاصم بن علي، حدثنا قيس بن الربيع، عن حبيب بن أبي ثابت، عن سعيد بن جبير، عن ابن عباس قال: فذكره.","grade":"حسن","chapter_ar":"باب أن المؤمن يحمد اللّٰه على كل حال","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (12/19) and al-Muʿjam al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (4548).","chapter_en":"The Believer Praises Allah in Every Circumstance","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Messenger of Allah ﷺ said: “The first people to be called to Paradise will be those who frequently praise Allah—those who praise Allah in prosperity and adversity.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (12/19)، وفي الأوسط، كما في مجمع البحرين (4548)."},{"num":10804,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدَبٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  أَحَبُّ الْكَلَامِ إِلَى اللَّهِ أَرْبَعٌ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللهُ أَكْبَرُ، لَا يَضُرُّكَ بِأَيِّهِنَّ بَدَأْتَ، وَلَا."],"takhrij":"صحيح: رواه مسلم في الآداب (2137) عن أحمد بن عبد الله بن يونس، ثنا زهير، ثنا منصور، عن هلال بن يساف، عن ربيع بن عُميلة، عن سمرة بن جندب فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن أحب الكلام إلى اللّٰه أربع: سبحان اللّٰه، والحمد للّٰه، ولا إله إلا اللّٰه، واللّٰه أكبر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Book of Manners (2137).","chapter_en":"The Four Most Beloved Statements to Allah: “Glory Be to Allah,” “All Praise Belongs to Allah,” “There Is No Deity Except Allah,” and “Allah Is the Greatest”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Samurah ibn Jundab narrated that the Messenger of Allah ﷺ said: “The statements most beloved to Allah are four: ‘Glory be to Allah,’ ‘All praise belongs to Allah,’ ‘There is no deity worthy of worship except Allah,’ and ‘Allah is the Greatest.’ It does not matter with which of them you begin.” This forms part of the hadith."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2137)."},{"num":10805,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  لَأَنْ أَقُولَ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللهُ أَكْبَرُ، أَحَبُّ إِلَيَّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ."],"takhrij":"صحيح: رواه مسلم في الذكر والدعاء (2695) من طريق أبي معاوية، عن الأعمش، عن أبي صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن أحب الكلام إلى اللّٰه أربع: سبحان اللّٰه، والحمد للّٰه، ولا إله إلا اللّٰه، واللّٰه أكبر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2695).","chapter_en":"The Four Most Beloved Statements to Allah: “Glory Be to Allah,” “All Praise Belongs to Allah,” “There Is No Deity Except Allah,” and “Allah Is the Greatest”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “To say, ‘Glory be to Allah, all praise belongs to Allah, there is no deity worthy of worship except Allah, and Allah is the Greatest,’ is more beloved to me than everything upon which the sun rises.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2695)."},{"num":10806,"demo":false,"sanad":"","matn":["عَن أَبِي هُرَيْرَة قَالَ: قَالَ رَسُول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خير الْكَلَام أَربع، لَا تبالي بأيتهن بدأت: سُبْحَانَ اللَّهِ، وَالْحَمْد لله، وَلَا إِلَه إِلَّا اللَّهُ، وَالله أَكْبَرُ."],"takhrij":"صحيح: رواه النسائي في عمل اليوم والليلة (841)، وصحّحه ابن حبان (836، 1812) كلاهما من حديث محمد بن علي بن حسن بن شقيق قال: سمعت أبي يقول: أخبرنا أبو حمزة (هو محمد بن ميمون السكري)، عن الأعمش، عن أبي صالح، عن أبي هريرة فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء أن أحب الكلام إلى اللّٰه أربع: سبحان اللّٰه، والحمد للّٰه، ولا إله إلا اللّٰه، واللّٰه أكبر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (841) and Ibn Ḥibbān (836, 1812).","chapter_en":"The Four Most Beloved Statements to Allah: “Glory Be to Allah,” “All Praise Belongs to Allah,” “There Is No Deity Except Allah,” and “Allah Is the Greatest”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The best statements are four, and it does not matter with which of them you begin: ‘Glory be to Allah,’ ‘All praise belongs to Allah,’ ‘There is no deity worthy of worship except Allah,’ and ‘Allah is the Greatest.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه النسائي في عمل اليوم والليلة (841)، وابن حبان (836، 1812)."},{"num":10807,"demo":false,"sanad":"","matn":["عَن بَعْضِ أَصْحَابِ مُحَمَّد صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ رَسُول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: احب الْكَلَام إِلَى اللَّهِ أَربع، لَا يَضُرُّكَ بأيهن بدأت: سُبْحَانَ اللَّهِ، وَالْحَمْد لله، وَلَا إِلَه إِلَّا اللَّهُ، وَالله أَكْبَرُ."],"takhrij":"صحيح: رواه أحمد (16412) عن وكيع،- والنسائي في عمل اليوم والليلة (842) من طريق ابن فضيل- كلاهما عن الأعمش، عن أبي صالح، عن بعض أصحاب النبي صلى الله عليه وسلم فذكره.واللفظ للنسائي، وليس عند أحمد: \"لا يضرك بأيهن بدأت\".","grade":"صحيح","chapter_ar":"باب ما جاء أن أحب الكلام إلى اللّٰه أربع: سبحان اللّٰه، والحمد للّٰه، ولا إله إلا اللّٰه، واللّٰه أكبر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (16412) and al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (842).","chapter_en":"The Four Most Beloved Statements to Allah: “Glory Be to Allah,” “All Praise Belongs to Allah,” “There Is No Deity Except Allah,” and “Allah Is the Greatest”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["One of the Companions of the Prophet ﷺ narrated that the Prophet ﷺ said: “The statements most beloved to Allah are four, and it does not matter with which of them you begin: ‘Glory be to Allah,’ ‘All praise belongs to Allah,’ ‘There is no deity worthy of worship except Allah,’ and ‘Allah is the Greatest.’”"]},"buhuth":{"en":["The unnamed Companion was Abū Hurayrah. Ibn Ḥajar also stated this in Tahdhīb al-Tahdhīb (12/394)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (16412)، والنسائي في عمل اليوم والليلة (842)."},{"num":10808,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خُذُوا جُنَّتَكُمْ. قُلْنَا: يَا رَسُولَ اللَّهِ: مِنْ عَدُوٍّ قَدْ حَضَرَ؟ قَالَ: لَا جُنَّتَكُمْ مِنَ النَّارِ، قُولُوا: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، فَإِنَّهَا يَأْتِينَ يَوْمَ الْقِيَامَةِ مُنْجِيَاتٍ وَمُقَدَّمَاتٍ وَهُنَّ الْبَاقِيَاتُ الصَّالِحَاتُ."],"takhrij":"حسن: رواه الحاكم (1985) عن محمد بن صالح بن هانىء، حدثنا يحيى بن محمد بن يحيى، ثنا أبو عمر حفص بن عمر، ثنا عبد العزيز بن مسلم، ثنا محمد بن عجلان، عن سعيد بن أبي سعيد المقبري، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء أن أحب الكلام إلى اللّٰه أربع: سبحان اللّٰه، والحمد للّٰه، ولا إله إلا اللّٰه، واللّٰه أكبر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ḥākim (1985).","chapter_en":"The Four Most Beloved Statements to Allah: “Glory Be to Allah,” “All Praise Belongs to Allah,” “There Is No Deity Except Allah,” and “Allah Is the Greatest”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Take hold of your shields.” We asked: “O Messenger of Allah, is there an enemy present?” He replied: “No. They are your shields against the Fire. Say: ‘Glory be to Allah, all praise belongs to Allah, there is no deity worthy of worship except Allah, and Allah is the Greatest.’ These statements will come on the Day of Resurrection as rescuers and forerunners, and they are the everlasting righteous deeds.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الحاكم (1985)."},{"num":10809,"demo":false,"sanad":"","matn":["عن أَبِي سَعِيدٍ الْخُدْرِيِّ وَأَبِي هُرَيْرَةَ عَن النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِن اللَّهَ اصْطَفَى من الْكَلَام أَرْبعا: سُبْحَانَ اللَّهِ، وَالْحَمْد لله، وَلَا إِلَه إِلَّا اللَّهُ، وَالله أَكْبَرُ، فَمن قَالَ: سُبْحَانَ اللَّهِ كُتِبَ لَهُ عِشْرُونَ حَسَنَة، وحطت عَنهُ عِشْرُونَ سَيِّئَة، وَمن قَالَ: اللَّهُ أَكْبَرُ فَمثل ذَلِك، وَمن قَالَ: لَا إِلَه إِلَّا اللَّهُ فَمثل ذَلِك، وَمن قَالَ: الْحَمد لله رَبِّ الْعَالَمِينَ من قبل نَفسه، كتب لَهُ ثَلَاثُونَ حَسَنَة، وحطت عَنهُ ثَلَاثُونَ سَيِّئَة."],"takhrij":"صحيح: رواه أحمد (8093، 8012)، والنسائي في عمل اليوم والليلة (840)، وصحّحه الحاكم (1886) كلهم من طريق إسرائيل، عن أبي سنان ضرار بن مرة، عن أبي صالح الحنفي (هو عبد الرحمن بن قيس)، عن أبي سعيد وأبي هريرة فذكراه.","grade":"صحيح","chapter_ar":"باب ما جاء أن أحب الكلام إلى اللّٰه أربع: سبحان اللّٰه، والحمد للّٰه، ولا إله إلا اللّٰه، واللّٰه أكبر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (8012, 8093), al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (840), and al-Ḥākim (1886).","chapter_en":"The Four Most Beloved Statements to Allah: “Glory Be to Allah,” “All Praise Belongs to Allah,” “There Is No Deity Except Allah,” and “Allah Is the Greatest”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī and Abū Hurayrah narrated that the Prophet ﷺ said: “Allah, Mighty and Majestic, has chosen four statements from all speech: ‘Glory be to Allah,’ ‘All praise belongs to Allah,’ ‘There is no deity worthy of worship except Allah,’ and ‘Allah is the Greatest.’ Whoever says, ‘Glory be to Allah,’ will have twenty good deeds recorded for him and twenty evil deeds erased from him. Whoever says, ‘Allah is the Greatest,’ will receive the same. Whoever says, ‘There is no deity worthy of worship except Allah,’ will receive the same. Whoever says on his own initiative, ‘All praise belongs to Allah, Lord of the worlds,’ will have thirty good deeds recorded for him and thirty evil deeds erased from him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (8012، 8093)، والنسائي في عمل اليوم والليلة (840)، والحاكم (1886)."},{"num":10810,"demo":false,"sanad":"","matn":["عَنْ أَبِى ذَرٍّ أَنَّ نَاسًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالُوا لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا رَسُولَ الله ذَهَبَ أَهْلُ الدُّثُورِ بِالأُجُور، يُصَلُّونَ كَمَا نُصَلِّي، وَيَصُومُونَ كَمَا نَصُومُ، وَيَتَصَدَّقُونَ بِفُضُولِ أَمْوَالهمْ.قَالَ:  أَوَلَيْسَ قَدْ جَعَلَ الله لَكُمْ مَا تَصَّدَّقُونَ: إِنَّ بِكُلِّ تَسْبِيحَةٍ صَدَقَةً، وَكُلِّ تَكْبِيرَةٍ صَدَقَةٌ، وَكُلِّ تَحْمِيدَةٍ صَدَقَةٌ، وَكُلِّ تَهْلِيلَةٍ صَدَقَةٌ، وَأَمْرٌ بِالْمَعْرُوفِ صَدَقَةٌ، وَنَهْيٌ عَنْ مُنْكَرٍ صَدَقَةٌ، وَفِي بُضْعِ أَحَدِكُمْ صَدَقَةٌ.قَالُوا يَا رَسُولَ الله، أَيَأْتِي أَحَدُنَا شَهْوَتَهُ وَيَكُونُ لَهُ فِيهَا أَجْرٌ قَالَ: أَرَأَيْتُمْ لَوْ وَضَعَهَا فِي حَرَامٍ أَكَانَ عَلَيْهِ فِيهَا وِزْرٌ؟ فَكَذَلِكَ إِذَا وَضَعَهَا فِى الحَلاَلِ كَانَ لَهُ أَجْرٌ."],"takhrij":"صحيح: رواه مسلم في الزكاة (1006) عن عبد الله بن محمد بن أسماء الضبعي، ثنا مهدي بن ميمون، حدثنا واصل مولى أبي عيينة، عن يحيى بن عقيل، عن يحيى بن يعمر، عن أبي الأسود الديلي، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن أحب الكلام إلى اللّٰه أربع: سبحان اللّٰه، والحمد للّٰه، ولا إله إلا اللّٰه، واللّٰه أكبر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1006).","chapter_en":"The Four Most Beloved Statements to Allah: “Glory Be to Allah,” “All Praise Belongs to Allah,” “There Is No Deity Except Allah,” and “Allah Is the Greatest”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abū Dharr narrated: Some of the Companions of the Prophet ﷺ said: “O Messenger of Allah, the wealthy have taken all the rewards. They pray as we pray, fast as we fast, and give charity from their surplus wealth.” He replied: “Has Allah not provided you with things through which you may give charity? Every declaration of Allah’s glory is charity. Every declaration of His greatness is charity. Every expression of praise is charity. Every declaration that there is no deity except Allah is charity. Commanding what is right is charity. Forbidding what is wrong is charity. Even in the sexual act of one of you there is charity.” They asked: “O Messenger of Allah, does one of us satisfy his desire and receive a reward for it?” He replied: “Tell me: if he were to satisfy it unlawfully, would he not bear a sin? Likewise, when he satisfies it lawfully, he receives a reward.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1006)."},{"num":10811,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، رَضِيَ اللَّهُ عَنْهُ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيْسَ مِنْ نَفْسِ ابْنِ آدَمَ إِلَاّ عَلَيْهَا صَدَقَةٌ فِي كُلِّ يَوْمٍ طَلَعَتْ فِيهِ الشَّمْسُ، قِيلَ: يَا رَسُولَ اللَّهِ، وَمِنْ أَيْنَ لَنَا صَدَقَةٌ نَتَصَدَّقُ بِهَا؟ فَقَالَ: إِنَّ أَبْوَابَ الْخَيْرِ لَكَثِيرَةٌ: التَّسْبِيحُ، وَالتَّحْمِيدُ، وَالتَّكْبِيرُ، وَالتَّهْلِيلُ، وَالأَمْرُ بِالْمَعْرُوفِ، وَالنَّهْيُ عَنِ الْمُنْكَرِ، وَتُمِيطُ الأَذَى عَنِ الطَّرِيقِ، وَتُسْمِعُ الأَصَمَّ، وَتَهْدِي الأَعْمَى، وَتُدِلُّ الْمُسْتَدِلَّ عَلَى حَاجَتِهِ، وَتَسْعَى بِشِدَّةِ سَاقَيْكَ مَعَ اللَّهْفَانِ الْمُسْتَغِيثِ، وَتَحْمِلُ بِشِدَّةِ ذِرَاعَيْكَ مَعَ الضَّعِيفِ، فَهَذَا كُلُّهُ صَدَقَةٌ مِنْكَ عَلَى نَفْسِكَ."],"takhrij":"صحيح: رواه ابن حبان (3377) والبيهقي في الشعب (7212) كلاهما من طريق عبد الله بن وهب، أخبرني عمرو بن الحارث، أن سعيد بن أبي هلال حدّثه عن أبي سعيد المهري، عن أبي ذر، فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء أن أحب الكلام إلى اللّٰه أربع: سبحان اللّٰه، والحمد للّٰه، ولا إله إلا اللّٰه، واللّٰه أكبر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Ḥibbān (3377) and al-Bayhaqī in Shuʿab al-Īmān (7212).","chapter_en":"The Four Most Beloved Statements to Allah: “Glory Be to Allah,” “All Praise Belongs to Allah,” “There Is No Deity Except Allah,” and “Allah Is the Greatest”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abū Dharr narrated that the Messenger of Allah ﷺ said: “Every descendant of Adam is required to give charity on every day upon which the sun rises.” It was asked: “O Messenger of Allah, from where are we to obtain something to give in charity?” He replied: “The avenues of goodness are many: glorifying Allah, praising Allah, declaring Allah’s greatness, declaring that there is no deity except Allah, commanding what is right, forbidding what is wrong, removing something harmful from the road, helping a deaf person hear, guiding a blind person, directing someone seeking guidance to what he needs, rushing with the strength of your legs to assist a distressed person crying for help, and using the strength of your arms to help the weak. All of this is charity that you give on behalf of yourself.”"]}},"tuhfa":{},"full":1,"rep":[4094],"tks":"صحيح: رواه ابن حبان (3377)، والبيهقي في شعب الإيمان (7212)."},{"num":10812,"demo":false,"sanad":"","matn":["عن عَائِشَةَ قَالَتْ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  إِنَّهُ خُلِقَ كُلُّ إِنْسَانٍ مِنْ بَنِي آدَمَ عَلَى سِتِّينَ وَثَلَاثِمِائَةِ مَفْصِلٍ، فَمَنْ كَبَّرَ اللهَ، وَحَمِدَ اللَّهَ، وَهَلَّلَ اللهَ، وَسَبَّحَ اللهَ، وَاسْتَغْفَرَ اللهَ، وَعَزَلَ حَجَرًا عَنْ طَرِيقِ النَّاسِ، أَوْ شَوْكَةً، أَوْ عَظْمًا عَنْ طَرِيقِ النَّاسِ، وَأَمَرَ بِمَعْرُوفٍ، أَوْ نَهَى عَنْ مُنْكَرٍ عَدَدَ تِلْكَ السِّتِّينَ، وَالثَّلَاثِمِائَةِ السُّلَامَى، فَإِنَّهُ يَمْشِي يَوْمَئِذٍ، وَقَدْ زَحْزَحَ نَفْسَهُ عَنِ النَّارِ."],"takhrij":"صحيح: رواه مسلم في الزكاة (1007) عن حسن بن علي الحلواني، حدثنا أبو توبة الربيع بن نافع، حدثنا معاوية يعني ابن سلام، عن زيد، أنه سمع أبا سلام يقول: حدثني عبدالله بن فروخ، أنه سمع عائشة تقول فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء أن أحب الكلام إلى اللّٰه أربع: سبحان اللّٰه، والحمد للّٰه، ولا إله إلا اللّٰه، واللّٰه أكبر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1007).","chapter_en":"The Four Most Beloved Statements to Allah: “Glory Be to Allah,” “All Praise Belongs to Allah,” “There Is No Deity Except Allah,” and “Allah Is the Greatest”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["ʿĀ’ishah narrated that the Messenger of Allah ﷺ said: “Every human being among the children of Adam was created with three hundred and sixty joints. Whoever proclaims Allah’s greatness, praises Allah, declares that there is no deity except Allah, glorifies Allah, seeks Allah’s forgiveness, removes a stone, thorn, or bone from the people’s path, commands what is right, or forbids what is wrong—until these deeds equal the number of those three hundred and sixty joints—will walk through that day having moved himself away from the Fire.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1007)."},{"num":10813,"demo":false,"sanad":"","matn":["عن أنس أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَذَ غُصْنًا، فَنَفَضَهُ فَلَمْ يَنْتَفِضْ، ثُمَّ نَفَضَهُ فَلَمْ يَنْتَفِضْ، ثُمَّ نَفَضَهُ فَانْتَفَضَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللهُ أَكْبَرُ، تَنْفُضُ الْخَطَايَا كَمَا تَنْفُضُ الشَّجَرَةُ وَرَقَهَا."],"takhrij":"حسن: رواه أحمد (12534)، والبخاري في الأدب المفرد (634) كلاهما من طريق عبد الوارث (وهو ابن سعيد) قال: حدثنا أبو ربيعة سنان، حدثنا أنس بن مالك فذكره.وإسناده حسن من أجل أبي ربيعة سنان، وهو ابن ربيعة الباهلي حسن الحديث.","grade":"حسن","chapter_ar":"باب ما جاء أن أحب الكلام إلى اللّٰه أربع: سبحان اللّٰه، والحمد للّٰه، ولا إله إلا اللّٰه، واللّٰه أكبر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (12534) and al-Bukhārī in al-Adab al-Mufrad (634).","chapter_en":"The Four Most Beloved Statements to Allah: “Glory Be to Allah,” “All Praise Belongs to Allah,” “There Is No Deity Except Allah,” and “Allah Is the Greatest”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Anas narrated: The Messenger of Allah ﷺ took hold of a branch and shook it, but its leaves did not fall. He shook it again, but they still did not fall. He then shook it a third time, and its leaves fell. The Messenger of Allah ﷺ said: “The statements ‘Glory be to Allah,’ ‘All praise belongs to Allah,’ ‘There is no deity worthy of worship except Allah,’ and ‘Allah is the Greatest’ shake sins away just as a tree shakes off its leaves.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (12534)، والبخاري في الأدب المفرد (634)."},{"num":10814,"demo":false,"sanad":"","matn":["عَنْ أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ قَالَتْ: مَرَّ بِي ذَاتَ يَوْمٍ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ الله إِنِّي قَدْ كَبِرْتُ وَضَعُفْتُ أَوْ كَمَا قَالَتْ، فَمُرْنِي بِعَمَلٍ أَعْمَلُهُ وَأَنَا جَالِسَةٌ، قَالَ: سَبِّحِي الله مِائَةَ تَسْبِيحَةٍ، فَإِنَّهَا تَعْدِلُ لَكِ مِائَةَ رَقَبَةٍ تُعْتِقِينَهَا مِنْ وَلَدِ إِسْمَاعِيلَ، وَاحْمَدِي الله مِائَةَ تَحْمِيدَةٍ تَعْدِلُ لَكِ مِائَةَ فَرَسٍ مُسْرَجَةٍ مُلْجَمَةٍ تَحْمِلِينَ عَلَيْهَا فِي سَبِيلِ الله ، وَكَبِّرِي الله مِائَةَ تَكْبِيرَةٍ فَإِنَّهَا تَعْدِلُ لَكِ مِائَةَ بَدَنَةٍ مُقَلَّدَةٍ مُتَقَبَّلَةٍ، وَهَلِّلِي الله مِائَةَ تَهْلِيلَةٍ.","قَالَ ابْنُ خَلَفٍ: أَحْسِبُهُ قَالَ: تَمْلَأُ مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ، وَلَا يُرْفَعُ يَوْمَئِذٍ لِأَحَدٍ عَمَلٌ إِلَّا أَنْ يَأْتِيَ بِمِثْلِ مَا أَتَيْتِ بِهِ."],"takhrij":"حسن: رواه أحمد (26911) قال عبد الله: وجدت في كتاب أبي، حدثنا سعيد بن سليمان، قال: حدثنا موسى بن خلف، قال: حدثنا عاصم بن بهدلة، عن أبي صالح، عن أم هانئ بنت أبي طالب قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء أن أحب الكلام إلى اللّٰه أربع: سبحان اللّٰه، والحمد للّٰه، ولا إله إلا اللّٰه، واللّٰه أكبر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (26911), Ibn Mājah (3810), and al-Ḥākim (1/513–514).","chapter_en":"The Four Most Beloved Statements to Allah: “Glory Be to Allah,” “All Praise Belongs to Allah,” “There Is No Deity Except Allah,” and “Allah Is the Greatest”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Umm Hāniʾ bint Abī Ṭālib said: The Messenger of Allah ﷺ passed by me one day, and I said: “O Messenger of Allah, I have grown old and weak”—or words to that effect—“so instruct me in a deed that I can perform while sitting.” He said: “Glorify Allah one hundred times, for it will be equal for you to freeing one hundred slaves from the descendants of Ishmael. Praise Allah one hundred times, for it will be equal for you to providing one hundred saddled and bridled horses to be ridden in the cause of Allah. Proclaim Allah’s greatness one hundred times, for it will be equal for you to offering one hundred garlanded and accepted sacrificial camels. Declare that there is no deity worthy of worship except Allah one hundred times.”","Ibn Khalaf said: I believe he also said: “They will fill what lies between heaven and earth. On that day, no one’s deed will be raised above yours unless he performs the same as you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (26911)، وابن ماجه (3810)، والحاكم (1/513-514)."},{"num":10815,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ قَالَ: قَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الَّذِينَ يَذْكُرُونَ مِنْ جَلَالِ الله مِنْ تَسْبِيحِهِ وَتَحْمِيدِهِ وَتَكْبِيرِهِ وَتَهْلِيلِهِ يَتَعَاطَفْنَ حَوْلَ الْعَرْشِ، لهُنَّ دَوِيٌّ كَدَوِيِّ النَّحْلِ، يُذَكِّرْنَ بِصَاحِبِهِنَّ، أَلَا يُحِبُّ أَحَدُكُمْ أَنْ لَا يَزَالَ لَهُ عِنْدَ الله شَيْءٌ يُذَكِّرُ بِهِ."],"takhrij":"صحيح: رواه أحمد (18362) عن ابن نمير، حدثنا موسى –يعني ابن مسلم الطحّان- عن عون بن عبد الله، عن أبيه أو عن أخيه، عن النعمان بن بشير قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن أحب الكلام إلى اللّٰه أربع: سبحان اللّٰه، والحمد للّٰه، ولا إله إلا اللّٰه، واللّٰه أكبر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (18362) and Ibn Mājah (3809).","chapter_en":"The Four Most Beloved Statements to Allah: “Glory Be to Allah,” “All Praise Belongs to Allah,” “There Is No Deity Except Allah,” and “Allah Is the Greatest”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr narrated that the Messenger of Allah ﷺ said: “The declarations of Allah’s majesty that you utter—glorifying Him, praising Him, proclaiming His greatness, and declaring His oneness—gather around the Throne with a humming sound like the humming of bees, mentioning the person who uttered them. Would one of you not love to have something continually mentioning him in the presence of Allah?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (18362)، وابن ماجه (3809)."},{"num":10816,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الله بْنِ شَدَّادٍ أَنَّ نَفَرًا مِنْ بَنِي عُذْرَةَ ثَلَاثَةً أَتَوا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَسْلَمُوا قَالَ: فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ يَكْفِنِيهِمْ؟ قَالَ طَلْحَةُ: أَنَا، قَالَ: فَكَانُوا عِنْدَ طَلْحَةَ فَبَعَثَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْثًا، فَخَرَجَ أَحَدُهُمْ، فَاسْتُشْهِدَ، قَالَ: ثُمَّ بَعَثَ بَعْثًا فَخَرَجَ فِيهِمْ آخَرُ فَاسْتُشْهِدَ، قَالَ: ثُمَّ مَاتَ الثَّالِثُ عَلَى فِرَاشِهِ.قَالَ طَلْحَةُ: فَرَأَيْتُ هَؤُلَاءِ الثَّلَاثَةَ الَّذِينَ كَانُوا عِنْدِي فِي الجَنَّةِ، فَرَأَيْتُ المَيِّتَ عَلَى فِرَاشِهِ أَمَامَهُمْ، وَرَأَيْتُ الَّذِي اسْتُشْهِدَ أَخِيرًا يَلِيهِ، وَرَأَيْتُ الَّذِي اسْتُشْهِدَ أَوَّلهُمْ آخِرَهُمْ، قَالَ: فَدَخَلَنِي مِنْ ذَلِكَ، قَالَ: فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ ذَلِكَ لَهُ، قَالَ: فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَمَا أَنْكَرْتَ مِنْ ذَلِكَ؟ لَيْسَ أَحَدٌ أَفْضَلَ عِنْدَ الله مِنْ مُؤْمِنٍ يُعَمَّرُ فِي الْإِسْلَامِ لِتَسْبِيحِهِ وَتَكْبِيرِهِ وَتَهْلِيلِهِ."],"takhrij":"حسن: رواه أحمد (1401) عن وكيع، حدثني طلحة بن يحيى بن طلحة، عن إبراهيم بن محمد بن طلحة، عن عبد الله بن شدّاد قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء أن أحب الكلام إلى اللّٰه أربع: سبحان اللّٰه، والحمد للّٰه، ولا إله إلا اللّٰه، واللّٰه أكبر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (1401).","chapter_en":"The Four Most Beloved Statements to Allah: “Glory Be to Allah,” “All Praise Belongs to Allah,” “There Is No Deity Except Allah,” and “Allah Is the Greatest”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullāh ibn Shaddād narrated: Three men from Banū ʿUdhrah came to the Prophet ﷺ and accepted Islam. The Prophet ﷺ asked: “Who will take responsibility for them?” Ṭalḥah replied: “I will.” They therefore stayed with Ṭalḥah. The Prophet ﷺ later dispatched a military expedition. One of the three joined it and was martyred. He then dispatched another expedition, and another of them joined it and was martyred. The third later died upon his bed. Ṭalḥah said: I saw those three men who had stayed with me in Paradise. I saw the one who died upon his bed ahead of the other two. The man who was martyred later was behind him, and the man who had been martyred first was last among them. I was troubled by this, so I went to the Prophet ﷺ and told him what I had seen. The Messenger of Allah ﷺ said: “What do you find objectionable about that? No one is better in the sight of Allah than a believer whose life is prolonged in Islam so that he may continue glorifying Allah, proclaiming His greatness, and declaring His oneness.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (1401)."},{"num":10817,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ، وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهْوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ. فِي يَوْمٍ مِائَةَ مَرَّةٍ، كَانَتْ لَهُ عَدْلَ عَشْرِ رِقَابٍ، وَكُتِبَ لَهُ مِائَةُ حَسَنَةٍ، وَمُحِيَتْ عَنْهُ مِائَةُ سَيِّئَةٍ، وَكَانَتْ لَهُ حِرْزًا مِنَ الشَّيْطَانِ يَوْمَهُ ذَلِكَ، حَتَّى يُمْسِيَ، وَلَمْ يَأْتِ أَحَدٌ بِأَفْضَلَ مِمَّا جَاءَ بِهِ إِلاَّ رَجُلٌ عَمِلَ أَكْثَرَ مِنْهُ."],"takhrij":"متفق عليه: رواه مالك في كتاب القرآن (20) عن سُميّ مولى أبي بكر، عن أبي صالح السمان، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (20), al-Bukhārī (6403), and Muslim (2691).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever says one hundred times in a day, ‘There is no deity worthy of worship except Allah alone, without partner. To Him belongs all sovereignty and all praise, and He has power over all things,’ will receive a reward equal to freeing ten slaves. One hundred good deeds will be recorded for him, one hundred evil deeds will be erased from him, and it will serve as protection from Satan throughout that day until evening. No one will bring anything better than what he has brought except someone who performs more than that.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11210],"tks":"متفق عليه: رواه مالك (20)، والبخاري (6403)، ومسلم (2691)."},{"num":10818,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ أن رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ عَشْرَ مَرَّاتٍ كَانَ كَمَنْ أَعْتَقَ أَرْبَعَةَ أَنْفُسٍ مِنْ وَلَدِ إِسْمَاعِيلَ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6404)، ومسلم في الذكر والدعاء (2693) كلاهما من حديث عمر بن أبي زائدة، عن أبي إسحاق، عن عمرو بن ميمون قال: من قال: لا إله إلا الله...الخ.","grade":"متفق عليه","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6404) and Muslim (2693).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abū Ayyūb narrated that the Messenger of Allah ﷺ said: “Whoever says ten times, ‘There is no deity worthy of worship except Allah alone, without partner. To Him belongs all sovereignty and all praise, and He has power over all things,’ will be like one who freed four people from the descendants of Ishmael.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[5113],"tks":"متفق عليه: رواه البخاري (6404)، ومسلم (2693)."},{"num":10819,"demo":false,"sanad":"","matn":["عَن الْبَرَاءِ قَالَ: قَالَ رَسُول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: من قَالَ: لَا إِلَه إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْملك وَله الْحَمد وَهُوَ عَلَى كُلِّ شَيْء قَدِيرٌ عَشْرَ مَرَّات كن لَهُ عدل نسمَة."],"takhrij":"صحيح: رواه النسائي في عمل اليوم والليلة (125)، وأحمد (18518)، وصحّحه ابن حبان (850)، كلهم من طريق طلحة بن مصرف، عن عبد الرحمن بن عوسجة، عن البراء بن عازب فذكره.","grade":"صحيح","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (125), Aḥmad (18518), and Ibn Ḥibbān (850).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib narrated that the Messenger of Allah ﷺ said: “Whoever says ten times, ‘There is no deity worthy of worship except Allah alone, without partner. To Him belongs all sovereignty and all praise, and He has power over all things,’ will receive a reward equal to freeing one person.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي في عمل اليوم والليلة (125)، وأحمد (18518)، وابن حبان (850)."},{"num":10820,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ قَالَ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ. فِي يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ، وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ."],"takhrij":"متفق عليه: رواه مالك في كتاب القرآن (21) عن سُميّ مولى أبي بكر، عن أبي صالح السمان، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (21), al-Bukhārī (6405), and Muslim (2691).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever says one hundred times in a day, ‘Glory and praise be to Allah,’ will have his sins erased, even if they are as abundant as the foam of the sea.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11206,12994],"tks":"متفق عليه: رواه مالك (21)، والبخاري (6405)، ومسلم (2691)."},{"num":10821,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ، سُبْحَانَ اللَّهِ الْعَظِيمِ، سُبْحَانَ اللَّهِ وَبِحَمْدِهِ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6406)، ومسلم في الذكر والدعاء (2694) كلاهما من طريق ابن فضيل، عن عمارة بن القعقاع، عن أبي زرعة، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6406) and Muslim (2694).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “There are two statements that are light upon the tongue, heavy upon the Scale, and beloved to the Most Merciful: ‘Glory and praise be to Allah; glory be to Allah, the Magnificent.’”"]}},"tuhfa":{},"full":1,"rep":[13497,16228],"tks":"متفق عليه: رواه البخاري (6406)، ومسلم (2694)."},{"num":10822,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَالِكٍ الْأَشْعَرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  الطُّهُورُ شَطْرُ الْإِيمَانِ، وَالْحَمْدُ لِلهِ تَمْلَأُ الْمِيزَانَ، وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلهِ تَمْلَآنِ - أَوْ تَمْلَأُ - مَا بَيْنَ السَّمَاوَاتِ وَالْأَرْضِ، وَالصَّلَاةُ."],"takhrij":"صحيح: رواه مسلم في الطهارة (223)، عن إسحاق بن منصور، ثنا حبان بن هلال، ثنا أبان (هو ابن يزيد العطار)، ثنا يحيى (هو ابن أبي كثير) أن زيدا حدثه أن أبا سلام حدثه عن أبي مالك الأشعري فذكره.","grade":"صحيح","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (223).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abū Mālik al-Ashʿarī narrated that the Messenger of Allah ﷺ said: “Purification is half of faith. ‘All praise belongs to Allah’ fills the Scale. ‘Glory be to Allah’ and ‘All praise belongs to Allah’ fill—or together fill—what lies between the heavens and the earth…” This forms part of the hadith."]}},"tuhfa":{},"full":1,"dr":1,"rep":[16229],"tks":"صحيح: رواه مسلم (223)."},{"num":10823,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ: أَيُّ الْكَلَامِ أَفْضَلُ؟ قَالَ: مَا اصْطَفَى اللهُ لِمَلَائِكَتِهِ، أَوْ لِعِبَادِهِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ."],"takhrij":"صحيح: رواه مسلم في الذكر والدعاء (2731) عن زهير بن حرب، حدثنا حبان بن هلال، حدثنا وهيب، حدثنا الجريري، عن أبي عبد الله الجسري، عن ابن الصامت (هو عبد الله)، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2731).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abū Dharr narrated that the Messenger of Allah ﷺ was asked: “Which statement is best?” He replied: “The statement Allah chose for His angels—or for His servants: ‘Glory and praise be to Allah.’”"]}},"tuhfa":{},"full":1,"rep":[11897,13172],"tks":"صحيح: رواه مسلم (2731)."},{"num":10824,"demo":false,"sanad":"","matn":["عن عائشة قالت: كان رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يكثر من قول: سبحان الله وبحمده أستغفر الله وأتوب إليه قالت: فقلت: يا رسول الله أراك تكثر من قول: سبحان الله وبحمده أستغفر الله وأتوب إليه؟ فقال: خبرني ربي أني سأرى علامة في أمتي فإذا رأيتها أكثرت من قول سبحان الله وبحمده أستغفر الله وأتوب إليه فقد رأيتها إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ (1) فتح مكة ﴿وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا (2) فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا (3)﴾ [سورة النصر: 2، 3]. "],"takhrij":"صحيح: رواه مسلم في الصلاة (484: 220) عن محمد بن المثنى، حدثني عبدالأعلى، حدثنا داود، عن عامر، عن مسروق، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Book of Prayer (484/220).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["ʿĀ’ishah, the wife of the Prophet ﷺ, said: The Messenger of Allah ﷺ frequently used to say: “Glory and praise be to Allah. I seek Allah’s forgiveness and repent to Him.” I asked: “O Messenger of Allah, I see that you frequently say, ‘Glory and praise be to Allah. I seek Allah’s forgiveness and repent to Him.’” He replied: “My Lord informed me that I would see a sign within my nation. When I saw it, I was to frequently say: ‘Glory and praise be to Allah. I seek Allah’s forgiveness and repent to Him.’ I have now seen it: ‘When the victory of Allah and the conquest come’—meaning the conquest of Makkah— ‘and you see the people entering the religion of Allah in multitudes, then glorify your Lord with praise and seek His forgiveness. Indeed, He is ever accepting of repentance.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (484: 220)."},{"num":10825,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَبْلَ أَنْ يَمُوتَ يُكْثِرُ أَنْ يَقُولَ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. قُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي أَرَاكَ تَكْثُرُ قَوْلَ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ قَالَ: إِنَّى أُمِرْتُ بِأَمْرٍ، فَقَرَأَ: إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ."],"takhrij":"صحيح: رواه الطبراني في الأوسط (1223-مجمع البحرين) عن عبد الرحمن بن سلم أبي يحيى الرازي، ثنا سهل بن عثمان، حدثنا حفص بن غياث، عن عاصم الأحول، عن الشعبي، عن أم سلمة فذكرته.","grade":"صحيح","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (1223), as cited in Majmaʿ al-Baḥrayn.","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, said: Before his death, the Prophet ﷺ frequently used to say: “Glory and praise be to You, O Allah. I seek Your forgiveness and repent to You.” I asked: “O Messenger of Allah, I see that you frequently say, ‘Glory and praise be to You, O Allah. I seek Your forgiveness and repent to You.’” He replied: “I have been commanded to do so.” He then recited: “When the victory of Allah and the conquest come.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الأوسط (1223)، كما في مجمع البحرين."},{"num":10826,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بن أَبِي وَقَّاصٍ قَالَ كُنَّا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَيَعْجِزُ أَحَدُكُمْ أَنْ يَكْسِبَ كُلَّ يَوْمٍ أَلْفَ حَسَنَةٍ؟ فَسَأَلَهُ سَائِلٌ مِنْ جُلَسَائِهِ: كَيْفَ يَكْسِبُ أَحَدُنَا أَلْفَ حَسَنَةٍ؟ قَالَ: يُسَبِّحُ مِائَةَ تَسْبِيحَةٍ، فَيُكْتَبُ لَهُ أَلْفُ حَسَنَةٍ، أَوْ يُحَطُّ عَنْهُ أَلْفُ خَطِيئَةٍ."],"takhrij":"صحيح: رواه مسلم في الذكر والدعاء (2698) من طريق موسى الجهني، عن مصعب بن سعد، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2698).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ said: We were with the Messenger of Allah ﷺ when he asked: “Is one of you incapable of earning one thousand good deeds every day?” One of those sitting with him asked: “How can one of us earn one thousand good deeds?” He replied: “He glorifies Allah one hundred times, so one thousand good deeds are recorded for him, or one thousand sins are erased from him.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2698)."},{"num":10827,"demo":false,"sanad":"","matn":["عن سَعْدِ بن أَبِي وَقَّاصٍ قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: عَلِّمْنِي كَلَامًا أَقُولُهُ؟ قَالَ: قُلْ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، آللَّهُ أَكْبَرُ كَبِيرًا، وَالْحَمْدُ لِلهِ كَثِيرًا، سُبْحَانَ اللَّهِ رَبِّ الْعَالَمِينَ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ الْعَزِيزِ الْحَكِيمِ قَالَ: فَهَؤُلَاءِ لِرَبِّي فَمَا لِي؟ قَالَ: قُلِ: اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَارْزُقْنِي."],"takhrij":"صحيح: رواه مسلم في الذكر والدعاء (2696) من طريق موسى الجهني، عن مصعب بن سعد، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2696).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ narrated: A Bedouin came to the Messenger of Allah ﷺ and said: “Teach me words that I may say.” He replied: “Say: ‘There is no deity worthy of worship except Allah alone, without partner. Allah is supremely great. Abundant praise belongs to Allah. Glory be to Allah, Lord of the worlds. There is no power and no strength except through Allah, the Almighty, the All-Wise.’” The man said: “These are for my Lord. What is there for me?” He replied: “Say: ‘O Allah, forgive me, have mercy upon me, guide me, and provide for me.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2696)."},{"num":10828,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  أَلَا أُخْبِرُكَ بِأَحَبِّ الْكَلَامِ إِلَى اللَّهِ؟ قُلْتُ: يَا رَسُولَ اللَّهِ أَخْبِرْنِي بِأَحَبِّ الْكَلَامِ إِلَى اللَّهِ فَقَالَ: إِنَّ أَحَبَّ الْكَلَامِ إِلَى اللَّهِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ."],"takhrij":"صحيح: رواه مسلم في الذكر والدعاء (2731: 85) عن أبي بكر بن أبي شيبة، ثنا يحيى بن أبي بكير، عن شعبة، عن الجريري، عن أبي عبد الله الجسري –من عنزة- عن عبد الله بن الصامت، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2731/85).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abū Dharr narrated that the Messenger of Allah ﷺ said: “Shall I tell you the words most beloved to Allah?” I replied: “O Messenger of Allah, tell me the words most beloved to Allah.” He said: “The words most beloved to Allah are: ‘Glory and praise be to Allah.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2731: 85)."},{"num":10829,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  مَرَّ بِهِ وَهُوَ يُحَرِّكُ شَفَتَيْهِ فَقَالَ: مَاذَا تَقُولُ يَا أَبَا أُمَامَةَ؟ قَالَ: أَذْكُرُ رَبِّي قَالَ: ألَا أُخْبِرُكَ بِأَفْضَلَ أَوْ أَكْثَرَ مِنْ ذِكْرِكَ اللَّيْلِ مَعَ النَّهَارِ وَالنَّهَارِ مَعَ اللَّيْلِ، أَنْ تَقُولَ: سُبْحَانَ اللهِ عَدَدَ مَا خَلَقَ، سُبْحَانَ اللهِ مِلْءَ مَا خَلَقَ، سُبْحَانَ اللهِ عَدَدَ مَا فِي الْأَرْضِ وَالسَّمَاءِ، سُبْحَانَ اللهِ مِلْءَ مَا فِي السَّمَاءِ وَالْأَرْضِ، سُبْحَانَ اللهِ مِلْءَ مَا خَلَقَ، سُبْحَانَ اللهِ عَدَدَ مَا أَحْصَى كِتَابُهُ، وَسُبْحَانَ اللهِ مِلْءَ كُلِّ شَيْءٍ، وَتَقُولُ: الْحَمْدُ لِلَّهِ مِثْلَ ذَلِكَ."],"takhrij":"حسن: رواه النسائي في عمل اليوم والليلة (166)، وصحّحه ابن خزيمة (754)، -وعنه ابن حبان (830)- كلاهما من طريق ابن أبي مريم قال: أخبرنا يحيى بن أيوب، حدثني ابن عجلان، عن مصعب بن محمد بن شرحبيل، عن محمد بن سعد بن زرارة، عن أبي أمامة الباهلي فذكره.","grade":"حسن","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (166), Ibn Khuzaymah (754), and from him by Ibn Ḥibbān (830).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abū Umāmah al-Bāhilī narrated: The Messenger of Allah ﷺ passed by him while his lips were moving and asked: “What are you saying, O Abū Umāmah?” He replied: “I am remembering my Lord.” He said: “Shall I not tell you something more abundant—or more excellent—than your remembrance throughout the night and day? Say: ‘Glory be to Allah according to the number of everything He created. Glory be to Allah filling everything He created. Glory be to Allah according to the number of everything in the earth and heaven. Glory be to Allah filling everything in the earth and heaven. Glory be to Allah according to the number of everything His Book has recorded. Glory be to Allah according to the number of all things. Glory be to Allah filling all things.’ Then say the same using: ‘All praise belongs to Allah.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في عمل اليوم والليلة (166)، وابن خزيمة (754)، وعنه ابن حبان (830)."},{"num":10830,"demo":false,"sanad":"","matn":["عَن أنس قَالَ: كُنْتُ جَالِسا مَعَ رَسُول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْحَلْقَةِ إِذْ جَاءَ رَجُلٌ فَسَلَّمَ عَلَى النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَى الْقَوْم، فَقَالَ: السَّلَام عَلَيْكُم، فَرد عَلَيْهِ النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَعَلَيْكُم السَّلَام وَرَحْمَة اللَّهِ وَبَرَكَاته فَلَمَّا جَلَسَ الرَّجُلُ قَالَ: الْحَمد لله حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ كَمَا يحب رَبنَا وَيَرْضَى فَقَالَ لَهُ النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَيفَ قُلْتَ فردّ على النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَمَا قَالَ، فَقَالَ النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَالَّذِي نَفسِي بِيَدِهِ لَقَدْ ابْتَدَرَهَا عشرَة أَمْلَاك كلهم حَرِيص على أَن يكتبوها، فبادروا كَيفَ يكتبونها حَتَّى رَفَعُوهُ إِلَى ذِي الْعِزَّة (فَقَالَ): آاكتبوها كَمَا قَالَ عَبدِي."],"takhrij":"حسن: رواه النسائيّ في عمل اليوم والليلة (341) وصحّحه ابن حبان (845)، والضياء في المختارة (1887) كلهم من حديث قتيبة بن سعيد، قال: حدّثنا خلف، عن ابن أخي أنس، عن أنس، فذكره.","grade":"حسن","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (341), and authenticated by Ibn Ḥibbān (845).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Anas said: I was sitting with the Messenger of Allah ﷺ in a gathering when a man came and greeted the Prophet ﷺ and the people, saying: “Peace be upon you.” The Prophet ﷺ replied: “And peace, the mercy of Allah, and His blessings be upon you.” When the man sat down, he said: “All praise belongs to Allah—abundant, pure, and blessed praise—as our Lord loves and is pleased with.” The Prophet ﷺ asked him: “What did you say?” The man repeated what he had said. The Prophet ﷺ then said: “By the One in Whose Hand is my soul, ten angels rushed toward those words, each eager to record them. They differed over how they should write them until they raised them to the Possessor of Might, who said: ‘Write them exactly as My servant said them.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10782],"tks":"حسن: رواه النسائي في عمل اليوم والليلة (341)، وصححه ابن حبان (845)."},{"num":10831,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلا أُعَلِّمُكَ كَلِمَاتٍ إِذَا قُلْتَهُنَّ غُفِرَ لَكَ، عَلَى أَنَّهُ مَغْفُورٌ لَكَ؟ لَا إِلَهَ إِلا اللَّهُ الْعَلِيُّ الْعَظِيمُ، لَا إِلَهَ إِلا هُوَ الْحَلِيمُ الْكَرِيمُ، سُبْحَانَ اللَّهِ رَبِّ الْعَرْشِ الْعَظِيمِ، الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ."],"takhrij":"صحيح: رواه أحمد (1363)، والنسائي في عمل اليوم والليلة (637) كلاهما من طريق إسرائيل، عن أبي إسحاق، عن عبد الرحمن بن أبي ليلى، عن علي فذكره.","grade":"صحيح","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (1363) and al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (637).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["ʿAlī narrated that the Messenger of Allah ﷺ said: “Shall I teach you words which, if you say them, you will be forgiven—although you are already forgiven? ‘There is no deity worthy of worship except Allah, the Most High, the Magnificent. There is no deity worthy of worship except Allah, the Forbearing, the Generous. Glory be to Allah, Lord of the Magnificent Throne. All praise belongs to Allah, Lord of the worlds.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (1363)، والنسائي في عمل اليوم والليلة (637)."},{"num":10832,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا عَلَى الأَرْضِ أَحَدٌ يَقُولُ: لاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ. إِلاَّ كُفِّرَتْ عَنْهُ خَطَايَاهُ وَلَوْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ."],"takhrij":"حسن: رواه الترمذي (3460)، والنسائي في عمل اليوم والليلة (124)، والحاكم (1853) كلهم من طريق حاتم بن أبي صغيرة، عن أبي بلج، عن عمرو ميمون، عن عبدالله بن عمرو فذكره مرفوعا.","grade":"حسن","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3460) and al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (124).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated that the Messenger of Allah ﷺ said: “No one upon the earth says, ‘There is no deity worthy of worship except Allah, Allah is the Greatest, and there is no power and no strength except through Allah,’ except that his sins are expiated, even if they are as abundant as the foam of the sea.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3460)، والنسائي في عمل اليوم والليلة (124)."},{"num":10833,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَفْضَلُ الذِّكْرِ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَفْضَلُ الدُّعَاءِ الْحَمْدُ لِلَّهِ."],"takhrij":"حسن: رواه الترمذي (3383)، وابن ماجه (3800)، وصحّحه ابن حبان (846)، والحاكم (1/498، و503) كلهم من طريق موسى بن إبراهيم بن كثير الأنصاري قال: سمعت طلحة بن خراش قال: سمعت جابر بن عبد الله فذكره.","grade":"حسن","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3383) and Ibn Mājah (3800), and authenticated by Ibn Ḥibbān (846).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: I heard the Messenger of Allah ﷺ say: “The best remembrance is: ‘There is no deity worthy of worship except Allah,’ and the best supplication is: ‘All praise belongs to Allah.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3383)، وابن ماجه (3800)، وصححه ابن حبان (846)."},{"num":10834,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ قَالَ: سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ. غُرِسَتْ لَهُ نَخْلَةٌ فِي الْجَنَّةِ."],"takhrij":"حسن: رواه الترمذي (3464، 3465)، والنسائي في عمل اليوم والليلة (827)، وصحّحه ابن حبان (826، 827)، والحاكم (1/501، 512) كلهم من طرق عن أبي الزبير، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3464, 3465), al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (827), and Ibn Ḥibbān (826, 827).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that the Prophet ﷺ said: “Whoever says, ‘Glory and praise be to Allah, the Magnificent,’ a palm tree will be planted for him in Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13498],"tks":"حسن: رواه الترمذي (3464، 3465)، والنسائي في عمل اليوم والليلة (827)، وابن حبان (826، 827)."},{"num":10835,"demo":false,"sanad":"","matn":["عن أَبِي سلمى راعي رسول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: بَخٍ بَخٍ، وَأَشَارَ بِيَدِهِ بِخَمْسٍ مَا أَثْقَلَهُنَّ فِي الْمِيزَانِ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ للهِ، وَلَا إِلَهَ إِلَاّ اللَّهُ، وَاللهُ أَكْبَرُ، وَالْوَلَدُ الصَّالِحُ يُتَوَفَّى لِلْمَرْءِ الْمُسْلِمِ فَيَحْتَسِبُهُ."],"takhrij":"صحيح: رواه النسائي في عمل اليوم والليلة (167)، وابن أبي عاصم في السنة (800)، وصحّحه ابن حبان (833)، والحاكم (1885) كلهم من طريق الوليد بن مسلم قال: حدثنا عبد الله بن العلاء بن زبر وعبد الرحمن بن يزيد بن جابر قالا: حدثنا أبو سلام الأسود، حدثني أبو سلمى راعي رسول الله صلى الله عليه وسلم فذكره.إلا أنه ليس في إسناد الحاكم ذكر عبد الله بن العلاء.","grade":"صحيح","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (167) and Ibn Abī ʿĀṣim in al-Sunnah (800).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abū Salmā, the shepherd of the Messenger of Allah ﷺ, said: I heard the Messenger of Allah ﷺ say: “Excellent! Excellent!” He gestured with his hand to indicate five and said: “How heavy these five are upon the Scale: ‘Glory be to Allah,’ ‘All praise belongs to Allah,’ ‘There is no deity worthy of worship except Allah,’ ‘Allah is the Greatest,’ and the death of a righteous child whose Muslim parent patiently seeks the reward from Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي في عمل اليوم والليلة (167)، وابن أبي عاصم في السنة (800)."},{"num":10836,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: من لقيت يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ مُسْتَيْقِنًا بِهَا قَلْبُهُ بَشَّرَهُ بِالْجَنَّةِ.فضربه عمر بِيَدِهِ وَقَالَ: ارْجِعْ.فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا عُمَرُ مَا حَمَلَكَ عَلَى مَا فَعَلْتَ؟ قَالَ يَا رَسُولَ اللَّهِ، بِأَبِي أَنْتَ وَأُمِّي، أَبَعَثْتَ أَبَا هُرَيْرَةَ بِنَعْلَيْكَ مَنْ لَقِيَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ مُسْتَيْقِنًا بِهَا قَلْبُهُ بَشَّرَهُ بِالْجَنَّةِ ؟ قَالَ: نَعَمْ قَالَ: فَلَا تَفْعَلْ، فَإِنِّي أَخْشَى أَنْ يَتَّكِلَ النَّاسُ عَلَيْهَا، فَخَلِّهِمْ يَعْمَلُونَ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَخَلِّهِمْ."],"takhrij":"صحيح: رواه مسلم في الإيمان (31) عن زهير بن حرب حدثنا عمر بن يونس الحنفي حدثنا عكرمة بن عمار قال حدثني أبو كثير قال حدثني أبو هريرة فذكره.","grade":"صحيح","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Book of Faith (31).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah narrated: The Messenger of Allah ﷺ said to me: “Whoever you meet who testifies that there is no deity worthy of worship except Allah with certainty in his heart, give him the glad tidings of Paradise.” ʿUmar struck him with his hand and said: “Go back.” The Messenger of Allah ﷺ asked him: “O ʿUmar, what caused you to do that?” He replied: “O Messenger of Allah, may my father and mother be sacrificed for you! Did you send Abū Hurayrah with your sandals and command him to give the glad tidings of Paradise to anyone he met who testified that there is no deity worthy of worship except Allah with certainty in his heart?” He said: “Yes.” ʿUmar said: “Do not do so, for I fear that the people will rely upon it and abandon righteous deeds. Leave them to continue working.” The Messenger of Allah ﷺ said: “Then leave them.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (31)."},{"num":10837,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: نَادِ فِي النَّاسِ: مَنْ قَالَ: لَا إِلَهَ إِلَاّ اللَّهُ دَخَلَ الْجَنَّةَ، فَخَرَجَ فَلَقِيَهُ عُمَرُ فِي الطَّرِيقِ، فَقَالَ: أَيْنَ تُرِيدُ؟ قُلْتُ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِكَذَا وَكَذَا، قَالَ: ارْجِعْ، فَأَبَيْتُ، فَلَهَزَنِي لَهْزَةً فِي صَدْرِي آلَمَتْهَا، فَرَجَعْتُ، وَلَمْ أَجِدْ بُدًّا، قَالَ: يَا رَسُولَ اللَّهِ، بَعَثْتَ هَذَا بِكَذَا وَكَذَا؟ قَالَ: نَعَمْ، قَالَ: يَا رَسُولَ اللَّهِ، إِنَّ النَّاسَ قَدْ طَمِعُوا وَخَشُوا، فَقَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اقْعُدْ."],"takhrij":"حسن: رواه ابن خزيمة (693)، وابن حبان (151) كلاهما من طريق المحرر ابن قعنب الباهلي، قال: حدثني رباح بن عبيدة، أن ذكوان السمان حدّثه، أن جابر ابن عبدالله حدّثه وقال (فذكره)، واللفظ لابن حبان.","grade":"حسن","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Khuzaymah (693) and Ibn Ḥibbān (151).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Jābir narrated: The Messenger of Allah ﷺ sent me and said: “Proclaim among the people: ‘Whoever says that there is no deity worthy of worship except Allah will enter Paradise.’” I went out and met ʿUmar on the road. He asked: “Where are you going?” I replied: “The Messenger of Allah ﷺ sent me with such-and-such a message.” He said: “Go back.” I refused, so he pushed me firmly in the chest. I returned, having no alternative. ʿUmar asked: “O Messenger of Allah, did you send this man with such-and-such a message?” He replied: “Yes.” ʿUmar said: “O Messenger of Allah, the people have become hopeful and afraid.” The Prophet ﷺ then said to Jābir: “Sit down.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (693)، وابن حبان (151)."},{"num":10838,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرِ بْنِ أَبِي مُوسَى، عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَبْشِرُوا وَبَشِّرُوا النَّاسَ. مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ صَادِقًا بِهَا دَخَلَ الْجَنَّةَ. فَخَرَجُوا يُبَشِّرُونَ النَّاسَ، فَلَقِيَهُمْ عُمَرُ، رَضِيَ اللَّهُ عَنْهُ فَبَشَّرُوهُ، فَرَدَّهُمْ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ رَدَّكُمْ؟ قَالُوا: عُمَرُ. قَالَ: لِمَ رَدَدْتَهُمْ يَا عُمَرُ؟ قَالَ: إِذًا يَتَّكِلَ النَّاسُ يَا رَسُولَ اللَّهِ."],"takhrij":"صحيح: رواه أحمد (19689)، والطحاوي في شرح المشكل (4003) كلاهما من طريق حماد بن سلمة، حدثنا أبو عمران الجوني، عن أبي بكر بن أبي موسى، عن أبيه فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (19689) and al-Ṭaḥāwī in Sharḥ Mushkil al-Āthār (4003).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abū Bakr ibn Mūsā narrated from his father that the Messenger of Allah ﷺ said: “Receive glad tidings and give the people glad tidings: whoever sincerely says, ‘There is no deity worthy of worship except Allah,’ will enter Paradise.” They went out to give the people the glad tidings and met ʿUmar. They informed him, but he sent them back. The Messenger of Allah ﷺ asked: “Who sent you back?” They replied: “ʿUmar.” He asked: “Why did you send them back, O ʿUmar?” He replied: “Otherwise, the people would rely upon this alone, O Messenger of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (19689)، والطحاوي في شرح مشكل الآثار (4003)."},{"num":10839,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا قَالَ عَبْدٌ لاَ إِلَهَ إِلاَّ اللَّهُ قَطُّ مُخْلِصًا إِلاَّ فُتِحَتْ لَهُ أَبْوَابُ السَّمَاءِ حَتَّى تُفْضِيَ إِلَى الْعَرْشِ مَا اجْتَنَبَ الْكَبَائِرَ."],"takhrij":"حسن: رواه الترمذي (3590)، والنسائي في عمل اليوم والليلة (833) كلاهما عن الحسين بن على بن يزيد الصدائي البغدادي، حدثنا الوليد بن القاسم بن الوليد الهمدانى، عن يزيد بن كيسان (هو اليشكري)، عن أبى حازم (وهو سليمان الأشجعي)، عن أبى هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3590) and al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (833).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “No servant ever sincerely says, ‘There is no deity worthy of worship except Allah,’ except that the gates of heaven are opened for it until it reaches the Throne, provided that he avoids the major sins.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3590)، والنسائي في عمل اليوم والليلة (833)."},{"num":10840,"demo":false,"sanad":"","matn":["عن عبدالله بن مسعود قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ أَحَبَّ الْكَلَامِ إِلَى الله أَنْ يَقُولَ الْعَبْدُ: سُبْحَانَكَ اللهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلَهَ غَيْرَكَ، وَإِنَّ أَبْغَضَ الْكَلَامِ إِلَى الله أَنْ يَقُولَ الرَّجُلُ لِلرَّجُلِ: اتَّقِ الله، فَيَقُولُ: عَلَيْكَ نَفْسَكَ."],"takhrij":"صحيح: رواه النسائي في عمل اليوم والليلة (849)، والبيهقي في الشعب (621)، وفي الدعوات الكبير (156) كلاهما من طريق محمد بن سعيد بن الأصبهاني، حدثنا أبو معاوية، عن الأعمش، عن إبراهيم التيمي، عن الحارث بن سويد، عن عبدالله (هو ابن مسعود) قال: فذكره.","grade":"صحيح","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (849) and al-Bayhaqī in Shuʿab al-Īmān (621).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “The speech most beloved to Allah is for the servant to say: ‘Glory and praise be to You, O Allah. Blessed is Your name, exalted is Your majesty, and there is no deity other than You.’ The speech most detested by Allah is for one man to say to another, ‘Fear Allah,’ and for him to reply, ‘Concern yourself with your own affairs.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي في عمل اليوم والليلة (849)، والبيهقي في شعب الإيمان (621)."},{"num":10841,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَقَالَ: يَا رَسُولَ اللهِ، عَلِّمْنِي خَيْرًا فَأَخَذَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  بِيَدِهِ فَقَالَ: قُلْ: سُبْحَانَ اللهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللهُ، وَاللهُ أَكْبَرُ.","قَالَ: فَعَقَدَ الْأَعْرَابِيُّ عَلَى يَدِهِ، ثُمَّ مَضَى فَتَفَكَّرَ ثُمَّ رَجَعَ، فَتَبَسَّمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  وَقَالَ: تَفَكَّرَ الْبَائِسُ. فَجَاءَ فَقَالَ: يَا رَسُولَ اللهِ، سُبْحَانَ اللهِ وَالْحَمْدُ لِلهِ وَلَا إِلَهَ إِلَّا اللهُ وَاللهُ أَكْبَرُ، هَذِهِ لِلهِ، فَمَا لِي؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : يَا أَعْرَابِيُّ، إِذَا قُلْتَ سُبْحَانَ اللهِ، قَالَ اللهُ: صَدَقْتَ، وَإِذَا قُلْتَ: الْحَمْدُ لِلهِ، قَالَ اللهُ: صَدَقْتَ، وَإِذَا قُلْتَ: لَا إِلَهَ إِلَّا اللهُ، قَالَ اللهُ: صَدَقْتَ، وَإِذَا قُلْتَ: اللهُ أَكْبَرُ، قَالَ اللهُ: صَدَقْتَ، فَإِذَا قُلْتَ: اللَّهُمَّ اغْفِرْ لِي، قَالَ اللهُ: فَعَلْتُ، فَإِذَا قُلْتَ: اللَّهُمَّ ارْحَمْنِي، قَالَ اللهُ: فَعَلْتُ، وَإِذَا قُلْتَ: اللَّهُمَّ ارْزُقْنِي، قَالَ اللهُ: قَدْ فَعَلْتُ. قَالَ: فَعَقَدَ الْأَعْرَابِيُّ عَلَى سَبْعٍ فِي يَدِهِ، ثُمَّ وَلَّى."],"takhrij":"حسن: رواه أبو جعفر ابن البختري محمد بن عمرو في جزئه (21) –مجموع فيه مصنفات أبي جعفر بن البختري- من طريقه البيهقي في الشعب (610)- عن الحسن بن ثواب أبو علي، حدثني عمار بن عثمان الحلبي أبو عثمان، حدثني جعفر بن سليمان الضبعي، عن ثابت، عن أنس قال: فذكره.","grade":"حسن","chapter_ar":"باب فضل التهليل والتسبيح والتحميد والتكبير عمومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Jaʿfar Ibn al-Bakhtarī, Muḥammad ibn ʿAmr, in his Juzʾ (21), and through him by al-Bayhaqī in Shuʿab al-Īmān (610).","chapter_en":"The General Virtue of Declaring Allah’s Oneness, Glorifying Him, Praising Him, and Proclaiming His Greatness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Mālik narrated: A Bedouin came to the Prophet ﷺ and said: “O Messenger of Allah, teach me something good.” The Prophet ﷺ took him by the hand and said: “Say: ‘Glory be to Allah, all praise belongs to Allah, there is no deity worthy of worship except Allah, and Allah is the Greatest.’” The Bedouin counted these statements upon his fingers and departed. He then reflected and returned. The Prophet ﷺ smiled and said: “The poor man has been thinking.”","The Bedouin came and said: “O Messenger of Allah, ‘Glory be to Allah, all praise belongs to Allah, there is no deity worthy of worship except Allah, and Allah is the Greatest’—these are for Allah. What is there for me?” The Prophet ﷺ replied: “O Bedouin, when you say, ‘Glory be to Allah,’ Allah says: ‘You have spoken the truth.’ When you say, ‘All praise belongs to Allah,’ Allah says: ‘You have spoken the truth.’ When you say, ‘There is no deity worthy of worship except Allah,’ Allah says: ‘You have spoken the truth.’ When you say, ‘Allah is the Greatest,’ Allah says: ‘You have spoken the truth.’ When you say, ‘O Allah, forgive me,’ Allah says: ‘I have done so.’ When you say, ‘O Allah, have mercy upon me,’ Allah says: ‘I have done so.’ When you say, ‘O Allah, provide for me,’ Allah says: ‘I have done so.’” The Bedouin counted seven statements upon his fingers and then departed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو جعفر ابن البختري محمد بن عمرو في جزئه (21)، ومن طريقه البيهقي في شعب الإيمان (610)."},{"num":10842,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا غَزَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ ـ أَوْ قَالَ: لَمَّا تَوَجَّهَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ـ أَشْرَفَ النَّاسُ عَلَى وَادٍ، فَرَفَعُوا أَصْوَاتَهُمْ بِالتَّكْبِيرِ: اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، لاَ إِلَهَ إِلاَّ اللَّهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ارْبَعُوا عَلَى أَنْفُسِكُمْ، إِنَّكُمْ لاَ تَدْعُونَ أَصَمَّ وَلاَ غَائِبًا، إِنَّكُمْ تَدْعُونَ سَمِيعًا قَرِيبًا وَهْوَ مَعَكُمْ. وَأَنَا خَلْفَ دَابَّةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَمِعَنِي وَأَنَا أَقُولُ: لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ، فَقَالَ لِي: يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ. قُلْتُ: لَبَّيْكَ رَسُولَ اللَّهِ. قَالَ: أَلاَ أَدُلُّكَ عَلَى كَلِمَةٍ مِنْ كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ. قُلْتُ: بَلَى يَا رَسُولَ اللَّهِ، فِدَاكَ أَبِي وَأُمِّي. قَالَ: لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4202)، ومسلم في الذكر والدعاء (2704) كلاهما من طريق عاصم (هو الأحول)، عن أبي عثمان (هو النهدي)، عن أبي موسى الأشعري فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل لا حول ولا قوة إلا باللّٰه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4202) and Muslim (2704).","chapter_en":"The Virtue of Saying: “There Is No Power and No Strength Except through Allah”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī narrated: When the Messenger of Allah ﷺ fought at Khaybar—or when he set out toward it—the people came upon a valley and raised their voices, proclaiming: “Allah is the Greatest! Allah is the Greatest! There is no deity worthy of worship except Allah!” The Messenger of Allah ﷺ said: “Be gentle with yourselves. You are not calling upon one who is deaf or absent. You are calling upon One who hears, who is near, and who is with you.” I was behind the mount of the Messenger of Allah ﷺ, and he heard me saying: “There is no power and no strength except through Allah.” He said: “O ʿAbdullāh ibn Qays.” I replied: “At your service, O Messenger of Allah.” He said: “Shall I direct you to a phrase that is one of the treasures of Paradise?” I replied: “Certainly, O Messenger of Allah. May my father and mother be sacrificed for you.” He said: “There is no power and no strength except through Allah.”"]}},"tuhfa":{},"full":1,"rep":[9039],"tks":"متفق عليه: رواه البخاري (4202)، ومسلم (2704)."},{"num":10843,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلاَ أَدُلُّكَ عَلَى كنـز مِنْ كُنُوزِ الْجَنَّةِ؟ قُلْتُ: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: لاَ حَوْلَ وَ لاَ قُوَّةَ إِلاَّ بِاللَّهِ."],"takhrij":"صحيح: رواه ابن ماجه (3825)، والنسائي في عمل اليوم والليلة (43)، وأحمد (21346) كلهم من طريق سليمان الأعمش، عن مجاهد، عن عبد الرحمن بن أبي ليلى، عن أبي ذر فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب فضل لا حول ولا قوة إلا باللّٰه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (3825), al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (43), and Aḥmad (21346).","chapter_en":"The Virtue of Saying: “There Is No Power and No Strength Except through Allah”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abū Dharr narrated that the Prophet ﷺ said: “Shall I direct you to one of the treasures of Paradise?” I replied: “Certainly, O Messenger of Allah.” He said: “There is no power and no strength except through Allah.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه ابن ماجه (3825)، والنسائي في عمل اليوم والليلة (43)، وأحمد (21346)."},{"num":10844,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلَا أَدُلُّكَ عَلَى كنـز مِنْ كُنُوزِ الْجَنَّةِ؟ قُلْتُ: بَلَى يَا رَسُولَ اللَّهِ، فَقَالَ: لَا حَوْلَ وَ لَا قُوَّةَ إِلَّا بِاللهِ، وَلَا مَلْجَأَ مِنَ اللَّهِ إِلَّا إِلَيْهِ."],"takhrij":"صحيح: رواه أحمد (8085)، والبزار –كشف الأستار (3089)، والنسائي في عمل اليوم والليلة (358)، وصحّحه الحاكم (1901) كلهم من طرق عن أبي إسحاق، عن كُميل بن زياد، عن أبي هريرة فذكره في حديث طويل.","grade":"صحيح","chapter_ar":"باب فضل لا حول ولا قوة إلا باللّٰه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (8085), al-Bazzār in Kashf al-Astār (3089), and al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (358).","chapter_en":"The Virtue of Saying: “There Is No Power and No Strength Except through Allah”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Shall I direct you to one of the treasures of Paradise?” I replied: “Certainly, O Messenger of Allah.” He said: “There is no power and no strength except through Allah, and there is no refuge from Allah except with Him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (8085)، والبزار في كشف الأستار (3089)، والنسائي في عمل اليوم والليلة (358)."},{"num":10845,"demo":false,"sanad":"","matn":["عَنْ عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ قَالَ: لَقِيتُ أَبَا أَيُّوبَ الْأَنْصَارِيَّ، فَقَالَ لِي: أَلَا آمُرُكَ بِمَا أَمَرَنِي بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنْ أُكْثِرَ مِنْ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، فَإِنَّهُ كَنْزٌ مِنْ كُنُوزِ الْجَنَّةِ."],"takhrij":"حسن: رواه ابن أبي شيبة (36410)، والطبراني في الكبير (3900) كلاهما من حديث زيد بن الحباب، عن كثير بن زيد المدني قال: حدثني المطلب بن عبد الله بن حنطب، عن عامر بن سعد بن أبي وقاص فذكره.","grade":"حسن","chapter_ar":"باب فضل لا حول ولا قوة إلا باللّٰه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī Shaybah (36410) and al-Ṭabarānī in al-Muʿjam al-Kabīr (4/158).","chapter_en":"The Virtue of Saying: “There Is No Power and No Strength Except through Allah”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["ʿĀmir ibn Saʿd ibn Abī Waqqāṣ said: I met Abū Ayyūb al-Anṣārī, and he said to me: “Shall I instruct you in what the Messenger of Allah ﷺ instructed me? Frequently say, ‘There is no power and no strength except through Allah,’ for it is one of the treasures of Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي شيبة (36410)، والطبراني في الكبير (3900)."},{"num":10846,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ سَعْدِ بْنِ عُبَادَةَ أَنَّ أَبَاهُ دَفَعَهُ إِلَى النَّبِيِّ صلى الله عليه وسلم يَخْدُمُهُ قَالَ: فَمَرَّ بِيَ النَّبِيُّ صلى الله عليه وسلم وَقَدْ صَلَّيْتُ فَضَرَبَنِي بِرِجْلِهِ وَقَالَ: أَلاَ أَدُلُّكَ عَلَى بَابٍ مِنْ أَبْوَابِ الْجَنَّةِ؟ قُلْتُ: بَلَى قَالَ: لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بالله.وفي لفظ: كنز مِنْ كنوز الجنة."],"takhrij":"حسن: رواه الترمذي (3581)، والنسائي في عمل اليوم والليلة (355)، وأحمد (15480)، والبزار –كشف الأستار (3085)، والحاكم (7787) كلهم من حديث وهب بن جرير، حدثنا أبي قال: سمعت منصور بن زاذان يحدث عن ميمون بن أبي شبيب، عن قيس بن سعد بن عبادة فذكره.","grade":"حسن","chapter_ar":"باب فضل لا حول ولا قوة إلا باللّٰه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3581), al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (355), and Aḥmad (15480).","chapter_en":"The Virtue of Saying: “There Is No Power and No Strength Except through Allah”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Qays ibn Saʿd ibn ʿUbādah narrated that his father placed him in the service of the Prophet ﷺ. He said: The Prophet ﷺ passed by me after I had prayed, nudged me with his foot, and said: “Shall I direct you to one of the gates of Paradise?” I replied: “Certainly.” He said: “There is no power and no strength except through Allah.” Another wording states: “One of the treasures of Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3581)، والنسائي في عمل اليوم والليلة (355)، وأحمد (15480)."},{"num":10847,"demo":false,"sanad":"","matn":["عن عبدالله بن عمرو قال: رأيت رسول الله صلى الله عليه وسلم يعقد التسبيح.وزاد في رواية: بيمينه."],"takhrij":"صحيح: رواه أبو داود (1502)، والترمذي (3411)، والحاكم (1/547) كلهم من طريق الأعمش، عن عطاء بن السائب، عن أبيه، عن عبد الله بن عمرو بن العاص فذكره.","grade":"صحيح","chapter_ar":"باب استحباب التسبيح باليمين","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1502) and al-Tirmidhī (3411), and authenticated by al-Ḥākim (1/547).","chapter_en":"The Recommendation of Counting Glorifications with the Right Hand","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأذكار","group_en":"Collection of Narrations Concerning Remembrances","part_no":54,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ said: “I saw the Messenger of Allah ﷺ counting the glorifications.” Another narration adds: “With his right hand.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1502)، والترمذي (3411)، وصححه الحاكم (1/547)."},{"num":10848,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  مَنْ صَلَّى عَلَيَّ وَاحِدَةً صَلَّى اللَّهُ عَلَيْهِ عَشْرًا."],"takhrij":"صحيح: رواه مسلم في الصلاة (408) من طرق عن إسماعيل بن جعفر، عن العلاء بن عبد الرحمن، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب فضل الصلاة على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (408).","chapter_en":"The Virtue of Sending Blessings upon the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever sends one blessing upon me, Allah will send ten blessings upon him.”"]},"buhuth":{"en":["Aḥmad also narrated it (7561), and Ibn Ḥibbān authenticated it (905), with the wording:","“Whoever sends blessings upon me once, Allah, Mighty and Majestic, will record ten good deeds for him because of it.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿إِنَّ اللّٰهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ، يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا﴾ [سورة الأحزاب: ٥٦].","قال سفيان الثوري وغير واحد من أهل العلم: صلاة الرب الرحمة، وصلاة الملائكة الاستغفار. ذكره الترمذي عقب حديث أبي هريرة (٤٨٥)، وهو الحديث الآتي. وذكر البخاري في ترجمة الباب قبل حديث (٤٧٩٧)، عن أبي العالية قال: صلاة اللّٰه ثناؤه عليه عند الملائكة، وصلاة الملائكة الدعاء."],"en":["Allah, the Exalted, said:","“Indeed, Allah and His angels send blessings upon the Prophet. O you who believe, send blessings upon him and greet him with complete peace.”","[Sūrat al-Aḥzāb 33:56]","Sufyān al-Thawrī and a number of other scholars said:","“The blessing of the Lord means mercy, while the blessing of the angels means seeking forgiveness.”","Al-Tirmidhī mentioned this after the hadith of Abū Hurayrah (485), which follows.","Al-Bukhārī also cited in the chapter heading before Hadith 4797 that Abū al-ʿĀliyah said:","“Allah’s blessing upon the Prophet means His praise of him before the angels, while the angels’ blessing means their supplication.”"]}},"tuhfa":{},"voc":["seerah",1727],"full":1,"dr":1,"rep":[13105],"tks":"صحيح: رواه مسلم (408)."},{"num":10849,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ صَلَّى عَلَىَّ صَلاَةً وَاحِدَةً صَلَّى اللَّهُ عَلَيْهِ عَشْرَ صَلَوَاتٍ، وَحُطَّتْ عَنْهُ عَشْرُ خَطِيئَاتٍ، وَرُفِعَتْ لَهُ عَشْرُ دَرَجَاتٍ.","وفي رواية عنه: من ذكرني فليصل علي، ومن صلى علي صلاة واحدة صلى الله عليه عشرا."],"takhrij":"حسن: رواه النسائي (1297) –والسياق له-، وأحمد (11998، 13754)، والبخاري في الأدب المفرد (643)، وصحّحه ابن حبان (904)، والحاكم (1/550) كلهم من طريق يونس بن أبي إسحاق، عن بريد بن أبي مريم، عن انس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب فضل الصلاة على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (1297), whose wording is cited here, Aḥmad (11998, 13754), and al-Bukhārī in al-Adab al-Mufrad (643), and authenticated by Ibn Ḥibbān (904) and al-Ḥākim (1/550).","chapter_en":"The Virtue of Sending Blessings upon the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “Whoever sends one blessing upon me, Allah will send ten blessings upon him, erase ten sins from him, and raise him by ten ranks.” Another narration states: “Whoever mentions me should send blessings upon me. Whoever sends one blessing upon me, Allah will send ten blessings upon him.”"]}},"tuhfa":{},"voc":["seerah",1728],"full":1,"dr":1,"rep":[13106],"tks":"حسن: رواه النسائي (1297) - والسياق له -، وأحمد (11998، 13754)، والبخاري في الأدب المفرد (643)، وصححه ابن حبان (904)، والحاكم (1/550)."},{"num":10850,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ قَالَ: خَرَجَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَإِذَا هو بِأَبِي طَلْحَةَ، فَقَامَ إِلَيْهِ، فَتَلَقَّاهُ، فَقَالَ: بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ اللَّهِ إِنِّي لَأَرَى السُّرُورَ فِي وَجْهِكَ قَالَ: أَجَلْ، أَتَانِي جِبْرِيلُ آنِفًا فَقَالَ: يَا مُحَمَّدُ مَنْ صَلَّى عَلَيْكَ مَرَّةً –أَوْ قَالَ وَاحِدَةً- كَتَبَ اللَّهُ تبارك وتعالى لَهُ بِهَا عَشْرَ حَسَنَاتٍ، وَمَحَا عَنْهُ بِهَا عَشْرَ سَيِّئَاتٍ، وَرَفَعَ لَهُ بِهَا عَشْرَ دَرَجَاتٍ.","قال ابن حبيب (أحد رواة الحديث): ولا أعلمه إلا قال: وصلى عليه الملائكة عشر مرات."],"takhrij":"حسن: رواه البغوي في الجعديات (3058) –ومن طريقه ابن بشران في أماليه (1192)، والخطيب في تلخيص المتشابه (250)- عن محمد بن حبيب الجارودي، حدثنا عبد العزيز بن أبي حازم، عن أبيه، عن سهل بن سعد فذكره.","grade":"حسن","chapter_ar":"باب فضل الصلاة على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Baghawī in al-Jaʿdiyyāt (3058), and through him by Ibn Bishrān in his Amālī (1192) and al-Khaṭīb in Talkhīṣ al-Mutashābih (250).","chapter_en":"The Virtue of Sending Blessings upon the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Sahl ibn Saʿd narrated: The Messenger of Allah ﷺ came out and encountered Abū Ṭalḥah, who stood and went forward to meet him. He said: “May my father and mother be sacrificed for you, O Messenger of Allah! I can see happiness upon your face.” He replied: “Yes. Gabriel came to me just now and said: ‘O Muḥammad, whoever sends blessings upon you once, Allah, Blessed and Exalted, will record ten good deeds for him, erase ten evil deeds from him, and raise him by ten ranks.’” Ibn Ḥabīb, one of the narrators of the hadith, said: “I do not know it except that he also said: ‘And the angels send blessings upon him ten times.’”"]}},"tuhfa":{},"voc":["seerah",1729],"full":1,"dr":1,"rep":[13107],"tks":"حسن: رواه البغوي في الجعديات (3058)، ومن طريقه ابن بشران في أماليه (1192)، والخطيب في تلخيص المتشابه (250)."},{"num":10851,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ نَسِيَ الصَّلَاةَ عَلَيَّ خُطِئَ بِهِ طَرِيقُ الْجَنَّةِ."],"takhrij":"حسن: رواه البيهقي في الكبرى (19177)، وفي الشعب (1473)، وابن شاهين في الجزء الخامس من الأفراد (81) كلهم من طريق عمر بن حفص بن غياث، حدثني أبي، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب فضل الصلاة على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqī in al-Sunan al-Kubrā (9/286) and Shuʿab al-Īmān (1473), and Ibn Shāhīn in al-Juzʾ al-Khāmis min al-Afrād (81).","chapter_en":"The Virtue of Sending Blessings upon the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever neglects to send blessings upon me has missed the path to Paradise.”"]}},"tuhfa":{},"voc":["seerah",1730],"full":1,"dr":1,"tks":"حسن: رواه البيهقي في السنن الكبرى (19177)، وفي شعب الإيمان (1473)، وابن شاهين في الجزء الخامس من الأفراد (81)."},{"num":10852,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إنَّ لِلَّهِ مَلَائِكَةً سَيَّاحِينَ فِي الْأَرْضِ يُبَلِّغُونِي مِنْ أُمَّتِي السَّلَامَ."],"takhrij":"صحيح: رواه النسائي (1282)، وأحمد (3666)، وصحّحه ابن حبان (914)، والحاكم (3576) كلهم من طرق عن سفيان، عن عبد الله بن السائب، عن زاذان، عن عبد الله بن مسعود فذكره.","grade":"صحيح","chapter_ar":"باب أن النبي ﷺ تبلغه الملائكة الصلاة والسلام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (1282) and Aḥmad (3666), and authenticated by Ibn Ḥibbān (914) and al-Ḥākim (3576).","chapter_en":"The Angels Convey Blessings and Greetings of Peace to the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “Allah has angels who travel throughout the earth, conveying to me the greetings of peace from my nation.”"]},"buhuth":{"en":["This is one of the special distinctions of the Prophet ﷺ: Allah has appointed angels to convey to him the blessings and greetings of peace sent by the Muslims."]}},"tuhfa":{},"voc":["seerah",1731],"full":1,"dr":1,"rep":[547,5320],"tks":"صحيح: رواه النسائي (1282)، وأحمد (3666)، وصححه ابن حبان (914)، والحاكم (3576)."},{"num":10853,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تَجْعَلُوا بُيُوتَكُمْ قُبُورًا، وَلاَ تَجْعَلُوا قَبْرِي عِيدًا، وَصَلُّوا عَلَىَّ فَإِنَّ صَلاَتَكُمْ تَبْلُغُنِي حَيْثُ كُنْتُمْ."],"takhrij":"حسن: رواه أبو داود (2042)، وأحمد (8804) كلاهما من طريق عبدالله بن نافع، أخبرني ابن أبي ذئب، عن سعيد المقبري، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب أن النبي ﷺ تبلغه الملائكة الصلاة والسلام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2042) and Aḥmad (8804).","chapter_en":"The Angels Convey Blessings and Greetings of Peace to the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Do not make your houses into graves, and do not make my grave a place of recurring celebration. Send blessings upon me, for your blessings reach me wherever you may be.”"]}},"tuhfa":{},"voc":["seerah",1732],"full":1,"dr":1,"rep":[5319],"tks":"حسن: رواه أبو داود (2042)، وأحمد (8804)."},{"num":10854,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا مِنْ أَحَدٍ يُسَلِّمُ عَلَىَّ إِلاَّ رَدَّ اللَّهُ عَلَىَّ رُوحِي حَتَّى أَرُدَّ عَلَيْهِ السَّلاَمَ."],"takhrij":"حسن: رواه أبو داود (2041) وأحمد (10815)، والبيهقي في الكبرى (10270) كلهم من طريق المقرئ (وهو عبد الله بن يزيد)، حدّثنا حيوة، عن أبي صخر حُميد بن زياد، عن يزيد بن عبدالله بن قُسيط، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب أن النبي ﷺ تبلغه الملائكة الصلاة والسلام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2041), Aḥmad (10815), and al-Bayhaqī in al-Sunan al-Kubrā (5/245).","chapter_en":"The Angels Convey Blessings and Greetings of Peace to the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “No one sends greetings of peace upon me except that Allah restores my soul to me so that I may return his greeting of peace.”"]},"buhuth":{"en":["Know that this hadith and similar narrations relate specifically to the life of the intermediate realm after death. None knows its true nature except Allah, Glorified and Exalted.","The life of the intermediate realm must not be measured according to the conditions of worldly life, for interpreting it according to the outward conditions of worldly existence would conflict with direct observation and sensory experience."]}},"tuhfa":{},"voc":["seerah",1733],"full":1,"dr":1,"rep":[5318],"tks":"حسن: رواه أبو داود (2041)، وأحمد (10815)، والبيهقي في السنن الكبرى (10270)."},{"num":10855,"demo":false,"sanad":"","matn":["عن عَبْدِ الرَّحْمَنِ بن أَبِي لَيْلَى قَالَ: لَقِيَنِي كَعْبُ بْنُ عُجْرَةَ فَقَالَ: أَلاَ أُهْدِي لَكَ هَدِيَّةً، إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ عَلَيْنَا، فَقُلْنَا: يَا رَسُولَ اللَّهِ! قَدْ عَلِمْنَا كَيْفَ نُسَلِّمُ عَلَيْكَ، فَكَيْفَ نُصَلِّي عَلَيْكَ؟ قَالَ: فَقُولُوا: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ، وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ، وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6357)، ومسلم في الصلاة (406) كلاهما من طريق شعبة، حدَّثنا الحكم، قال: سمعت عبدالرحمن بن أبي ليلى يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب في ذكر صيغ الصلاة على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6357) and Muslim (406).","chapter_en":"The Reported Forms of Sending Blessings upon the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Abī Laylā said: Kaʿb ibn ʿUjrah met me and said: “Shall I give you a gift? The Prophet ﷺ came out to us, and we said, ‘O Messenger of Allah, we have learned how to greet you with peace, but how should we send blessings upon you?’” He replied: “Say: ‘O Allah, send blessings upon Muḥammad and upon the family of Muḥammad, as You sent blessings upon the family of Abraham. Indeed, You are Praiseworthy and Glorious. O Allah, bless Muḥammad and the family of Muḥammad, as You blessed the family of Abraham. Indeed, You are Praiseworthy and Glorious.’”"]},"buhuth":{"en":["The statement, “We have learned how to greet you with peace,” refers to what is recited during the tashahhud:","“Peace be upon you, O Prophet, and the mercy of Allah and His blessings.”"]}},"tuhfa":{},"voc":["seerah",1734],"full":1,"dr":1,"rep":[2170,13103],"tks":"متفق عليه: رواه البخاري (6357)، ومسلم (406)."},{"num":10856,"demo":false,"sanad":"","matn":["عَنْ أَبِي حُمَيْدٍ الساعدي قَالَ: قَالُوا: يَا رَسُولَ اللَّهِ كَيْفَ نُصلِّي عَلَيْكَ؟ فَقَالَ: قُولُوا: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ، كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيمَ، وَبَارِكْ عَلَى مُحَمَّدٍ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة (66) عن عبدالله بن أبي بكر بن حزم، عن أبيه، عن عمرو بن سُلَيم الزرقي، أنه قال: أخبرني أبو حُميد الساعدي فذكره.","grade":"متفق عليه","chapter_ar":"باب في ذكر صيغ الصلاة على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (66), al-Bukhārī (3369), and Muslim (407).","chapter_en":"The Reported Forms of Sending Blessings upon the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Abū Ḥumayd al-Sāʿidī narrated: They asked: “O Messenger of Allah, how should we send blessings upon you?” He replied: “Say: ‘O Allah, send blessings upon Muḥammad, his wives, and his descendants, as You sent blessings upon the family of Abraham. Bless Muḥammad, his wives, and his descendants, as You blessed the family of Abraham. Indeed, You are Praiseworthy and Glorious.’”"]}},"tuhfa":{},"voc":["seerah",1735],"full":1,"dr":1,"rep":[2168],"tks":"متفق عليه: رواه مالك (66)، والبخاري (3369)، ومسلم (407)."},{"num":10857,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: قُلْنَا يَا رَسُولَ اللَّهِ: هَذَا السَّلاَمُ عَلَيْكَ، فَكَيْفَ نُصَلِّي؟ قَالَ: قُولُوا: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ، وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ."],"takhrij":"صحيح: رواه البخاري في الدعوات (6358) عن إبراهيم بن حمزة، حدثنا ابن أبي حازم والدراوردي، عن يزيد (هو ابن الهاد)، عن عبدالله بن حَبَّاب، عن أبي سعيد الخدري قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر صيغ الصلاة على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6358).","chapter_en":"The Reported Forms of Sending Blessings upon the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: We said: “O Messenger of Allah, this is how we greet you with peace, but how should we send blessings upon you?” He replied: “Say: ‘O Allah, send blessings upon Muḥammad, Your servant and Messenger, as You sent blessings upon Abraham. Bless Muḥammad and the family of Muḥammad, as You blessed Abraham and the family of Abraham.’”"]}},"tuhfa":{},"voc":["seerah",1736],"full":1,"tks":"صحيح: رواه البخاري (6358)."},{"num":10858,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ أَنَّهُ قَالَ: أَتَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَجْلِسِ سَعْدِ بْنِ عُبَادَةَ، فَقَالَ لَهُ بَشِيرُ بْنُ سَعْدٍ: أَمَرَنَا اللهُ أَنْ نُصَلِّيَ عَلَيْكَ يَا رَسُولَ اللَّهِ، فَكَيْفَ نُصَلِّي عَلَيْكَ؟ قَالَ: فَسَكَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى تَمَنَّيْنَا أَنَّهُ لَمْ يَسْأَلْهُ ثُمَّ قَالَ: قُولُوا: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صلَّيت عَلَى إِبْرَاهِيمَ، وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، وَالسَّلَامُ كَمَا عَلِمْتُمْ."],"takhrij":"صحيح: رواه مالك في قصر الصلاة (67) عن نعيم بن عبدالله المُجْمِر، عن محمد بن عبدالله بن زيد، أنه أخبره عن أبي مسعود الأنصاري فذكره.ورواه مسلم في الصلاة (405) عن يحيى بن يحيى، عن مالك به مثله.وزاد ابنُ خزيمة (711) وغيره: كيف نصلي عليك إذا نحن صلّينا عليك في صلاتنا.","grade":"صحيح","chapter_ar":"باب في ذكر صيغ الصلاة على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (67) and Muslim (405).","chapter_en":"The Reported Forms of Sending Blessings upon the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Abū Masʿūd al-Anṣārī narrated: The Messenger of Allah ﷺ came to us while we were in the gathering of Saʿd ibn ʿUbādah. Bashīr ibn Saʿd said to him: “Allah has commanded us to send blessings upon you, O Messenger of Allah. How should we send blessings upon you?” The Messenger of Allah ﷺ remained silent until we wished that Bashīr had not asked him. He then said: “Say: ‘O Allah, send blessings upon Muḥammad and the family of Muḥammad, as You sent blessings upon Abraham. Bless Muḥammad and the family of Muḥammad, as You blessed the family of Abraham throughout the worlds. Indeed, You are Praiseworthy and Glorious.’ As for the greeting of peace, it is as you have already been taught.”"]},"buhuth":{"ar":["وزاد ابن خزيمة (٧١١) وغيره: كيف نصلي عليك إذا نحن صلينا عليك في صلاتنا؟."],"en":["Ibn Khuzaymah (711) and others added:","“How should we send blessings upon you when we do so in our prayer?”"]}},"tuhfa":{},"voc":["seerah",1737],"full":1,"rep":[11023],"tks":"صحيح: رواه مالك (67)، ومسلم (405)."},{"num":10859,"demo":false,"sanad":"","matn":["عَنْ طَلْحَةَ بن عُبيدالله قَالَ: قُلْنَا يَا رَسُولَ اللَّهِ: كَيْفَ الصَّلاَةُ عَلَيْكَ؟ قَالَ: قُولُوا: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ، وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ."],"takhrij":"حسن: رواه النسائي (1290) عن إسحاق بن إبراهيم قال: أخبرنا محمد ابن بشر، قال: حدّثنا مجمع بن يحيى، عن عثمان بن موهب، عن موسى بن طلحة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب في ذكر صيغ الصلاة على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (1290).","chapter_en":"The Reported Forms of Sending Blessings upon the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Ṭalḥah ibn ʿUbaydillāh narrated: We asked: “O Messenger of Allah, how should blessings be sent upon you?” He replied: “Say: ‘O Allah, send blessings upon Muḥammad and the family of Muḥammad, as You sent blessings upon Abraham and the family of Abraham. Indeed, You are Praiseworthy and Glorious. Bless Muḥammad and the family of Muḥammad, as You blessed Abraham and the family of Abraham. Indeed, You are Praiseworthy and Glorious.’”"]}},"tuhfa":{},"voc":["seerah",1738],"full":1,"dr":1,"tks":"حسن: رواه النسائي (1290)."},{"num":10860,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بن خَارِجَةَ، قَالَ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَيْفَ الصَّلَاةُ عَلَيْكَ؟ قَالَ:صَلُّوا وَاجْتَهِدُوا، ثُمَّ قُولُوا:اللهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ."],"takhrij":"صحيح: رواه أحمد (1714) عن علي بن بَحْر، حدثنا عيسى بن يونس، حدثنا عثمان بن حكيم، حدثنا خالد بن سلمة، أن عبدالحميد بن عبدالرحمن دعا موسى بن طلحة حين عرَّس على ابنه فقال: يا أبا عيسى كيف بلغك في الصلاة على النبي صلى الله عليه وسلم؟ فقال موسى: سألتُ زيد بن خارجة عن الصلاة على النبي صلى الله عليه وسلم فقال زيد: أنا سألت رسول الله صلى الله عليه وسلم نفسي: كيف الصلاة عليك؟ فذكر الحديث.","grade":"صحيح","chapter_ar":"باب في ذكر صيغ الصلاة على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (1714).","chapter_en":"The Reported Forms of Sending Blessings upon the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Zayd ibn Khārijah said: I asked the Messenger of Allah ﷺ: “How should blessings be sent upon you?” He replied: “Send blessings and strive earnestly in doing so, then say: ‘O Allah, bless Muḥammad and the family of Muḥammad, as You blessed the family of Abraham. Indeed, You are Praiseworthy and Glorious.’”"]}},"tuhfa":{},"voc":["seerah",1739],"full":1,"dr":1,"tks":"صحيح: رواه أحمد (1714)."},{"num":10861,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّهُمْ سَأَلُوا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَيْفَ نُصَلِّي عَلَيْكَ؟، قَالَ: قُولُوا: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ، وَبَارِكْ عَلَى مُحَمَّدٍ، وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ وَبَارَكْتَ عَلَى إِبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، وَالسَّلامُ كَمَا قَدْ عُلِّمْتُمْ."],"takhrij":"صحيح: رواه البزار -كشف الأستار (565) عن أحمد بن عبدة، أنبأ سُلَيم بن أخضر، ثنا داود بن قيس، عن نُعيم، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب في ذكر صيغ الصلاة على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzār in Kashf al-Astār (565).","chapter_en":"The Reported Forms of Sending Blessings upon the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated: They asked the Messenger of Allah ﷺ: “How should we send blessings upon you?” He replied: “Say: ‘O Allah, send blessings upon Muḥammad, and bless Muḥammad and the family of Muḥammad, as You sent blessings and bestowed blessings upon Abraham and the family of Abraham throughout the worlds. Indeed, You are Praiseworthy and Glorious.’ As for the greeting of peace, it is as you have been taught.”"]}},"tuhfa":{},"voc":["seerah",1740],"full":1,"dr":1,"rep":[2174],"tks":"صحيح: رواه البزار في كشف الأستار (565)."},{"num":10862,"demo":false,"sanad":"","matn":["عن عَامِرِ بن رَبِيعَةَ عَنْ أَبِيهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا مِنْ مُسْلِمٍ يُصَلِّي عَلَىَّ إِلاَّ صَلَّتْ عَلَيْهِ الْمَلاَئِكَةُ مَا صَلَّى عَلَىَّ، فَلْيُقِلَّ الْعَبْدُ مِنْ ذَلِكَ أَوْ لِيُكْثِرْ."],"takhrij":"حسن: رواه ابن ماجه (907)، وأحمد (15680) كلاهما من طريق شعبة، عن عاصم بن عبيد الله قال: سمعت عبد الله بن عامر بن ربيعة يحدث عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب يستحب للمسلم إكثار الصلاة على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (907), Aḥmad (15680), and ʿAbd al-Razzāq (3115).","chapter_en":"It Is Recommended for a Muslim to Frequently Send Blessings upon the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["ʿĀmir ibn Rabīʿah narrated that the Prophet ﷺ said: “No Muslim sends blessings upon me except that the angels continue sending blessings upon him for as long as he sends blessings upon me. Therefore, let the servant do little of that or much.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿إِنَّ اللّٰهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ، يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا﴾ [سورة الأحزاب: ٥٦]."],"en":["Allah, the Exalted, said:","“Indeed, Allah and His angels send blessings upon the Prophet. O you who believe, send blessings upon him and greet him with complete peace.”","[Sūrat al-Aḥzāb 33:56]"]}},"tuhfa":{},"voc":["seerah",1742],"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (907)، وأحمد (15680)، وعبد الرزاق (3115)."},{"num":10863,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَقَى الْمِنْبَرَ فَقَالَ: آمِينَ، آمِينَ، آمِينَ، قِيلَ لَهُ: يَا رَسُولَ اللَّهِ، مَا كُنْتَ تَصْنَعُ هَذَا؟ فَقَالَ: قَالَ لِي جِبْرِيلُ: رَغِمَ أَنْفُ عَبْدٍ أَدْرَكَ أَبَوَيْهِ أَوْ أَحَدَهُمَا لَمْ يُدْخِلْهُ الْجَنَّةَ، قُلْتُ: آمِينَ. ثُمَّ قَالَ: رَغِمَ أَنْفُ عَبْدٍ دَخَلَ عَلَيْهِ رَمَضَانُ لَمْ يُغْفَرْ لَهُ، فَقُلْتُ: آمِينَ. ثُمَّ قَالَ: رَغِمَ أَنْفُ امْرِئٍ ذُكِرْتَ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيْكَ، فَقُلْتُ: آمِينَ."],"takhrij":"حسن: رواه البخاري في الأدب المفرد (646)، وصحّحه ابن خزيمة (1888) كلاهما من طريق كثير بن زيد، عن الوليد بن رباح، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب الصلاة على النبي ﷺ كلما جاء ذكره","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bukhārī in al-Adab al-Mufrad (646), and authenticated by Ibn Khuzaymah (1888).","chapter_en":"Sending Blessings upon the Prophet ﷺ Whenever He Is Mentioned","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated: The Prophet ﷺ ascended the pulpit and said: “Āmīn. Āmīn. Āmīn.” He was asked: “O Messenger of Allah, you did not previously do this. What happened?” He replied: “Gabriel said to me: ‘May the nose of a servant be rubbed in the dust who lives to see both of his parents, or one of them, yet they do not become a cause for his entering Paradise.’ I said: ‘Āmīn.’ Then he said: ‘May the nose of a servant be rubbed in the dust who reaches Ramadan and is not forgiven.’ I said: ‘Āmīn.’ Then he said: ‘May the nose of a man be rubbed in the dust in whose presence you are mentioned but he does not send blessings upon you.’ I said: ‘Āmīn.’”"]}},"tuhfa":{},"voc":["seerah",1743],"full":1,"dr":1,"tks":"حسن: رواه البخاري في الأدب المفرد (646)، وصححه ابن خزيمة (1888)."},{"num":10864,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رَغِمَ أَنْفُ رَجُلٍ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَىَّ، وَرَغِمَ أَنْفُ رَجُلٍ دَخَلَ عَلَيْهِ رَمَضَانُ ثُمَّ انْسَلَخَ قَبْلَ أَنْ يُغْفَرَ لَهُ، وَرَغِمَ أَنْفُ رَجُلٍ أَدْرَكَ عِنْدَهُ أَبَوَاهُ الْكِبَرَ فَلَمْ يُدْخِلاَهُ الْجَنَّةَ."],"takhrij":"حسن: رواه الترمذي (3545)، وأحمد (7451)، وصحّحه ابن حبان (908)، والحاكم (2016) كلهم من طرق عن عبد الرحمن بن إسحاق عن سعيد بن أبي سعيد المقبري، عن أبي هريرة فذكره.واقتصر الحاكم على ذكر الصلاة على النبي صلى الله عليه وسلم.","grade":"حسن","chapter_ar":"باب الصلاة على النبي ﷺ كلما جاء ذكره","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3545) and Aḥmad (7451), and authenticated by Ibn Ḥibbān (908) and al-Ḥākim (1/549).","chapter_en":"Sending Blessings upon the Prophet ﷺ Whenever He Is Mentioned","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “May the nose of a man be rubbed in the dust in whose presence I am mentioned but he does not send blessings upon me. May the nose of a man be rubbed in the dust who reaches Ramadan, but it ends before he is forgiven. May the nose of a man be rubbed in the dust whose parents reach old age in his presence, yet they do not become a cause for his entering Paradise.”"]}},"tuhfa":{},"voc":["seerah",1744],"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3545)، وأحمد (7451)، وصححه ابن حبان (908)، والحاكم (2016)."},{"num":10865,"demo":false,"sanad":"","matn":["عَنْ حُسَيْنِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْبَخِيلُ الَّذِي مَنْ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عليّ."],"takhrij":"حسن: رواه الترمذي (3546)، وأحمد (1736)، والنسائي في عمل اليوم والليلة (55، 56)، وصحّحه ابن حبان (909)، والحاكم (2015) كلهم من طرق عن سليمان بن بلال، عن عمارة بن غزية، عن عبد الله بن علي بن حسين بن علي بن أبي طالب، عن أبيه، عن حسين بن علي بن أبي طالب فذكره.","grade":"حسن","chapter_ar":"باب الصلاة على النبي ﷺ كلما جاء ذكره","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3546), Aḥmad (1736), and al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (55, 56).","chapter_en":"Sending Blessings upon the Prophet ﷺ Whenever He Is Mentioned","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Ḥusayn ibn ʿAlī ibn Abī Ṭālib narrated that the Messenger of Allah ﷺ said: “The miser is the one in whose presence I am mentioned, yet he does not send blessings upon me.”"]}},"tuhfa":{},"voc":["seerah",1745],"full":1,"dr":1,"rep":[13104],"tks":"حسن: رواه الترمذي (3546)، وأحمد (1736)، والنسائي في عمل اليوم والليلة (55، 56)."},{"num":10866,"demo":false,"sanad":"","matn":["عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  إِذَا سَمِعْتُمُ الْمُؤَذِّنَ فَقُولُوا مِثْلَ مَا يَقُولُ، ثُمَّ صَلُّوا عَلَيَّ؛ فَإِنَّهُ مَنْ صَلَّى عَلَيَّ صَلَاةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا، ثُمَّ سَلُوا اللَّهَ لِي الْوَسِيلَةَ؛ فَإِنَّهَا مَنْزِلَةٌ فِي الْجَنَّةِ لَا تَنْبَغِي إِلَّا لِعَبْدٍ مِنْ عِبَادِ اللَّهِ، وَأَرْجُو أَنْ أَكُونَ أَنَا هُوَ. فَمَنْ سَأَلَ لِي الْوَسِيلَةَ حَلَّتْ لَهُ الشَّفَاعَةُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (384) من طريق كعب بن علقمة، عن عبدالرحمن بن جبير، عن عبدالله بن عمرو بن العاص فذكره.","grade":"صحيح","chapter_ar":"باب الصلاة على النبي ﷺ بعد إجابة المؤذن","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (384).","chapter_en":"Sending Blessings upon the Prophet ﷺ after Responding to the Caller to Prayer","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated that he heard the Prophet ﷺ say: “When you hear the caller to prayer, repeat what he says. Then send blessings upon me, for whoever sends one blessing upon me, Allah will send ten blessings upon him because of it. Then ask Allah to grant me al-Wasīlah, for it is a rank in Paradise that is appropriate for only one servant from among the servants of Allah, and I hope that I will be that servant. Whoever asks Allah to grant me al-Wasīlah will become entitled to my intercession.”"]}},"tuhfa":{},"voc":["seerah",1746],"full":1,"rep":[10984],"tks":"صحيح: رواه مسلم (384)."},{"num":10867,"demo":false,"sanad":"","matn":["عن فَضَالَةَ بن عُبيد صاحب رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: سَمِعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلاً يَدْعُو فِي صَلاَتِهِ، لَمْ يُمَجِّدِ اللَّهَ، تَعَالَى وَلَمْ يُصَلِّ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عَجِلَ هَذَا. ثُمَّ دَعَاهُ فَقَالَ لَهُ، أَوْ لِغَيْرِهِ: إِذَا صَلَّى أَحَدُكُمْ فَلْيَبْدَأْ بِتَحْمِيدِ رَبِّهِ جَلَّ وَعَزَّ وَالثَّنَاءِ عَلَيْهِ، ثُمَّ يُصَلِّي عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ يَدْعُو بَعْدُ بِمَا شَاءَ."],"takhrij":"صحيح: رواه أبو داود (1481)، والترمذي (3477) كلاهما من طريق عبدالله بن يزيد المُقرئ، ثنا حيوة بن شريح، أخبرني أبو هاني حُميد بن هانئ، أن أبا علي عمرو بن مالك الجَنْبيَّ أخبره، أنه سمع فَضالة بن عبيد فذكر مثله.","grade":"صحيح","chapter_ar":"باب الصلاة على النبي ﷺ عند الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1481) and al-Tirmidhī (3477).","chapter_en":"Sending Blessings upon the Prophet ﷺ When Supplicating","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Faḍālah ibn ʿUbayd, a Companion of the Messenger of Allah ﷺ, narrated: The Messenger of Allah ﷺ heard a man supplicating during his prayer without first glorifying Allah or sending blessings upon the Prophet ﷺ. The Messenger of Allah ﷺ said: “This man has been hasty.” He then called him and said to him—or to someone else: “When one of you prays, let him begin by glorifying and praising his Lord. Then let him send blessings upon the Prophet ﷺ. After that, let him supplicate for whatever he wishes.”"]}},"tuhfa":{},"voc":["seerah",1747],"full":1,"dr":1,"rep":[2172,10893],"tks":"صحيح: رواه أبو داود (1481)، والترمذي (3477)."},{"num":10868,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ بْنِ سهل بْنِ حُنَيْفٍ قَالَ: السُّنَّةُ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ أَنْ يُكَبِّرَ، ثُمَّ يَقْرَأَ بِأُمِّ الْقُرْآنِ، ثُمَّ يُصَلِّي عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، ثُمَّ يُخْلِصَ الدُّعَاءَ لِلْمَيِّتِ، وَلَا يَقْرَأَ إِلَّا فِي التَّكْبِيرَةِ الْأُولَى، ثُمَّ يُسَلِّمَ فِي نفســه عَنْ يَمِينِهِ."],"takhrij":"صحيح: رواه عبد الرزاق (6428)- ومن طريقه ابن الجارود في المنتقى (540)- عن معمر، عن الزهري قال: سمعت أبا أمامة بن سهل بن حنيف يحدث ابن المسيب فذكره.وإسناده صحيح. وصحّحه أيضا ابن القيم في جلاء الأفهام (ص 193).","grade":"صحيح","chapter_ar":"باب الصلاة على النبي ﷺ في صلاة الجنازة بعد التكبيرة الثانية","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by ʿAbd al-Razzāq (6428), and through him by Ibn al-Jārūd in al-Muntaqā (540).","chapter_en":"Sending Blessings upon the Prophet ﷺ in the Funeral Prayer after the Second Takbīr","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Abū Umāmah ibn Sahl ibn Ḥunayf said: “The Sunnah in the funeral prayer is that one pronounces the takbīr, then recites the Opening of the Qur’an, then sends blessings upon the Prophet ﷺ, and then sincerely supplicates for the deceased. Recitation is performed only after the first takbīr. He then quietly gives the greeting of peace to his right.”"]}},"tuhfa":{},"voc":["seerah",1748],"full":1,"dr":1,"tks":"صحيح: رواه عبد الرزاق (6428)، ومن طريقه ابن الجارود في المنتقى (540)."},{"num":10869,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بن عبدٍ القاري - وَكَانَ فِي عَهْدِ عُمَرَ بْنِ الْخَطَّابِ مَعَ عَبْدِ اللَّهِ بْنِ الْأَرْقَمَ عَلَى بَيْتِ الْمَالِ - أَنَّ عُمَرَ خَرَجَ لَيْلَةً فِي رَمَضَانَ، فَخَرَجَ مَعَهُ عَبْدُ الرَّحْمَنِ بْنُ عبدٍ الْقَارِيَّ، فَطَافَ بِالْمَسْجِدِ، وَأَهْلُ الْمَسْجِدِ أَوْزَاعٌ مُتَفَرِّقُونَ، يُصَلِّي الرَّجُلُ لِنَفْسِهِ، وَيُصَلِّي الرَّجُلُ فَيُصَلِّي بِصَلَاتِهِ الرَّهْطُ، فَقَالَ عُمَرُ: وَاللَّهِ إِنِّي أَظُنُّ لَوْ جَمَعْنَا هَؤُلَاءِ عَلَى قَارِئٍ وَاحِدٍ لَكَانَ أَمْثَلَ، ثُمَّ عَزَمَ عُمَرُ عَلَى ذَلِكَ، وَأَمَرَ أُبَيَّ بْنَ كَعْبٍ أَنْ يَقُومَ لَهُمْ فِي رَمَضَانَ، فَخَرَجَ عُمَرُ عَلَيْهِمْ، وَالنَّاسُ يُصَلُّونَ بِصَلَاةِ قَارِئِهِمْ فَقَالَ عُمَرُ: نِعْمَ الْبِدْعَةُ هِيَ، وَالَّتِي تَنَامُونَ عَنْهَا أَفْضَلُ مِنَ الَّتِي تَقُومُونَ - يُرِيدُ آخِرَ اللَّيْلِ - فَكَانَ النَّاسُ يَقُومُونَ أَوَّلَهُ، وَكَانُوا يَلْعَنُونَ الْكَفَرَةَ فِي النِّصْفِ: اللَّهُمَّ قَاتِلِ الْكَفَرَةَ الَّذِينَ يَصُدُّونَ عَنْ سَبِيلِكَ، وَيُكَذِّبُونَ رُسُلَكَ، وَلَا يُؤْمِنُونَ بِوَعْدِكَ، وَخَالِفْ بَيْنَ كَلِمَتِهِمْ، وَأَلْقِ فِي قُلُوبِهِمُ الرُّعْبَ، وَأَلْقِ عَلَيْهِمْ رِجْزَكَ وَعَذَابَكَ إِلَهَ الْحَقِّ، ثُمَّ يُصَلِّي عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، وَيَدْعُو لِلْمُسْلِمِينَ بِمَا اسْتَطَاعَ مِنْ خَيْرٍ، ثُمَّ يَسْتَغْفِرُ لِلْمُؤْمِنِينَ.","قَالَ: وَكَانَ يَقُولُ إِذَا فَرَغَ مِنْ لَعْنَةِ الْكَفَرَةِ وَصَلاتِهِ عَلَى النَّبِيِّ وَاسْتِغْفَارِهِ لِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَمَسْأَلَتِهِ: اللَّهُمَّ إِيَّاكَ نَعْبُدُ، وَلَكَ نُصَلِّي وَنَسْجُدُ، وَإِلَيْكَ نَسْعَى وَنَحْفِدُ، وَنَرْجُو رَحْمَتَكَ رَبَّنَا، وَنَخَافُ عَذَابَكَ الْجِدَّ، إِنَّ عَذَابَكَ لِمَنْ عَادَيْتَ مُلْحِقٌ، ثُمَّ يُكَبِّرُ وَيَهْوِي سَاجِدًا."],"takhrij":"صحيح: رواه ابن خزيمة (1100) عن الربيع بن سليمان المرادي، نا عبد الله بن وهب، أخبرني يونس، عن ابن شهاب، أخبرني عروة بن الزبير، عن عبدالرحمن بن عبد القاري قال: فذكره.","grade":"صحيح","chapter_ar":"باب الصلاة على النبي ﷺ في آخر القنوت","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Khuzaymah (1100).","chapter_en":"Sending Blessings upon the Prophet ﷺ at the End of the Qunūt","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn ʿAbd al-Qārī—who, during the caliphate of ʿUmar ibn al-Khaṭṭāb, was responsible for the public treasury together with ʿAbdullāh ibn al-Arqam—narrated: ʿUmar went out one night during Ramadan, and ʿAbd al-Raḥmān ibn ʿAbd al-Qārī accompanied him. They walked around the mosque and found its people divided into scattered groups. Some men were praying individually, while others were leading small groups in prayer. ʿUmar said: “By Allah, I think that gathering these people behind a single reciter would be better.” ʿUmar then resolved to do so and instructed Ubayy ibn Kaʿb to lead them in prayer during Ramadan. Later, ʿUmar came out while the people were praying behind their reciter and said: “What an excellent innovation this is! Yet the prayer during the time in which you sleep is better than the prayer during the time in which you stand.” He was referring to the latter part of the night, although the people were performing the prayer during its earlier part. During the latter half of Ramadan, they would supplicate against the disbelievers: “O Allah, fight the disbelievers who obstruct people from Your path, deny Your messengers, and do not believe in Your promise. Divide their unity, cast terror into their hearts, and inflict upon them Your punishment and torment, O Allah of truth.” He would then send blessings upon the Prophet ﷺ, supplicate for the Muslims with whatever good he was able to ask, and seek forgiveness for the believers. When he had finished supplicating against the disbelievers, sending blessings upon the Prophet ﷺ, seeking forgiveness for the believing men and women, and making his requests, he would say: “O Allah, You alone we worship. For You we pray and prostrate. Toward You we strive and hasten. We hope for Your mercy, our Lord, and fear Your severe punishment. Indeed, Your punishment will surely overtake those whom You oppose.” He would then pronounce the takbīr and descend into prostration."]}},"tuhfa":{},"voc":["seerah",1749],"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (1100)."},{"num":10870,"demo":false,"sanad":"","matn":["عَنْ أَبِي حُمَيْدٍ أَوْ أَبِي أُسَيْدٍ الأنصاري قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا دَخَلَ أَحَدُكُمُ الْمَسْجِدَ فَلْيُسَلِّمْ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ لْيَقُلِ: اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ، فَإِذَا خَرَجَ فَلْيَقُلِ: اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ."],"takhrij":"صحيح: رواه أبو داود (465)، وابن ماجه (772)، والبيهقي (2/441-442)، وصحّحه ابن حبان (2048) كلهم من طرق عن ربيعة بن أبي عبدالرحمن، عن عبد الملك بن سعيد بن سويد، عن أبي حميد أو أبي أسيد فذكره.إلا أنه ليس في رواية ابن ماجه ذكر أبي أسيد.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الصلاة والسلام على النبي ﷺ عند دخول المسجد والخروج منه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (465), Ibn Mājah (772), and al-Bayhaqī (2/441–442), and authenticated by Ibn Ḥibbān (2048).","chapter_en":"Sending Blessings and Greetings of Peace upon the Prophet ﷺ When Entering and Leaving the Mosque","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Abū Ḥumayd—or Abū Usayd—al-Anṣārī narrated that the Messenger of Allah ﷺ said: “When one of you enters the mosque, let him send greetings of peace upon the Prophet ﷺ and then say: ‘O Allah, open for me the gates of Your mercy.’ When he leaves, let him say: ‘O Allah, I ask You from Your bounty.’”"]},"buhuth":{"en":["Al-Bayhaqī said:","“The wording concerning the greeting of peace is reliably preserved in this narration.”"]}},"tuhfa":{},"voc":["seerah",1750],"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (465)، وابن ماجه (772)، والبيهقي (2/441-442)، وصححه ابن حبان (2048)."},{"num":10871,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا قَعَدَ قَوْمٌ مَقْعَدًا لَا يَذْكُرُونَ فِيهِ اللهَ عَزَّ وَجَلَّ، وَيُصَلُّونَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِلَّا كَانَ عَلَيْهِمْ حَسْرَةً يَوْمَ الْقِيَامَةِ، وَإِنْ دَخَلُوا الْجَنَّةَ لِلثَّوَابِ."],"takhrij":"صحيح: رواه أحمد (9965)، وصحّحه ابن حبان (591، 592) كلاهما من حديث عبد الرحمن بن مهدي، عن شعبة، عن الأعمش، عن أبي صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الصلاة على النبي ﷺ عند اجتماع القوم قبل تفرقهم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (9965) and authenticated by Ibn Ḥibbān (591, 592).","chapter_en":"Sending Blessings upon the Prophet ﷺ When People Gather before They Disperse","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “No people sit in a gathering in which they do not remember Allah, Mighty and Majestic, and send blessings upon the Prophet ﷺ, except that it will be a source of regret for them on the Day of Resurrection, even if they enter Paradise because of other rewards.”"]}},"tuhfa":{},"voc":["seerah",1751],"full":1,"dr":1,"rep":[10783],"tks":"صحيح: رواه أحمد (9965)، وصححه ابن حبان (591، 592)."},{"num":10872,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا اجْتَمَعَ قَوْمٌ ثُمَّ تَفَرَّقُوا عَنْ غَيْرِ ذِكْرِ اللهِ، وَصَلَاةٍ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِلَّا قَامُوا عَنْ أَنْتَنِ جِيفَةٍ."],"takhrij":"حسن: رواه الطيالسي (1863) –ومن طريقه النسائي في عمل اليوم والليلة (411)- عن يزيد بن إبراهيم التستري، عن أبي الزبير، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب الصلاة على النبي ﷺ عند اجتماع القوم قبل تفرقهم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭayālisī (1863), and through him by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (411).","chapter_en":"Sending Blessings upon the Prophet ﷺ When People Gather before They Disperse","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Jābir narrated that the Messenger of Allah ﷺ said: “No people gather and then disperse without remembering Allah and sending blessings upon the Prophet ﷺ except that they rise from something more foul-smelling than a carcass.”"]}},"tuhfa":{},"voc":["seerah",1752],"full":1,"dr":1,"rep":[10786],"tks":"حسن: رواه الطيالسي (1863)، ومن طريقه النسائي في عمل اليوم والليلة (411)."},{"num":10873,"demo":false,"sanad":"","matn":["عَنْ أَوْسِ بْنِ أَوْسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ مِنْ أَفْضَلِ أَيَّامِكُمْ يَوْمَ الْجُمُعَةِ، فِيهِ خُلِقَ آدَمُ، وَفِيهِ قُبِضَ، وَفِيهِ النَّفْخَةُ، وَفِيهِ الصَّعْقَةُ، فَأَكْثِرُوا عَلَىَّ مِنَ الصَّلاَةِ فِيهِ، فَإِنَّ صَلاَتَكُمْ مَعْرُوضَةٌ عَلَىَّ. قَالَ قَالُوا: يَا رَسُولَ اللَّهِ! وَكَيْفَ تُعْرَضُ صَلاَتُنَا عَلَيْكَ وَقَدْ أَرِمْتَ؟ يَقُولُونَ: بَلِيتَ. فَقَالَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ حَرَّمَ عَلَى الأَرْضِ أَجْسَادَ الأَنْبِيَاءِ."],"takhrij":"صحيح: رواه أبو داود (1047) والنسائي (1374) وابن ماجه (1636) وصحّحه ابن خزيمة (1733)، وابن حبان (910) والحاكم (1029)كلّهم من طريق عبدالرحمن بن يزيد بن جابر، عن أبي الأشعث الصنعاني، عن أوس بن أوس، فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب إكثار الصلاة على النبي ﷺ يوم الجمعة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1047), al-Nasā’ī (1374), and Ibn Mājah (1636), and authenticated by Ibn Khuzaymah (1733).","chapter_en":"Frequently Sending Blessings upon the Prophet ﷺ on Friday","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Aws ibn Aws narrated that the Messenger of Allah ﷺ said: “Among the best of your days is Friday. On it Adam was created, on it he died, on it the Trumpet will be blown, and on it the great blast will occur. Therefore, frequently send blessings upon me on that day, for your blessings are presented to me.” They asked: “O Messenger of Allah, how will our blessings be presented to you after your body has decayed?” He replied: “Allah, Mighty and Majestic, has forbidden the earth from consuming the bodies of the prophets.”"]},"buhuth":{"en":["The phrase “and on it the great blast will occur” refers to loss of consciousness and death."]}},"tuhfa":{},"voc":["seerah",1753],"full":1,"dr":1,"rep":[685,3238,3821,10750,16132],"tks":"صحيح: رواه أبو داود (1047)، والنسائي (1374)، وابن ماجه (1636)، وصححه ابن خزيمة (1733)."},{"num":10874,"demo":false,"sanad":"","matn":["عن أَبِي بن كَعْبٍ عَنْ أَبِيهِ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا ذَهَبَ ثُلُثَا اللَّيْلِ قَامَ فَقَالَ: يَا أَيُّهَا النَّاسُ، اذْكُرُوا اللَّهَ، اذْكُرُوا اللَّهَ، جَاءَتِ الرَّاجِفَةُ، تَتْبَعُهَا الرَّادِفَةُ، جَاءَ الْمَوْتُ بِمَا فِيهِ، جَاءَ الْمَوْتُ بِمَا فِيهِ.","قَالَ أُبَيٌّ: قُلْتُ: يَا رَسُولَ اللَّهِ إِنِّي أُكْثِرُ الصَّلَاةَ عَلَيْكَ، فَكَمْ أَجْعَلُ لَكَ مِنْ صَلَاتِي؟ فَقَالَ: مَا شئت.قال: قُلْتُ: الربع؟.قال: مَا شِئْتَ، فَإِنْ زِدْتَ فَهُوَ خَيْرٌ لَكَ، قُلْتُ: النِّصْفَ؟ قَالَ: مَا شِئْتَ، فَإِنْ زِدْتَ فَهُوَ خَيْرٌ لَكَ ،، قَالَ: قُلْتُ: فالثلثين.قال: مَا شِئْتَ، فَإِنْ زِدْتَ فَهُوَ خَيْرٌ لَكَ، قُلْتُ: أَجْعَلُ لَكَ صَلَاتِي كُلَّهَا، قَالَ: إِذًا تُكْفَى هَمَّكَ، وَيُغْفَرُ لَكَ ذَنْبُكَ."],"takhrij":"حسن: رواه الترمذي (2457)، وأحمد (21241-21242)، والحاكم (3578) كلهم من طريق سفيان هو الثوري، عن عبد الله بن محمد بن عقيل، عن الطفيل بن أبي بن كعب ، عن أبيه قال فذكره.واللفظ للترمذي.","grade":"حسن","chapter_ar":"باب الصلاة على النبي ﷺ عند الهم والشدائد وطلب المغفرة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2457), Aḥmad (21241, 21242), and al-Ḥākim (3578).","chapter_en":"Sending Blessings upon the Prophet ﷺ during Worry and Hardship and When Seeking Forgiveness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":13,"content":{"translation":{"en":["Ubayy ibn Kaʿb narrated: When two-thirds of the night had passed, the Messenger of Allah ﷺ would rise and say: “O people, remember Allah! Remember Allah! The first blast has come, followed by the second. Death has come with all that it contains. Death has come with all that it contains.” Ubayy said: I asked: “O Messenger of Allah, I frequently send blessings upon you. How much of my supplication should I devote to sending blessings upon you?”","He replied: “Whatever you wish.” I asked: “One quarter?” He replied: “Whatever you wish, but if you increase it, that will be better for you.” I asked: “One half?” He replied: “Whatever you wish, but if you increase it, that will be better for you.” I asked: “Then two-thirds?” He replied: “Whatever you wish, but if you increase it, that will be better for you.” I said: “Shall I devote all of my supplication to sending blessings upon you?” He replied: “Then your worries will be taken care of, and your sins will be forgiven.”"]},"buhuth":{"en":["The Companions would also send blessings upon the Prophet ﷺ on other occasions, and all of that is good. Among these occasions were the following:"]}},"tuhfa":{},"voc":["seerah",1754],"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2457)، وأحمد (21241، 21242)، والحاكم (3578)."},{"num":10875,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ امْرَأَةً، قَالَتْ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: صَلِّ عَلَىَّ وَعَلَى زَوْجِي. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: صَلَّى اللَّهُ عَلَيْكِ، وَعَلَى زَوْجِكِ."],"takhrij":"صحيح: رواه أبو داود (1533)، وأحمد (15281)، والنسائي في عمل اليوم والليلة (423)، وصحّحه ابن حبان (916، 918) كلهم من طريق الأسود بن قيس، عن نبيح العنزي، عن جابر بن عبد الله فذكره.وسياق أحمد أطول.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في الصلاة على غير النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1533), Aḥmad (15281), and al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (423), and authenticated by Ibn Ḥibbān (916, 918).","chapter_en":"What Has Been Narrated Concerning Invoking Blessings upon Those Other than the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: A woman said to the Prophet ﷺ: “Invoke Allah’s blessings upon me and my husband.” The Prophet ﷺ said: “May Allah bestow His mercy and blessings upon you and your husband.”"]},"buhuth":{"en":["The statement “May Allah send blessings upon you and your husband” means: May Allah have mercy upon you and your husband."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1533)، وأحمد (15281)، والنسائي في عمل اليوم والليلة (423)، وصححه ابن حبان (916، 918)."},{"num":10876,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى، قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَتَاهُ قَوْمٌ بِصَدَقَتِهِمْ قَالَ: اللَّهُمَّ صَلِّ عَلَى آلِ فُلاَنٍ. فَأَتَاهُ أَبِي بِصَدَقَتِهِ، فَقَالَ: اللَّهُمَّ صَلِّ عَلَى آلِ أَبِي أَوْفَى."],"takhrij":"متفق عليه: رواه البخاري في الزكاة (1497)، ومسلم في الزكاة (1078) كلاهما من طريق شعبة، عن عمرو بن مرة، عن عبد الله بن أبي أوفي فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الصلاة على غير النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1497) and Muslim (1078).","chapter_en":"What Has Been Narrated Concerning Invoking Blessings upon Those Other than the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الصلاة على النبي المختار ﷺ","group_en":"Collection of Narrations Concerning Sending Blessings upon the Chosen Prophet ﷺ","part_no":54,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullāh ibn Abī Awfā narrated: Whenever people brought their charitable contributions to the Prophet ﷺ, he would say: “O Allah, send Your mercy and blessings upon the family of so-and-so.” My father brought his charitable contribution to him, so the Prophet ﷺ said: “O Allah, send Your mercy and blessings upon the family of Abū Awfā.”"]},"buhuth":{"en":["Sending blessings upon all the prophets and messengers is prescribed.","As for those who are not prophets, there is no harm in invoking blessings upon them occasionally, provided that this is not adopted as a habitual and distinctive formula reserved for them. If it is adopted as such a distinguishing practice, despite their not possessing the rank that would warrant it, then refraining from it becomes necessary."]}},"tuhfa":{},"full":1,"dr":1,"rep":[4112,11116],"tks":"متفق عليه: رواه البخاري (1497)، ومسلم (1078)."},{"num":10877,"demo":false,"sanad":"","matn":["عن النعمان بن بشير، عن النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قال: الدعاء هو العبادة ثم قرأ ﴿وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ إِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِي سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ﴾) [سورة غافر: 60]."],"takhrij":"صحيح: رواه أبو داود (1479)، والترمذي (3372)، وابن ماجه (3828)، وأحمد (18352)، وصحّحه ابن حبان (890)، والحاكم (1/490-491) كلهم من طرق عن ذر بن عبد الله الهمداني، عن يُسيع الحضرمي، عن النعمان بن بشير فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الدعاء هو العبادة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1479), al-Tirmidhī (3372), Ibn Mājah (3828), and Aḥmad (18352).","chapter_en":"Supplication Is Worship","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في فضل الدعاء","group_en":"Collection of Narrations Concerning the Virtue of Supplication","part_no":54,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr narrated that the Prophet ﷺ said: “Supplication is worship.” He then recited: “Your Lord has said: ‘Call upon Me, and I will answer you. Indeed, those who are too arrogant to worship Me will enter Hell humiliated.’” [Sūrat Ghāfir 40:60]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13222],"tks":"صحيح: رواه أبو داود (1479)، والترمذي (3372)، وابن ماجه (3828)، وأحمد (18352)."},{"num":10878,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيْسَ شَيْءٌ أَكْرَمَ عَلَى اللَّهِ تَعَالَى مِنَ الدُّعَاءِ."],"takhrij":"حسن: رواه الترمذي (3370)، وابن ماجه (3829)، وأحمد (7848)، وصحّحه ابن حبان (870)، والحاكم (1817) كلهم من طرق عن عمران القطان، عن قتادة، عن سعيد بن أبي الحسن، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب الدعاء أكرم شيء على اللّٰه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3370), Ibn Mājah (3829), and Aḥmad (7848), and authenticated by Ibn Ḥibbān (870).","chapter_en":"Supplication Is the Most Honorable Thing before Allah","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في فضل الدعاء","group_en":"Collection of Narrations Concerning the Virtue of Supplication","part_no":54,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Nothing is more honorable before Allah, the Exalted, than supplication.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3370)، وابن ماجه (3829)، وأحمد (7848)، وصححه ابن حبان (870)."},{"num":10879,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَقُولُ اللَّهُ تَعَالَى: أَنَا عِنْدَ ظَنِّ عَبْدِي بِي، وَأَنَا مَعَهُ إِذَا ذَكَرَنِي.","وفي رواية: إن الله عزوجل يقول: أنا عند ظن عبدي بي، وأنا معه إذا دعاني."],"takhrij":"متفق عليه: رواه البخاري في التوحيد (7405)، ومسلم في الذكر والدعاء (2675: 2) كلاهما من طريق الأعمش، عن أبي صالح، عن أبي هريرة فذكره باللفظ الأول.","grade":"متفق عليه","chapter_ar":"باب إن اللّٰه عند ظن العبد فيستجيب دعاءه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: The first wording was narrated by al-Bukhārī (7405) and Muslim (2675/2).","chapter_en":"Allah Is as His Servant Expects Him to Be and Answers His Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في فضل الدعاء","group_en":"Collection of Narrations Concerning the Virtue of Supplication","part_no":54,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Allah, the Exalted, says: ‘I am as My servant expects Me to be, and I am with him when he remembers Me…’” Another narration states: “Allah, Mighty and Majestic, says: ‘I am as My servant expects Me to be, and I am with him when he calls upon Me.’”"]},"buhuth":{"en":["The second wording was narrated by Muslim (2675/19)."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ، أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ، فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي لَعَلَّهُمْ يَرْشُدُونَ﴾ [البقرة: ١٨٦]."],"en":["Allah, the Exalted, said:","“When My servants ask you concerning Me, then indeed I am near. I answer the supplication of the supplicant when he calls upon Me. So let them respond to Me and believe in Me, so that they may be rightly guided.”","[Sūrat al-Baqarah 2:186]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7405)، ومسلم (2675: 2) باللفظ الأول."},{"num":10880,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَقُولُ اللَّهُ: أَنَا عِنْدَ ظَنِّ عَبْدِي بِي، وَأَنَا مَعَهُ إِذَا دَعَانِي."],"takhrij":"صحيح: رواه أحمد (13192)، وأبو يعلى (3232) كلاهما من حديث أبي داود سليمان (هو الطيالسي)، حدثنا شعبة، حدثنا قتادة، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب إن اللّٰه عند ظن العبد فيستجيب دعاءه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (13192) and Abū Yaʿlā (3232).","chapter_en":"Allah Is as His Servant Expects Him to Be and Answers His Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في فضل الدعاء","group_en":"Collection of Narrations Concerning the Virtue of Supplication","part_no":54,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ said: “Allah says: ‘I am as My servant expects Me to be, and I am with him when he calls upon Me.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3521],"tks":"صحيح: رواه أحمد (13192)، وأبو يعلى (3232)."},{"num":10881,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ مَنْ لَمْ يَسْأَلِ اللَّهَ يَغْضَبْ عَلَيْهِ.وَفِي لفظ: من لَمْ يدع الله."],"takhrij":"حسن: رواه الترمذي (3373) –واللفظ له-، وابن ماجه (3827)، وأحمد (9719)، -واللفظ الآخر لهما-، والحاكم (1/491) كلهم من طرق عن أبي المليح المدني، قال: سمعت أبا صالح، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب أن اللّٰه تعالى يحب أن يُسأل ويغضب إذا لم يُسأل","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3373), whose wording is cited here, Ibn Mājah (3827), and Aḥmad (9719). The second wording is that of Ibn Mājah and Aḥmad.","chapter_en":"Allah Loves to Be Asked and Becomes Angry When He Is Not Asked","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في فضل الدعاء","group_en":"Collection of Narrations Concerning the Virtue of Supplication","part_no":54,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever does not ask Allah, Allah becomes angry with him.” Another wording states: “Whoever does not call upon Allah.”"]},"buhuth":{"en":["Al-Ḥākim added:","“Allah becomes angry with the one who does this, and no one other than Him behaves in this manner.”","This refers to supplication."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3373) - واللفظ له -، وابن ماجه (3827)، وأحمد (9719)، واللفظ الآخر لهما."},{"num":10882,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، قَالَ: دَعَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَاءٍ فَتَوَضَّأَ، ثُمَّ رَفَعَ يَدَيْهِ فَقَالَ: اللَّهُمَّ اغْفِرْ لِعُبَيْدٍ أَبِي عَامِرٍ. وَرَأَيْتُ بَيَاضَ إِبْطَيْهِ، فَقَالَ: اللَّهُمَّ اجْعَلْهُ يَوْمَ الْقِيَامَةِ فَوْقَ كَثِيرٍ مِنْ خَلْقِكَ مِنَ النَّاسِ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6383)، ومسلم في فضائل الصحابة (2498) كلاهما عن أبي كريب محمد بن العلاء، ثنا أبو أسامة، عن بريد بن عبدالله، عن أبي بردة، عن أبيه أبي موسى الأشعري قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب استحباب الوضوء عند الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6383) and Muslim (2498).","chapter_en":"The Recommendation of Performing Ablution before Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":1,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī narrated: The Prophet ﷺ asked for water and performed ablution. He then raised his hands and said: “O Allah, forgive ʿUbayd Abū ʿĀmir.” I could see the whiteness of his armpits. He then said: “O Allah, on the Day of Resurrection, raise him above many of Your human creation.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6383)، ومسلم (2498)."},{"num":10883,"demo":false,"sanad":"","matn":["عَبْدَ اللَّهِ بْنَ زَيْدٍ الْأَنْصَارِيَّ: أَخْبَرَهُ  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ إِلَى الْمُصَلَّى يَسْتَسْقِي. وَأَنَّهُ لَمَّا أَرَادَ أَنْ يَدْعُوَ اسْتَقْبَلَ الْقِبْلَةَ، وَحَوَّلَ رِدَاءَهُ."],"takhrij":"متفق عليه: رواه البخاري في الاستسقاء (1028)، ومسلم (894: 3) كلاهما من طريق يحيى بن سعيد (هو الأنصاري) قال: أخبرني أبو بكر بن محمد بن عمرو (هو ابن حزم)، أن عباد بن تميم أخبره، أن عبد الله بن زيد الأنصاري أخبره فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في استقبال القبلة عند الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1028) and Muslim (894/3).","chapter_en":"Facing the Direction of Prayer When Supplicating","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn Zayd al-Anṣārī narrated: The Messenger of Allah ﷺ went out to the prayer ground to seek rain. When he intended to supplicate, he faced the qiblah and turned his cloak around."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1028)، ومسلم (894: 3)."},{"num":10884,"demo":false,"sanad":"","matn":["عن عُمَرَ بن الْخَطَّابِ قَالَ:  لَمَّا كَانَ يَوْمُ بَدْرٍ نَظَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْمُشْرِكِينَ وَهُمْ أَلْفٌ، وَأَصْحَابُهُ ثَلَاثُمِائَةٍ وَتِسْعَةَ عَشَرَ رَجُلًا، فَاسْتَقْبَلَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْقِبْلَةَ، ثُمَّ مَدَّ يَدَيْهِ فَجَعَلَ يَهْتِفُ بِرَبِّهِ: اللَّهُمَّ! أَنْجِزْ لِي مَا وَعَدْتَنِي، اللَّهُمَّ! آتِ مَا وَعَدْتَنِي، اللَّهُمَّ! إِنْ تَُهْلِكْ هَذِهِ الْعِصَابَةَُ مِنْ أَهْلِ الْإِسْلَامِ لَا تُعْبَدْ فِي الْأَرْضِ. فَمَا زَالَ يَهْتِفُ بِرَبِّهِ، مَادًّا يَدَيْهِ، مُسْتَقْبِلَ الْقِبْلَةِ، حَتَّى سَقَطَ رِدَاؤُهُ عَنْ مَنْكِبَيْهِ، فَأَتَاهُ."],"takhrij":"صحيح: رواه مسلم في الجهاد (58:1763) من طرق عن عكرمة بن عمار، حدثني أبو زميل سماك الحنفي، حدثني عبدالله بن عباس، قال: حدثني عمر بن الخطاب فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في استقبال القبلة عند الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1763/58).","chapter_en":"Facing the Direction of Prayer When Supplicating","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb narrated: On the Day of Badr, the Messenger of Allah ﷺ looked at the polytheists, who numbered one thousand, while his Companions numbered three hundred and nineteen. The Prophet of Allah ﷺ faced the qiblah, extended his hands, and began calling earnestly upon his Lord: “O Allah, fulfill for me what You promised me. O Allah, grant me what You promised me. O Allah, if this group from the people of Islam is destroyed, You will not be worshipped upon the earth.” He continued calling earnestly upon his Lord with his hands extended and while facing the qiblah until his cloak fell from his shoulders. This forms part of the hadith."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (58:1763)."},{"num":10885,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأشعري قَالَ: لَمَّا فَرَغَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ حُنَيْنٍ، بَعَثَ أَبَا عَامِرٍ عَلَى جَيْشٍ إِلَى أوطاس.الحديث.","وفيه: ثم رفع يديه فقال: اللهم اغفر لعبيد أبي عامر.ورأيت بياض إبطيه."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6323)، ومسلم في فضائل الصحابة (2498) كلاهما عن أبي كريب محمد بن العلاء، ثنا أبو أسامة، عن بريد بن عبدالله، عن أبي بردة، عن أبيه أبي موسى الأشعري قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في رفع اليدين في الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6323) and Muslim (2498).","chapter_en":"Raising the Hands during Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī narrated: When the Prophet ﷺ had finished the Battle of Ḥunayn, he sent Abū ʿĀmir at the head of an army toward Awṭās. This forms part of the hadith. It states: He then raised his hands and said: “O Allah, forgive ʿUbayd Abū ʿĀmir.” I could see the whiteness of his armpits."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6323)، ومسلم (2498)."},{"num":10886,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر قال: بعث النبي صلى الله عليه وسلم خالد بن الوليد إلى بني جذيمة، فدعاهم إلى الإسلام.الحديث.","وفيه: حَتَّى قَدِمْنَا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْنَاهُ، فَرَفَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَهُ فَقَالَ: اللَّهُمَّ إِنِّي أَبْرَأُ عليك مِمَّا صَنَعَ خَالِدٌ."],"takhrij":"صحيح: رواه البخاري (4339) من طريق معمر، عن الزهري، عن سالم، عن أبيه قال:فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في رفع اليدين في الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4339).","chapter_en":"Raising the Hands during Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿUmar narrated: The Prophet ﷺ sent Khālid ibn al-Walīd to Banū Jadhīmah, and he called them to Islam. This forms part of the hadith. It states: When we returned to the Prophet ﷺ and informed him of what had happened, the Prophet ﷺ raised his hands and said: “O Allah, I declare before You that I am free of what Khālid has done.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (4339)."},{"num":10887,"demo":false,"sanad":"","matn":["عَنْ سَلْمَانَ الْفَارِسِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ حَيِيٌّ كَرِيمٌ يَسْتَحِي إِذَا رَفَعَ الرَّجُلُ إِلَيْهِ يَدَيْهِ أَنْ يَرُدَّهُمَا صِفْرًا خَائِبَتَيْنِ."],"takhrij":"حسن: رواه أبو داود (1488)، والترمذي (3556)، وابن ماجه (3865) –واللفظ لهما-وصحّحه ابن حبان (876)، والحاكم (1/497) كلهم من طرق عن جعفر بن ميمون صاحب الأنماط، عن أبي عثمان النهدي، عن سلمان الفارسي فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في رفع اليدين في الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (1488), al-Tirmidhī (3556), Ibn Mājah (3865), whose wording is cited here, and Ibn Ḥibbān (876).","chapter_en":"Raising the Hands during Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Salmān al-Fārisī narrated that the Prophet ﷺ said: “Indeed, Allah is Modest and Generous. He is too generous, when a man raises his hands to Him, to return them empty and disappointed.”"]},"buhuth":{"en":["The phrase “to return them empty and disappointed” means to return them with nothing granted in them.","During supplication, the hands are held together like the hands of a person asking to receive something. I do not know of anything in the Sunnah or in the statements of the scholars indicating that the hands should be spread apart during supplication.","It is authentically established that the Prophet ﷺ raised his hands while seeking rain and during military expeditions until the whiteness of his armpits could be seen. However, it has not been established that he separated his hands from one another."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1488)، والترمذي (3556)، وابن ماجه (3865) - واللفظ لهما -، وابن حبان (876)."},{"num":10888,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَرْفَعُ يَدَيْهِ فِي شَىْءٍ مِنْ دُعَائِهِ إِلاَّ فِي الاِسْتِسْقَاءِ، وَإِنَّهُ يَرْفَعُ حَتَّى يُرَى بَيَاضُ إِبْطَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في الاستسقاء (1031)، ومسلم في صلاة الاستسقاء (896: 7) كلاهما من طريق سعيد (هو ابن أبي عروبة)، عن قتادة، عن أنس بن مالك قال:فذكره.","grade":"متفق عليه","chapter_ar":"باب في رفع الأيدي في الاستسقاء والمبالغة فيه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1031) and Muslim (896/7).","chapter_en":"Raising the Hands High When Seeking Rain","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Mālik narrated: “The Prophet ﷺ would not raise his hands during any of his supplications except when seeking rain. On that occasion, he would raise them so high that the whiteness of his armpits could be seen.”"]},"buhuth":{"en":["Anas’s statement, “He would not raise his hands during any of his supplications,” is a negation of what Anas personally witnessed. It does not necessarily negate what other Companions witnessed. It has been established through numerous widely transmitted reports that the Prophet ﷺ raised his hands during supplication on many occasions.","Some scholars interpreted Anas’s words as referring specifically to the extreme height to which the Prophet ﷺ raised his hands during the prayer for rain, until the whiteness of his armpits could be seen.","Thābit narrated from Anas, as recorded in Ṣaḥīḥ Muslim (895), without mentioning any negation of raising the hands. Rather, he said:","“I saw the Messenger of Allah ﷺ raising his hands during supplication until the whiteness of his armpits could be seen.”","Others besides Thābit also narrated this from Anas. Al-Bukhārī (6341) stated that al-Uwaysī narrated from Muḥammad ibn Jaʿfar, from Yaḥyā ibn Saʿīd and Sharīk, who both heard Anas narrate that the Prophet ﷺ raised his hands until the whiteness of his armpits could be seen.","Therefore, what is authentically established from the Prophet ﷺ is that he raised his hands during supplication. As far as I know, there is no disagreement among the scholars concerning this."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2959],"tks":"متفق عليه: رواه البخاري (1031)، ومسلم (896: 7)."},{"num":10889,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَسْقَى حَتَّى رَأَيْتُ - أَوْ رُؤِيَ - بَيَاضُ إِبْطَيْهِ."],"takhrij":"صحيح: رواه ابن ماجه (1271)- واللفظ له- وأحمد (8830)، وصحّحه ابن خزيمة (1413) كلهم من طريق سليمان التيمي، عن بركة (هو أبو الوليد)، عن بشير بن نهيك، عن أبي هريرة فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب في رفع الأيدي في الاستسقاء والمبالغة فيه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (1271), whose wording is cited here, Aḥmad (8830), and authenticated by Ibn Khuzaymah (1413).","chapter_en":"Raising the Hands High When Seeking Rain","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated: “The Prophet ﷺ supplicated for rain until I saw—or it was seen—the whiteness of his armpits.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (1271) - واللفظ له -، وأحمد (8830)، وصححه ابن خزيمة (1413)."},{"num":10890,"demo":false,"sanad":"","matn":["عَنْ مَالِكِ بْنِ يَسَارٍ السَّكُونِيِّ ثُمَّ الْعَوْفِيِّ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا سَأَلْتُمُ اللَّهَ، فَاسْأَلُوهُ بِبُطُونِ أَكُفِّكُمْ، وَلاَ تَسْأَلُوهُ بِظُهُورِهَا."],"takhrij":"حسن: رواه أبو داود (1486) عن سليمان بن عبد الحميد البهراني، قال: قرأته فى أصل إسماعيل - يعنى ابن عياش - حدثنى ضمضم، عن شريح، حدثنا أبو ظبية، أن أبا بحرية السكوني، حدثه عن مالك بن يسار فذكره.","grade":"حسن","chapter_ar":"باب دعاء اللّٰه تعالى ببطون الأكف","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (1486).","chapter_en":"Supplicating to Allah with the Palms Facing Upward","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":5,"content":{"translation":{"en":["Mālik ibn Yasār al-Sukūnī, then al-ʿAwfī, narrated that the Messenger of Allah ﷺ said: “When you ask Allah, ask Him with the palms of your hands, and do not ask Him with the backs of your hands.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1486)."},{"num":10891,"demo":false,"sanad":"","matn":["عن أنس أن النبي صلى الله عليه وسلم استسقى فأشار بظهر كفيه إلى السماء.وفي لفظ: أن رسول الله صلى الله عليه وسلم كان إذا دعا، جعل ظاهر كفيه مما يلي وجهه، وباطنهما مما يلي الأرض."],"takhrij":"صحيح: رواه مسلم في صلاة الاستسقاء (896: 6) عن عبد بن حميد، ثنا الحسن بن موسى (هو الأشيب)، ثنا حماد بن سلمة، عن ثابت، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في جعل ظهور الكفين إلى السماء في دعاء الاستسقاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: The first wording was narrated by Muslim (896/6).","chapter_en":"Placing the Backs of the Hands toward the Sky When Supplicating for Rain","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Anas narrated: “The Prophet ﷺ supplicated for rain and pointed the backs of his hands toward the sky.” Another wording states: “When the Messenger of Allah ﷺ supplicated, he would position the backs of his hands toward his face and their palms toward the ground.”"]},"buhuth":{"en":["The other wording was narrated by Imam Aḥmad (12239)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (896: 6)."},{"num":10892,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، قَالَ كُنْتُ أُصَلِّي وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ وَعُمَرُ مَعَهُ، فَلَمَّا جَلَسْتُ بَدَأْتُ بِالثَّنَاءِ عَلَى اللَّهِ، ثُمَّ الصَّلاَةِ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ دَعَوْتُ لِنَفْسِي فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَلْ تُعْطَهْ، سَلْ تُعْطَهْ."],"takhrij":"حسن: رواه الترمذي (593) عن محمود بن غيلان حدثنا يحيى بن آدم حدثنا أبو بكر بن عياش عن عاصم عن زر عن عبد الله فذكره.","grade":"حسن","chapter_ar":"باب من آداب الدعاء أن يثنى على اللّٰه عز وجل، ثم يصلى على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (593).","chapter_en":"Among the Etiquettes of Supplication Is to Praise Allah, Mighty and Majestic, and Then Send Blessings upon the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Ibn Masʿūd narrated: I was praying while the Prophet ﷺ was present with Abū Bakr and ʿUmar. When I sat, I began by praising Allah, then sent blessings upon the Prophet ﷺ, and afterward supplicated for myself. The Prophet ﷺ said: “Ask, and you will be given. Ask, and you will be given.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (593)."},{"num":10893,"demo":false,"sanad":"","matn":["عن فَضَالَةَ بن عُبيد صاحب رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: سَمِعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلاً يَدْعُو فِي صَلاَتِهِ لَمْ يُمَجِّدِ اللَّهَ تَعَالَى وَلَمْ يُصَلِّ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَجِلَ هَذَا. ثُمَّ دَعَاهُ فَقَالَ لَهُ أَوْ لِغَيْرِهِ إِذَا صَلَّى أَحَدُكُمْ فَلْيَبْدَأْ بِتَحْمِيدِ رَبِّهِ جَلَّ وَعَزَّ وَالثَّنَاءِ عَلَيْهِ ثُمَّ يُصَلِّي عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ يَدْعُو بَعْدُ بِمَا شَاءَ."],"takhrij":"صحيح: رواه أبو داود (1481)، والترمذي (3477) وصحّحه ابن خزيمة (710)، والحاكم (1/230) كلهم من طريق عبدالله بن يزيد المُقرئ، ثنا حيوة بن شريح، أخبرني أبو هاني حُميد بن هانئ، أن أبا علي عمرو بن مالك الجَنْبيَّ أخبره، أنه سمع فَضالة بن عبيد فذكر مثله.واللفظ لأبي داود.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب من آداب الدعاء أن يثنى على اللّٰه عز وجل، ثم يصلى على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1481) and al-Tirmidhī (3477), and authenticated by Ibn Khuzaymah (710) and al-Ḥākim (1/230).","chapter_en":"Among the Etiquettes of Supplication Is to Praise Allah, Mighty and Majestic, and Then Send Blessings upon the Prophet ﷺ","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Faḍālah ibn ʿUbayd, a Companion of the Messenger of Allah ﷺ, narrated: The Messenger of Allah ﷺ heard a man supplicating during his prayer without glorifying Allah or sending blessings upon the Prophet ﷺ. The Messenger of Allah ﷺ said: “This man has been hasty.” He then called him and said to him—or to someone else: “When one of you prays, let him begin by glorifying and praising his Lord. Then let him send blessings upon the Prophet ﷺ. After that, let him supplicate for whatever he wishes.”"]},"buhuth":{"en":["Al-Nasā’ī also narrated it (1284) through Abū Hāniʾ with the wording:","The Messenger of Allah ﷺ heard a man supplicating during the prayer without praising Allah or sending blessings upon the Prophet ﷺ.","The Messenger of Allah ﷺ said:","“You have been hasty, O worshipper.”","The Messenger of Allah ﷺ then taught them the proper manner of supplication.","The Messenger of Allah ﷺ also heard another man praying who glorified and praised Allah and sent blessings upon the Prophet ﷺ.","The Messenger of Allah ﷺ said:","“Supplicate, and you will be answered. Ask, and you will be given.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2172,10867],"tks":"صحيح: رواه أبو داود (1481)، والترمذي (3477)، وصححه ابن خزيمة (710)، والحاكم (1/230)."},{"num":10894,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي صلى الله عليه وسلم في قوله عز وجل: ﴿وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا﴾ [سورة الإسراء: 110] قالت: أنزل هذا في الدعاء."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6327)، ومسلم في الصلاة (447) كلاهما من طريق هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب الاعتدال بالصوت في الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6327) and Muslim (447).","chapter_en":"Moderation of the Voice during Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["ʿĀ’ishah said regarding the words of Allah, Mighty and Majestic: “Do not raise your voice excessively in your prayer, nor lower it completely.” She said: “This verse was revealed concerning supplication.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿ادْعُوا رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً، إِنَّهُ لَا يُحِبُّ الْمُعْتَدِينَ﴾ [سورة الأعراف: ٥٥].","وقال تعالى: ﴿وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَابْتَغِ بَيْنَ ذَلِكَ سَبِيلًا﴾ [الإسراء: ١١٠]."],"en":["Allah, the Exalted, said:","“Call upon your Lord humbly and privately. Indeed, He does not love the transgressors.”","[Sūrat al-Aʿrāf 7:55]","And He, the Exalted, said:","“Do not raise your voice excessively in your prayer, nor lower it completely, but seek a way between the two.”","[Sūrat al-Isrāʾ 17:110]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6327)، ومسلم (447)."},{"num":10895,"demo":false,"sanad":"","matn":["عن أَبِي مُوسَى الأَشْعَرِيِّ قَالَ: لمَّا غَزَا رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ - أَوْ قَالَ: لمَّا تَوَجَّهَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَشْرَفَ النَّاسُ عَلَى وَادٍ، فَرَفَعُوا أَصْوَاتَهُمْ بِالتَّكْبِيرِ: الله أَكْبَرُ الله أَكْبَرُ، لاَ إِلَهَ إِلاَّ الله .فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ارْبَعُوا عَلَى أَنْفُسِكُمْ، إِنَّكُمْ لاَ تَدْعُونَ أَصَمَّ وَلاَ غَائِبًا، إِنَّكُمْ تَدْعُونَ سَمِيعًا قَرِيبًا وَهْوَ مَعَكُمْ.وَأَنَا خَلْفَ دَابَّةِ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَمِعَنِي وَأَنَا أَقُولُ لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بالله، فَقَالَ لِي: يَا عَبْدَ الله بْنَ قَيْسٍ.قُلْتُ: لَبَّيْكَ رَسُولَ الله.قَالَ: أَلاَ أَدُلُّكَ عَلَى كَلِمَةٍ مِنْ كَنْزٍ مِنْ كُنُوزِ الجَنَّةِ؟.قُلْتُ: بَلَى يَا رَسُولَ الله فِدَاكَ أَبِي وَأُمِّي.قَالَ: لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بالله.","وفي رواية: والذي تدعونه أقرب إلى أحدكم من عنق راحلة أحدكم."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4202) ومسلم في الذكر والدعاء (44:2704) كلاهما من طريق عاصم (هو الأحول) عن أبي عثمان (هو النهدي) عن أبي موسى قال: فذكره.واللفظ الأول للبخاري، واللفظ الثاني عند مسلم (2704: 47) من طريق خالد الحذاء، عن أبي عثمان، عن أبي موسى الأشعري به.","grade":"متفق عليه","chapter_ar":"باب الاعتدال بالصوت في الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4202) and Muslim (2704/44).","chapter_en":"Moderation of the Voice during Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī narrated: When the Messenger of Allah ﷺ fought at Khaybar—or when he set out toward it—the people came upon a valley and raised their voices, proclaiming: “Allah is the Greatest! Allah is the Greatest! There is no deity worthy of worship except Allah!” The Messenger of Allah ﷺ said: “Be gentle with yourselves. You are not calling upon one who is deaf or absent. You are calling upon One who hears, who is near, and who is with you.” I was behind the mount of the Messenger of Allah ﷺ, and he heard me saying: “There is no power and no strength except through Allah.” He said: “O ʿAbdullāh ibn Qays.” I replied: “At your service, O Messenger of Allah.” He said: “Shall I direct you to a phrase that is one of the treasures of Paradise?” I replied: “Certainly, O Messenger of Allah. May my father and mother be sacrificed for you.” He said: “There is no power and no strength except through Allah.” Another narration states: “The One upon whom you are calling is nearer to each of you than the neck of his riding animal.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4202)، ومسلم (44:2704)."},{"num":10896,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُعْجِبُهُ أَنْ يَدْعُوَ ثَلاَثًا، وَيَسْتَغْفِرَ ثَلاَثًا."],"takhrij":"صحيح: رواه أبو داود (1524)، وأحمد (3744)، وصحّحه ابن حبان (923) كلهم من طريق إسرائيل، عن أبي إسحاق، عن عمرو بن ميمون، عن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب استحباب تكرير الدعاء ثلاثًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1524) and Aḥmad (3744), and authenticated by Ibn Ḥibbān (923).","chapter_en":"The Recommendation of Repeating a Supplication Three Times","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated: “The Messenger of Allah ﷺ liked to supplicate three times and seek forgiveness three times.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1524)، وأحمد (3744)، وصححه ابن حبان (923)."},{"num":10897,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ سَأَلَ اللَّهَ الْجَنَّةَ ثَلاَثَ مَرَّاتٍ، قَالَتِ الْجَنَّةُ: اللَّهُمَّ أَدْخِلْهُ الْجَنَّةَ. وَمَنِ اسْتَجَارَ مِنَ النَّارِ ثَلاَثَ مَرَّاتٍ، قَالَتِ النَّارُ: اللَّهُمَّ أَجِرْهُ مِنَ النَّارِ."],"takhrij":"صحيح: رواه الترمذي (2572)، والنسائي (5521)، وابن ماجه (4340)، وصحّحه ابن حبان (1034) كلهم من طريق أبي الأحوص- وأحمد (13173)، وصحّحه الحاكم (1960) من طريق إسرائيل- كلاهما عن أبي إسحاق، عن بريد بن أبي مريم، عن أنس بن مالك فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب استحباب تكرير الدعاء ثلاثًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2572), al-Nasā’ī (5521), and Ibn Mājah (4340), and authenticated by Ibn Ḥibbān (1034).","chapter_en":"The Recommendation of Repeating a Supplication Three Times","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":10,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “Whoever asks Allah for Paradise three times, Paradise says: ‘O Allah, admit him into Paradise.’ Whoever seeks Allah’s protection from the Fire three times, the Fire says: ‘O Allah, protect him from the Fire.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2572)، والنسائي (5521)، وابن ماجه (4340)، وصححه ابن حبان (1034)."},{"num":10898,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لِلَّهِ تِسْعَةٌ وَتِسْعُونَ اسْمًا مِائَةٌ إِلاَّ وَاحِدًا، لاَ يَحْفَظُهَا أَحَدٌ إِلاَّ دَخَلَ الْجَنَّةَ، وَهْوَ وَتْرٌ يُحِبُّ الْوَتْرَ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6410)، ومسلم في الذكر والدعاء (2677: 5) كلاهما من طريق سفيان بن عيينة، عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب دعاء اللّٰه تعالى بأسمائه الحسنى","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6410) and Muslim (2677).","chapter_en":"Calling upon Allah by His Most Beautiful Names","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Allah has ninety-nine names—one hundred minus one. Whoever preserves them will enter Paradise. He is One and loves what is odd-numbered.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَلِلّٰهِ الْأَسْمَاءُ الْحُسْنَىٰ فَادْعُوهُ بِهَا، وَذَرُوا الَّذِينَ يُلْحِدُونَ فِي أَسْمَائِهِ، سَيُجْزَوْنَ مَا كَانُوا يَعْمَلُونَ﴾ [الأعراف: ١٨٠]."],"en":["Allah, the Exalted, said:","“To Allah belong the Most Beautiful Names, so call upon Him by them. Leave those who deviate concerning His names; they will be recompensed for what they used to do.”","[Sūrat al-Aʿrāf 7:180]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[242,13527],"tks":"متفق عليه: رواه البخاري (6410)، ومسلم (2677)."},{"num":10899,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب الأسلمي أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمِعَ رَجُلاً يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ أَنِّي أَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لاَ إِلَهَ إِلاَّ أَنْتَ الأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ، وَلَمْ يُولَدْ، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ.فَقَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَقَدْ سَأَلْتَ اللَّهَ بِالاِسْمِ الَّذِي إِذَا سُئِلَ بِهِ أَعْطَى، وَإِذَا دُعي بِهِ أَجَابَ."],"takhrij":"صحيح: رواه أبو داود (1493، 1494)، وابن ماجه (3857)، والترمذي (3475)، وصحّحه ابن حبان (891)، والحاكم (1858) كلهم من طريق مالك بن مغول، عن عبدالله بن بريدة، عن أبيه فذكر الحديث.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب دعاء اللّٰه تعالى بأسمائه الحسنى","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1493, 1494), Ibn Mājah (3857), and al-Tirmidhī (3475), and authenticated by Ibn Ḥibbān (891).","chapter_en":"Calling upon Allah by His Most Beautiful Names","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb al-Aslamī narrated: The Messenger of Allah ﷺ heard a man saying: “O Allah, I ask You by my testimony that You are Allah. There is no deity worthy of worship except You, the One, the Self-Sufficient Master, who neither begets nor was born, and there is none comparable to Him.” The Messenger of Allah ﷺ said: “You have asked Allah by the Name through which, when He is asked, He gives, and when He is called upon, He answers.”"]}},"tuhfa":{},"full":1,"rep":[2186,10966,11035],"tks":"صحيح: رواه أبو داود (1493، 1494)، وابن ماجه (3857)، والترمذي (3475)، وصححه ابن حبان (891)."},{"num":10900,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: اسْمُ اللَّهِ الْأَعْظَمُ الَّذِي إِذَا دُعِيَ بِهِ أَجَابَ فِي ثَلَاثٍ سُوَرٍ من الْقُرْآنِ: فِي الْبَقَرَةِ، وَآلِ عِمْرَانَ، وَطَهَ."],"takhrij":"حسن: رواه الطحاوي في شرح المشكل (176)، والطبراني في الكبير (7925)، والحاكم (1861)، والفريابي في فضائل القرآن (47) كلهم من طريق الوليد بن مسلم، حدثني عبدالله بن العلاء بن زبر، حدثنا القاسم بن عبد الرحمن، عن أبي أمامة فذكره.واللفظ للطبراني،","grade":"حسن","chapter_ar":"باب دعاء اللّٰه تعالى بأسمائه الحسنى","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭaḥāwī in Sharḥ Mushkil al-Āthār (176), al-Ṭabarānī in al-Muʿjam al-Kabīr (8/282), and al-Ḥākim (1861).","chapter_en":"Calling upon Allah by His Most Beautiful Names","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Abū Umāmah narrated that the Prophet ﷺ said: “The Greatest Name of Allah, by which He answers when He is called upon, is found in three chapters of the Qur’an: al-Baqarah, Āl ʿImrān, and Ṭā Hā.”"]},"buhuth":{"en":["Al-Ḥākim added that al-Qāsim said:","“I searched for it and found in Sūrat al-Baqarah, in Āyat al-Kursī:","‘Allah—there is no deity worthy of worship except Him, the Ever-Living, the Sustainer of all existence.’","In Sūrat Āl ʿImrān:","‘Alif, Lām, Mīm. Allah—there is no deity worthy of worship except Him, the Ever-Living, the Sustainer of all existence.’","And in Sūrat Ṭā Hā:","‘All faces will be humbled before the Ever-Living, the Sustainer of all existence, and whoever bears wrongdoing will have failed.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12722],"tks":"حسن: رواه الطحاوي في شرح مشكل الآثار (176)، والطبراني في الكبير (7925)، والحاكم (1861)."},{"num":10901,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّهُ كَانَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا وَرَجُلٌ يُصَلِّي، ثُمَّ دَعَا: اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ، لاَ إِلَهَ إِلاَّ أَنْتَ الْمَنَّانُ، بَدِيعُ السَّمَوَاتِ وَالأَرْضِ، يَا ذَا الْجَلاَلِ وَالإِكْرَامِ، يَا حَىُّ يَا قَيُّومُ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَقَدْ دَعَا اللَّهَ بِاسْمِهِ الْعَظِيمِ الَّذِي إِذَا دُعِيَ بِهِ أَجَابَ، وَإِذَا سُئِلَ بِهِ أَعْطَى."],"takhrij":"حسن: رواه أبو داود (1495)، والنسائي (1300) وصحّحه ابن حبان (893)، والحاكم (1856) كلهم من طريق خلف بن خليفة، عن حفص بن أخي أنس، عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب دعاء اللّٰه تعالى بأسمائه الحسنى","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (1495) and al-Nasā’ī (1300), and authenticated by Ibn Ḥibbān (893) and al-Ḥākim (1856).","chapter_en":"Calling upon Allah by His Most Beautiful Names","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Anas narrated: I was sitting with the Messenger of Allah ﷺ while a man was praying. He then supplicated: “O Allah, I ask You because all praise belongs to You. There is no deity worthy of worship except You, the Bestower of favors, the Originator of the heavens and the earth, O Possessor of Majesty and Honor, O Ever-Living, O Sustainer of all existence.” The Prophet ﷺ said: “He has called upon Allah by His Great Name, through which, when He is called upon, He answers, and when He is asked, He gives.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11036],"tks":"حسن: رواه أبو داود (1495)، والنسائي (1300)، وصححه ابن حبان (893)، والحاكم (1856)."},{"num":10902,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ، قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: فِي هَذه الْآيَتَيْنِ ﴿اللهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ﴾ [البقرة: ٢٥٥] وَ﴿أَلَمْ اللهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ﴾ [آل عِمْرَانَ: ٢] إِنَّ فِيهِمَا اسْمَ اللَّهِ الْأَعْظَمَ."],"takhrij":"حسن: رواه أحمد (27611) عن محمد بن بكر، أخبرنا عبيد الله بن أبي زياد، قال: حدثنا شهر بن حوشب، عن أسماء بنت يزيد فذكرته.","grade":"حسن","chapter_ar":"باب دعاء اللّٰه تعالى بأسمائه الحسنى","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (27611), Abū Dāwūd (1496), al-Tirmidhī (3478), and Ibn Mājah (3855).","chapter_en":"Calling upon Allah by His Most Beautiful Names","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Asmāʾ bint Yazīd said: I heard the Messenger of Allah ﷺ say: “In these two verses: ‘Allah—there is no deity worthy of worship except Him, the Ever-Living, the Sustainer of all existence,’ and, ‘Alif, Lām, Mīm. Allah—there is no deity worthy of worship except Him, the Ever-Living, the Sustainer of all existence,’ is the Greatest Name of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (27611)، وأبو داود (1496)، والترمذي (3478)، وابن ماجه (3855)."},{"num":10903,"demo":false,"sanad":"","matn":["عَنْ رَبِيعَةَ بْنِ عَامِرٍ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَلِظُّوا بِيَا ذَا الْجَلَالِ وَالْإِكْرَامِ."],"takhrij":"صحيح: رواه أحمد (1796) والنسائي في الكبرى (7669)، والحاكم (1836) كلهم من طرق عن عبد الله بن المبارك، عن يحيى بن حسان – هو الفلسطيني- ، عن ربيعة بن عامر فذكره.","grade":"صحيح","chapter_ar":"باب إكثار الداعي في دعائه من قوله: يا ذا الجلال والإكرام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (1796), al-Nasā’ī in al-Sunan al-Kubrā (7669), and al-Ḥākim (1836).","chapter_en":"Frequently Saying “O Possessor of Majesty and Honor” in Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":12,"content":{"translation":{"en":["Rabīʿah ibn ʿĀmir said: I heard the Messenger of Allah ﷺ say: “Persist in saying: ‘O Possessor of Majesty and Honor.’”"]},"buhuth":{"en":["The phrase “Persist in saying: ‘O Possessor of Majesty and Honor’” means to say it frequently and remain constant upon it. In Arabic, alazza bi-al-shayʾ means to adhere firmly and continuously to something."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13474],"tks":"صحيح: رواه أحمد (1796)، والنسائي في السنن الكبرى (7669)، والحاكم (1836)."},{"num":10904,"demo":false,"sanad":"","matn":["عَنْ مُعَاذِ بْنِ جَبَلٍ، قَالَ: سَمِعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلاً يَدْعُو يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ تَمَامَ النِّعْمَةِ. فَقَالَ أَىُّ شَيْءٍ تَمَامُ النِّعْمَةِ. قَالَ: دَعْوَةٌ دَعَوْتُ بِهَا أَرْجُو بِهَا الْخَيْرَ. قَالَ فَإِنَّ مِنْ تَمَامِ النِّعْمَةِ دُخُولَ الْجَنَّةِ، وَالْفَوْزَ مِنَ النَّارِ. وَسَمِعَ رَجُلاً وَهُوَ يَقُولُ: يَا ذَا الْجَلاَلِ وَالإِكْرَامِ فَقَالَ: قَدِ اسْتُجِيبَ لَكَ فَسَلْ. وَسَمِعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلاً وَهُوَ يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الصَّبْرَ. فَقَالَ سَأَلْتَ اللَّهَ الْبَلاَءَ فَسَلْهُ الْعَافِيَةَ."],"takhrij":"حسن: رواه الترمذي (3527)، وأحمد (22017، 22056) كلاهما من طريق سفيان الثوري، وإسماعيل بن إبراهيم بن علية، عن الجريري، عن أبى الورد، عن اللجلاج، عن معاذ بن جبل فذكره.","grade":"حسن","chapter_ar":"باب إكثار الداعي في دعائه من قوله: يا ذا الجلال والإكرام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3527) and Aḥmad (22017, 22056).","chapter_en":"Frequently Saying “O Possessor of Majesty and Honor” in Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":12,"content":{"translation":{"en":["Muʿādh ibn Jabal narrated: The Prophet ﷺ heard a man supplicating: “O Allah, I ask You for the completion of Your favor.” He asked: “What is the completion of the favor?” The man replied: “It is a supplication through which I hope for goodness.” He said: “Part of the completion of Allah’s favor is entering Paradise and being saved from the Fire.” He also heard a man saying: “O Possessor of Majesty and Honor.” He said: “Your supplication has been answered, so ask.” The Prophet ﷺ also heard a man saying: “O Allah, I ask You for patience.” He said: “You have asked Allah for affliction. Ask Him instead for well-being.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3527)، وأحمد (22017، 22056)."},{"num":10905,"demo":false,"sanad":"","matn":["عَنْ أَبِي بن كَعْبٍ فِي قِصَّةِ الخضر وَمُوسَى قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رَحْمَةُ اللَّهِ عَلَيْنَا وَعَلَى مُوسَى، لَوْلَا أَنَّهُ عَجَّلَ لَرَأَى الْعَجَبَ، وَلَكِنَّهُ أَخَذَتْهُ مِنْ صَاحِبِهِ ذَمَامَةٌ ﴿قَالَ إِنْ سَأَلْتُكَ عَنْ شَيْءٍ بَعْدَهَا فَلَا تُصَاحِبْنِي قَدْ بَلَغْتَ مِنْ لَدُنِّي عُذْرًا﴾ [سورة الْكَهْفِ: 76] وَلَوْ صَبَرَ لَرَأَى الْعَجَبَ قَالَ: وَكَانَ إِذَا ذَكَرَ أَحَدًا مِنَ الْأَنْبِيَاءِ بَدَأَ بِنَفْسِهِ رَحْمَةُ اللَّهِ عَلَيْنَا وَعَلَى أَخِي كَذَا رَحْمَةُ اللَّهِ عَلَيْنَا.","وفي لفظ عنه: قال: كان رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إذا دعا لأحد بدأ بنفسه، فذكر ذات يوم موسى فقال: رحمة الله علينا وعلى موسى، لو كان صبر لقص الله تعالى علينا من خيره، ولكن ﴿قَالَ إِنْ سَأَلْتُكَ عَنْ شَيْءٍ بَعْدَهَا فَلَا تُصَاحِبْنِي قَدْ بَلَغْتَ مِنْ لَدُنِّي عُذْرًا﴾ [سورة الكهف: 76]."],"takhrij":"صحيح: رواه مسلم في الفضائل (1380: 171-172) من طريق رقبة، عن أبي إسحاق، عن سعيد بن جبير، عن ابن عباس، عن أبي بن كعب فذكره باللفظ الأول في قصة الخضر وموسى.","grade":"صحيح","chapter_ar":"باب أن الداعي يبدأ بنفسه في الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: The first wording was narrated by Muslim (1380/171–172).","chapter_en":"The Supplicant Begins with Himself in Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Ubayy ibn Kaʿb narrated concerning the story of al-Khiḍr and Moses that the Messenger of Allah ﷺ said: “May Allah have mercy upon us and upon Moses. Had he not acted hastily, he would have witnessed astonishing things. However, embarrassment before his companion overtook him, and he said: ‘If I ask you about anything after this, then do not keep me as a companion. You have received from me a sufficient excuse.’ Had he remained patient, he would have witnessed astonishing things.” The narrator said: Whenever the Prophet ﷺ mentioned one of the prophets, he would begin with himself, saying: “May Allah have mercy upon us and upon my brother so-and-so. May Allah have mercy upon us.” Another wording states: The Messenger of Allah ﷺ would begin with himself whenever he supplicated for someone. One day, he mentioned Moses and said: “May Allah have mercy upon us and upon Moses. Had he remained patient, Allah, the Exalted, would have related more of his story to us. However, he said: ‘If I ask you about anything after this, then do not keep me as a companion. You have received from me a sufficient excuse.’”"]},"buhuth":{"en":["The second wording was narrated by Aḥmad (21126) and Abū Dāwūd (3984)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1380/171-172)."},{"num":10906,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَجُلاً، كَانَ يَدْعُو بِأُصْبُعَيْهِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَحِّدْ أَحِّدْ.","وفي لفظ: أَنَّ النَّبِيَّ صلى الله عليه وسلم أَبْصَرَ رَجُلًا يَدْعُو بِإِصْبَعَيْهِ جَمِيعًا فَنَهَاهُ وَقَالَ: بِإِحْدَاهُمَا بِالْيُمْنَى."],"takhrij":"حسن: رواه الترمذي (3557)، والنسائي (1272)، وأحمد (10739)، والحاكم (1965) كلهم من حديث صفوان بن عيسى قال: حدثنا محمد بن عجلان، عن القعقاع بن حكيم، عن أبي صالح، عن أبي هريرة فذكره باللفظ الأول.","grade":"حسن","chapter_ar":"باب الإشارة بالسبابة عند الشهادة في الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3557), al-Nasā’ī (1272), Aḥmad (10739), and al-Ḥākim (1965).","chapter_en":"Pointing with the Index Finger When Affirming Allah’s Oneness during Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Abū Hurayrah narrated: A man was supplicating while pointing with both of his fingers. The Messenger of Allah ﷺ said: “One, one.” Another wording states: The Prophet ﷺ saw a man supplicating with both index fingers, so he prohibited him and said: “Use only one of them—the right one.”"]},"buhuth":{"en":["The expression “One, one” originally means: “Affirm His oneness, affirm His oneness.” It indicates that one should point with a single finger because the One being called upon is One without partner.","The Companion whom the Prophet ﷺ saw was Saʿd ibn Abī Waqqāṣ, as stated in the following hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3557)، والنسائي (1272)، وأحمد (10739)، والحاكم (1965)."},{"num":10907,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ، قَالَ: مَرَّ عَلَىَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا أَدْعُو بِأُصْبُعَىَّ فَقَالَ: أَحِّدْ، أَحِّدْ. وَأَشَارَ بِالسَّبَّابَةِ."],"takhrij":"صحيح: رواه أبو داود (1499)، والنسائي (1273)، وصحّحه الحاكم (1966) كلهم من طريق أبي معاوية، حدثنا الأعمش، عن أبي صالح، عن سعد بن أبي وقاص فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الإشارة بالسبابة عند الشهادة في الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1499) and al-Nasā’ī (1273), and authenticated by al-Ḥākim (1966).","chapter_en":"Pointing with the Index Finger When Affirming Allah’s Oneness during Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في آداب الدعاء","group_en":"Collection of Narrations Concerning the Etiquettes of Supplication","part_no":54,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ narrated: The Prophet ﷺ passed by me while I was supplicating with my finger and said: “One, one.” He pointed with his index finger."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2159],"tks":"صحيح: رواه أبو داود (1499)، والنسائي (1273)، وصححه الحاكم (1966)."},{"num":10908,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا دَعَا أَحَدُكُمْ فَلْيَعْزِمِ الْمَسْأَلَةَ، وَلاَ يَقُولَنَّ: اللَّهُمَّ إِنْ شِئْتَ فَأَعْطِنِي. فَإِنَّهُ لاَ مُسْتَكْرِهَ لَهُ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6338)، ومسلم في الذكر (2678)، كلاهما من طريق إسماعيل بن علية، أخبرنا عبد العزيز بن صهيب، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب العزم في الدعاء، ولا يقولن: إن شئت فأعطني","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6338) and Muslim (2678).","chapter_en":"Resoluteness in Supplication and Not Saying: “Give Me If You Wish”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “When one of you supplicates, let him ask with determination, and let him not say: ‘O Allah, give me if You wish,’ for no one can compel Him.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6338)، ومسلم (2678)."},{"num":10909,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يَقُولَنَّ أَحَدُكُمُ اللَّهُمَّ اغْفِرْ لِي، اللَّهُمَّ ارْحَمْنِي، إِنْ شِئْتَ. لِيَعْزِمِ الْمَسْأَلَةَ، فَإِنَّهُ لاَ مُكْرِهَ لَهُ.","وفي رواية: وليعظّم الرغبة، فإن الله لا يتعاظمه شيء أعطاه."],"takhrij":"متفق عليه: رواه مالك في كتاب القرآن (28) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.ورواه البخاري في الدعوات (6339) من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب العزم في الدعاء، ولا يقولن: إن شئت فأعطني","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (28), al-Bukhārī (6339), and Muslim (2679/8).","chapter_en":"Resoluteness in Supplication and Not Saying: “Give Me If You Wish”","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Let none of you say when supplicating: ‘O Allah, forgive me if You wish. O Allah, have mercy upon me if You wish.’ Rather, let him ask with determination, for no one can compel Him.” Another narration states: “Let him make his desire great, for nothing that Allah gives is too great for Him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (28)، والبخاري (6339)، ومسلم (2679/8)."},{"num":10910,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْقُلُوبُ أَوْعِيَةٌ وَبَعْضُهَا أَوْعَى مِنْ بَعْضٍ، فَإِذَا سَأَلْتُمُ اللَّهَ عَزَّ وَجَلَّ، أَيُّهَا النَّاسُ، فَاسْأَلُوهُ وَأَنْتُمْ مُوقِنُونَ بِالْإِجَابَةِ، فَإِنَّ اللَّهَ لَا يَسْتَجِيبُ لِعَبْدٍ دَعَاهُ عَنْ ظَهْرِ قَلْبٍ غَافِلٍ."],"takhrij":"حسن: رواه أحمد (6655) عن حسن، حدثنا ابن لهيعة، حدثنا بكر بن عمرو، عن أبي عبد الرحمن الحبلي، عن عبد الله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب لا يقبل اللّٰه دعاء عبد غافل القلب","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (6655).","chapter_en":"Allah Does Not Answer the Supplication of a Servant Whose Heart Is Heedless","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated that the Messenger of Allah ﷺ said: “Hearts are vessels, and some are more capable of retaining than others. Therefore, O people, when you ask Allah, Mighty and Majestic, ask Him while being certain of the answer, for Allah does not answer a servant who calls upon Him from a heedless heart.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (6655)."},{"num":10911,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ آمَنَ بِاللَّهِ وَبِرَسُولِهِ وَأَقَامَ الصَّلاَةَ، وَصَامَ رَمَضَانَ، كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُدْخِلَهُ الْجَنَّةَ، جَاهَدَ فِي سَبِيلِ اللَّهِ، أَوْ جَلَسَ فِي أَرْضِهِ الَّتِي وُلِدَ فِيهَا. فَقَالُوا يَا رَسُولَ اللَّهِ أَفَلاَ نُبَشِّرُ النَّاسَ. قَالَ: إِنَّ فِي الْجَنَّةِ مِائَةَ دَرَجَةٍ أَعَدَّهَا اللَّهُ لِلْمُجَاهِدِينَ فِي سَبِيلِ اللَّهِ، مَا بَيْنَ الدَّرَجَتَيْنِ كَمَا بَيْنَ السَّمَاءِ وَالأَرْضِ، فَإِذَا سَأَلْتُمُ اللَّهَ فَاسْأَلُوهُ الْفِرْدَوْسَ، فَإِنَّهُ أَوْسَطُ الْجَنَّةِ، وَأَعْلَى الْجَنَّةِ، أُرَاهُ فَوْقَهُ عَرْشُ الرَّحْمَنِ، وَمِنْهُ تَفَجَّرُ أَنْهَارُ الْجَنَّةِ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (2790) عن يحيى بن صالح، حدثنا فليح، عن هلال بن علي، عن عطاء بن يسار، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب على المسلم أن يسأل اللّٰه في دعائه الفردوس الأعلى","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2790).","chapter_en":"A Muslim Should Ask Allah for the Highest Firdaws in His Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever believes in Allah and His Messenger, establishes the prayer, and fasts Ramadan, Allah has made it a right upon Himself to admit him into Paradise, whether he strives in the path of Allah or remains in the land in which he was born.” They asked: “O Messenger of Allah, should we not give the people these glad tidings?” He replied: “Indeed, Paradise contains one hundred ranks which Allah has prepared for those who strive in His path. The distance between every two ranks is like the distance between the heaven and the earth. Therefore, when you ask Allah, ask Him for al-Firdaws, for it is the middle and highest part of Paradise. Above it, as I understand, is the Throne of the Most Merciful, and from it the rivers of Paradise spring forth.”"]},"buhuth":{"en":["The phrase “or remains in the land in which he was born” refers to a person who remains at home while sincerely intending to strive, but is prevented by a valid religious excuse. He will not be deprived of the reward of striving, although those who actually strive possess distinct ranks in Paradise."]}},"tuhfa":{},"full":1,"dr":1,"rep":[469,7743,12819],"tks":"صحيح: رواه البخاري (2790)."},{"num":10912,"demo":false,"sanad":"","matn":["عَنْ أَوْسَطَ بْنِ إِسْمَاعِيلَ الْبَجَلِيِّ، أَنَّهُ سَمِعَ أَبَا بَكْرٍ، حِينَ قُبِضَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَقَامِي هَذَا عَامَ الأَوَّلِ، ثُمَّ بَكَى أَبُو بَكْرٍ ثُمَّ قَالَ: عَلَيْكُمْ بِالصِّدْقِ؛ فَإِنَّهُ مَعَ الْبِرِّ وَهُمَا فِي الْجَنَّةِ، وَإِيَّاكُمْ وَالْكَذِبَ؛ فَإِنَّهُ مَعَ الْفُجُورِ وَهُمَا فِي النَّارِ، وَسَلُوا اللَّهَ الْمُعَافَاةَ فَإِنَّهُ لَمْ يُؤْتَ أَحَدٌ بَعْدَ الْيَقِينِ خَيْرًا مِنَ الْمُعَافَاةِ وَلاَ."],"takhrij":"صحيح: رواه ابن ماجه (3849)، وأحمد (5، 17)، والبخاري في الأدب المفرد (724)، والنسائي في عمل اليوم والليلة (879-883) وصحّحه ابن حبان (952)، والحاكم (1/529) كلهم من طرق عن أوسط البجلي فذكره.","grade":"صحيح","chapter_ar":"باب الترغيب في سؤال العافية","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (3849), Aḥmad (5, 17), and al-Bukhārī in al-Adab al-Mufrad (724).","chapter_en":"Encouragement to Ask Allah for Well-Being","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Awsaṭ ibn Ismāʿīl ibn Awsaṭ al-Bajalī narrated that he heard Abū Bakr, after the Prophet ﷺ had passed away, say: “The Messenger of Allah ﷺ stood in this very place of mine last year.” Abū Bakr then wept and said: “Adhere to truthfulness, for truthfulness accompanies righteousness, and both are in Paradise. Beware of lying, for lying accompanies wickedness, and both are in the Fire. Ask Allah for well-being, for after certainty, no one has been given anything better than well-being.” This forms part of the hadith."]},"buhuth":{"en":["Aḥmad also narrated it (6) through Rifāʿah ibn Rāfiʿ, who said:","I heard Abū Bakr al-Ṣiddīq say from the pulpit of the Messenger of Allah ﷺ:","“I heard the Messenger of Allah ﷺ say…”","Abū Bakr wept when he mentioned the Messenger of Allah ﷺ. When he regained his composure, he said:","“I heard the Messenger of Allah ﷺ say during the heat of last year:","‘Ask Allah for pardon, well-being, and certainty in this world and the Hereafter.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (3849)، وأحمد (5، 17)، والبخاري في الأدب المفرد (724)."},{"num":10913,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِعَمِّهِ العباس: يَا عَمِّ أَكْثِرِ الدُّعَاءَ بِالْعَافِيَةِ."],"takhrij":"حسن: رواه الطبراني في الكبير (11908)، والحاكم (1939) كلاهما من طريق هلال بن خباب، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب الترغيب في سؤال العافية","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (11/330–331) and al-Ḥākim (1/529).","chapter_en":"Encouragement to Ask Allah for Well-Being","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Prophet ﷺ said to his uncle al-ʿAbbās: “O uncle, frequently supplicate for well-being.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (11853)، والحاكم (1939)."},{"num":10914,"demo":false,"sanad":"","matn":["عَنْ أنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِقَوْمٍ مُبْتَلِينَ، فَقَالَ: أَمَا كَانَ هَؤُلاءِ يَسْأَلُونَ اللَّهَ الْعَافِيَةَ؟"],"takhrij":"صحيح: رواه البزار (6643) عن العباس بن جعفر البغدادي، حدثنا يزيد بن مهران، حدثنا أبو بكر بن عياش، عن حميد، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب الترغيب في سؤال العافية","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzār (6643).","chapter_en":"Encouragement to Ask Allah for Well-Being","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Anas narrated: The Prophet ﷺ passed by some people who were afflicted and said: “Why did these people not ask Allah for well-being?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البزار (6643)."},{"num":10915,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن مُغَفَّلٍ سَمِعَ ابْنَهُ، يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْقَصْرَ الأَبْيَضَ عَنْ يَمِينِ الْجَنَّةِ، إِذَا دَخَلْتُهَا. فَقَالَ أَىْ بُنَىَّ سَلِ اللَّهَ الْجَنَّةَ، وَتَعَوَّذْ بِهِ مِنَ النَّارِ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّهُ سَيَكُونُ فِي هَذِهِ الأُمَّةِ قَوْمٌ يَعْتَدُونَ فِي الطُّهُورِ وَالدُّعَاءِ."],"takhrij":"صحيح: رواه أبو داود (96)، وابن ماجه (3864)، وصحّحه ابن حبان (6764)، والحاكم (1/162، 540) كلهم من حديث حماد بن سلمة، ثنا الجريري، عن أبي نعامة، عن عبد الله بن مغفل فذكره إلا أن ابن ماجه لم يذكر \"الطهور\".وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب كراهية الاعتداء في الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (96) and Ibn Mājah (3864), and authenticated by Ibn Ḥibbān (6764) and al-Ḥākim (1/162, 540).","chapter_en":"The Dislike of Transgressing in Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullāh ibn Mughaffal heard his son saying: “O Allah, I ask You for the white palace on the right side of Paradise when I enter it.” He said: “My son, ask Allah for Paradise and seek His protection from the Fire, for I heard the Messenger of Allah ﷺ say: ‘There will be people within this nation who transgress in purification and supplication.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (96)، وابن ماجه (3864)، وصححه ابن حبان (6764)، والحاكم (1/162، 540)."},{"num":10916,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي صَلاَةٍ، وَقُمْنَا مَعَهُ، فَقَالَ أَعْرَابِيٌّ وَهْوَ فِي الصَّلاَةِ: اللَّهُمَّ ارْحَمْنِي وَمُحَمَّدًا، وَلاَ تَرْحَمْ مَعَنَا أَحَدًا فَلَمَّا سَلَّمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِلأَعْرَابِيِّ: لَقَدْ حَجَّرْتَ وَاسِعًا يُرِيدُ رَحْمَةَ اللَّهِ."],"takhrij":"صحيح: رواه البخاري في الأدب (6010) عن أبي اليمان، أخبرنا شعيب، عن الزهري، عن أبي سلمة بن عبد الرحمن، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب كراهة أن يحجر الداعي في دعائه واسع رحمة ربه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6010).","chapter_en":"The Dislike of Restricting the Vast Mercy of One’s Lord in Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah narrated: The Messenger of Allah ﷺ stood in prayer, and we stood with him. During the prayer, a Bedouin said: “O Allah, have mercy upon me and Muḥammad, and do not have mercy upon anyone else along with us.” When the Prophet ﷺ completed the prayer, he said to the Bedouin: “You have restricted something vast.” He meant the mercy of Allah."]}},"tuhfa":{},"full":1,"rep":[2593,13913],"tks":"صحيح: رواه البخاري (6010)."},{"num":10917,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّ رَجُلًا جَاءَ فَقَالَ: اللهُمَّ اغْفِرْ لِي وَلِمُحَمَّدٍ، وَلَا تُشْرِكْ فِي رَحْمَتِكَ إِيَّانَا أَحَدًا فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ قَائِلُهَا؟ فَقَالَ الرَّجُلُ: أَنَا فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَقَدْ حَجَبْتَهُنَّ عَنْ نَاسٍ كَثِيرٍ."],"takhrij":"صحيح: رواه أحمد (6590) –واللفظ له- والبخاري في الأدب المفرد (626)، وصحّحه ابن حبان (986) كلهم من طريق حماد بن سلمة، عن عطاء بن السائب، عن أبيه، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب كراهة أن يحجر الداعي في دعائه واسع رحمة ربه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (6590), whose wording is cited here, al-Bukhārī in al-Adab al-Mufrad (626), and authenticated by Ibn Ḥibbān (986).","chapter_en":"The Dislike of Restricting the Vast Mercy of One’s Lord in Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated: A man came and said: “O Allah, forgive me and Muḥammad, and do not include anyone else with us in Your mercy.” The Prophet ﷺ asked: “Who said this?” The man replied: “I did.” The Prophet ﷺ said: “You have withheld it from many people.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (6590) - واللفظ له -، والبخاري في الأدب المفرد (626)، وصححه ابن حبان (986)."},{"num":10918,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: حَدِّثِ النَّاسَ، كُلَّ جُمُعَةٍ مَرَّةً، فَإِنْ أَبَيْتَ فَمَرَّتَيْنِ، فَإِنَّ أَكْثَرْتَ فَثَلاَثَ مِرَارٍ، وَلاَ تُمِلَّ النَّاسَ هَذَا الْقُرْآنَ، وَلاَ أُلْفِيَنَّكَ تَأْتِي الْقَوْمَ وَهُمْ فِي حَدِيثٍ مِنْ حَدِيثِهِمْ، فَتَقُصُّ عَلَيْهِمْ، فَتَقْطَعُ عَلَيْهِمْ حَدِيثَهُمْ، فَتُمِلُّهُمْ، وَلَكِنْ أَنْصِتْ، فَإِذَا أَمَرُوكَ فَحَدِّثْهُمْ وَهُمْ يَشْتَهُونَهُ، فَانْظُرِ السَّجْعَ مِنَ الدُّعَاءِ فَاجْتَنِبْهُ، فَإِنِّي عَهِدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابَهُ لاَ يَفْعَلُونَ إِلاَّ ذَلِكَ. يَعْنِي لاَ يَفْعَلُونَ إِلاَّ ذَلِكَ الاِجْتِنَابَ."],"takhrij":"صحيح: رواه البخاري في الدعوات (6337) عن يحيى بن محمد بن السكن، حدثنا حبان بن هلال أبو حبيب، حدثنا هارون المقرئ، حدثنا الزبير بن الخريت، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ذم تكلف السجع في الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6337).","chapter_en":"Condemnation of Affecting Rhymed Prose in Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās said: “Speak to the people once every Friday. Should you refuse to limit yourself to that, then twice; and should you insist upon more, then three times. Do not make the people weary of this Qur’an. I must not find you approaching people while they are engaged in a conversation of their own and beginning to preach to them, thereby interrupting their conversation and making them weary. Rather, remain silent. When they ask you to speak, then speak to them while they are eager to listen.” He then said: “Beware of affected rhyming in supplication and avoid it, for I knew the Messenger of Allah ﷺ and his Companions, and they did nothing but avoid it.” That is, they consistently avoided affected rhyming in supplication."]},"buhuth":{"en":["The scholars stated that the blameworthy kind of rhymed prose in supplication is that which is deliberately contrived. It removes humility, submissiveness, and sincerity, and distracts the supplicant from earnest pleading, expressing need, and maintaining a focused heart.","As for rhyming that occurs naturally, without affectation or deliberate mental effort, because of eloquence or something similar, there is no harm in it.","See: al-Nawawī’s commentary on Ṣaḥīḥ Muslim (17/41)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (6337)."},{"num":10919,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُسْتَجَابُ لأَحَدِكُمْ مَا لَمْ يَعْجَلْ يَقُولُ دَعَوْتُ فَلَمْ يُسْتَجَبْ لِي."],"takhrij":"متفق عليه: رواه مالك في القرآن (29) عن ابن شهاب، عن أبي عبيد مولى ابن أزهر، عن أبي هريرة فذكره.ورواه البخاري في الدعوات (6340)، ومسلم في الذكر والدعاء (2735: 90) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب يستجاب دعاء المسلم ما لم يستعجل بالإجابة أو يدع بإثم أو قطيعة رحم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (29), al-Bukhārī (6340), and Muslim (2735/90).","chapter_en":"A Muslim’s Supplication Is Answered So Long as He Does Not Become Impatient, Supplicate for Sin, or Sever Family Ties","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The supplication of one of you will continue to be answered so long as he does not become impatient and say: ‘I supplicated, but my supplication was not answered.’”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ، أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ، فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي لَعَلَّهُمْ يَرْشُدُونَ﴾ [سورة البقرة: ١٨٦]."],"en":["Allah, the Exalted, said:","“When My servants ask you concerning Me, then indeed I am near. I answer the supplication of the supplicant when he calls upon Me. So let them respond to Me and believe in Me, so that they may be rightly guided.”","[Sūrat al-Baqarah 2:186]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مالك (29)، والبخاري (6340)، ومسلم (2735: 90)."},{"num":10920,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ:  لَا يَزَالُ يُسْتَجَابُ لِلْعَبْدِ مَا لَمْ يَدْعُ بِإِثْمٍ، أَوْ قَطِيعَةِ رَحِمٍ، مَا لَمْ يَسْتَعْجِلْ قِيلَ: يَا رَسُولَ اللَّهِ مَا الِاسْتِعْجَالُ؟ قَالَ: يَقُولُ: قَدْ دَعَوْتُ وَقَدْ دَعَوْتُ، فَلَمْ أَرَ يَسْتَجِيبُ لِي فَيَسْتَحْسِرُ عِنْدَ ذَلِكَ، وَيَدَعُ الدُّعَاءَ."],"takhrij":"صحيح: رواه مسلم في الذكر والدعاء (2735: 92) عن أبي الطاهر، أخبرنا ابن وهب، أخبرني معاوية (وهو ابن صالح)، عن ربيعة بن يزيد، عن أبي إدريس الخولاني، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب يستجاب دعاء المسلم ما لم يستعجل بالإجابة أو يدع بإثم أو قطيعة رحم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2735/92).","chapter_en":"A Muslim’s Supplication Is Answered So Long as He Does Not Become Impatient, Supplicate for Sin, or Sever Family Ties","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “The servant’s supplication will continue to be answered so long as he does not supplicate for a sin or the severing of family ties, and so long as he does not become impatient.” It was asked: “O Messenger of Allah, what does becoming impatient mean?” He replied: “He says: ‘I have supplicated and supplicated, but I have not seen my supplication answered.’ He then becomes weary and abandons supplication.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2735: 92)."},{"num":10921,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنْ رَجُلٍ يَدْعُو اللَّهَ بِدُعَاءٍ إِلاَّ اسْتُجِيبَ لَهُ، فَإِمَّا أَنْ يُعَجَّلَ لَهُ فِي الدُّنْيَا، وَإِمَّا أَنْ يُدَّخَرَ لَهُ فِي الآخِرَةِ، وَإِمَّا أَنْ يُكَفَّرَ عَنْهُ مِنْ ذُنُوبِهِ بِقَدْرِ مَا دَعَا مَا لَمْ يَدْعُ بِإِثْمٍ أَوْ قَطِيعَةِ رَحِمٍ أَوْ يَسْتَعْجِلُ. قَالُوا: يَا رَسُولَ اللَّهِ وَكَيْفَ يَسْتَعْجِلُ؟ قَالَ: يَقُولُ دَعَوْتُ رَبِّي فَمَا اسْتَجَابَ لِي."],"takhrij":"حسن: رواه الترمذي (3604.04) عن يحيى بن موسى قال: أخبرنا أبو معاوية، أخبرنا الليث هو ابن أبي سليم، عن زياد، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب يستجاب دعاء المسلم ما لم يستعجل بالإجابة أو يدع بإثم أو قطيعة رحم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3406/3), al-Bukhārī in al-Adab al-Mufrad (711), Aḥmad (9785), and al-Ḥākim (1/497).","chapter_en":"A Muslim’s Supplication Is Answered So Long as He Does Not Become Impatient, Supplicate for Sin, or Sever Family Ties","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “No man supplicates to Allah with a supplication except that it is answered for him. Either it is granted to him quickly in this world, stored for him in the Hereafter, or sins equal to the measure of his supplication are expiated from him, so long as he does not supplicate for a sin, the severing of family ties, or become impatient.” They asked: “O Messenger of Allah, how does he become impatient?” He replied: “He says: ‘I supplicated to my Lord, but He did not answer me.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3604.04)، والبخاري في الأدب المفرد (711)، وأحمد (9785)، والحاكم (1/497)."},{"num":10922,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا مِنْ مُسْلِمٍ يَدْعُو بِدَعْوَةٍ لَيْسَ فِيهَا إِثْمٌ، وَلَا قَطِيعَةُ رَحِمٍ، إِلَّا أَعْطَاهُ اللهُ بِهَا إِحْدَى ثَلَاثٍ: إِمَّا أَنْ تُعَجَّلَ لَهُ دَعْوَتُهُ، وَإِمَّا أَنْ يَدَّخِرَهَا لَهُ فِي الْآخِرَةِ، وَإِمَّا أَنْ يَصْرِفَ عَنْهُ مِنَ السُّوءِ مِثْلَهَا قَالُوا: إِذًا نُكْثِرُ، قَالَ: اللَّهُ أَكْثَرُ."],"takhrij":"حسن: رواه أحمد (11133)، والبخاري في الأدب المفرد (710)، والحاكم (1816) كلهم من طرق عن علي بن علي الرفاعي قال: سمعت أبا المتوكل الناجي قال: قال أبو سعيد الخدري، عن النبي صلى الله عليه وسلم فذكره.","grade":"حسن","chapter_ar":"باب يستجاب دعاء المسلم ما لم يستعجل بالإجابة أو يدع بإثم أو قطيعة رحم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (11133), al-Bukhārī in al-Adab al-Mufrad (710), and al-Ḥākim (1816).","chapter_en":"A Muslim’s Supplication Is Answered So Long as He Does Not Become Impatient, Supplicate for Sin, or Sever Family Ties","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Abū Saʿīd narrated that the Prophet ﷺ said: “No Muslim offers a supplication that contains neither sin nor the severing of family ties except that Allah grants him one of three things through it: either He hastens the fulfillment of his supplication, stores it for him in the Hereafter, or averts from him an equivalent amount of evil.” They said: “Then we shall supplicate abundantly.” He replied: “Allah has even more to give.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (11133)، والبخاري في الأدب المفرد (710)، والحاكم (1816)."},{"num":10923,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا مِنْ أَحَدٍ يَدْعُو بِدُعَاءٍ إِلاَّ آتَاهُ اللَّهُ مَا سَأَلَ أَوْ كَفَّ عَنْهُ مِنَ السُّوءِ مِثْلَهُ مَا لَمْ يَدْعُ بِإِثْمٍ أَوْ قَطِيعَةِ رَحِمٍ."],"takhrij":"حسن: رواه الترمذي (3381)، وأحمد (14879) كلاهما عن قتيبة بن سعيد، قال: حدثنا ابن لهيعة، عن أبي الزبير، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب يستجاب دعاء المسلم ما لم يستعجل بالإجابة أو يدع بإثم أو قطيعة رحم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3381) and Aḥmad (14879).","chapter_en":"A Muslim’s Supplication Is Answered So Long as He Does Not Become Impatient, Supplicate for Sin, or Sever Family Ties","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Jābir said: I heard the Messenger of Allah ﷺ say: “No one supplicates with a supplication except that Allah grants him what he asked for or averts from him an equivalent amount of evil, so long as he does not supplicate for a sin or the severing of family ties.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3381)، وأحمد (14879)."},{"num":10924,"demo":false,"sanad":"","matn":["عن عُبَادَةَ بْنِ الصَّامِتِ حَدَّثَهُمْ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا عَلَى الأَرْضِ مُسْلِمٌ يَدْعُو اللَّهَ بِدَعْوَةٍ إِلاَّ آتَاهُ اللَّهُ إِيَّاهَا أَوْ صَرَفَ عَنْهُ مِنَ السُّوءِ مِثْلَهَا مَا لَمْ يَدْعُ بِمَأْثَمٍ أَوْ قَطِيعَةِ رَحِمٍ. فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: إِذًا نُكْثِرَ. قَالَ اللَّهُ أَكْثَرُ."],"takhrij":"حسن: رواه الترمذي (3573)، وعبد الله بن أحمد في زياداته على المسند (22785) كلاهما من طريق محمد بن يوسف عن ابن ثوبان عن أبيه عن مكحول عن جبير بن نفير أن عبادة بن الصامت حدثهم فذكره.","grade":"حسن","chapter_ar":"باب يستجاب دعاء المسلم ما لم يستعجل بالإجابة أو يدع بإثم أو قطيعة رحم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3573) and ʿAbdullāh ibn Aḥmad in his additions to al-Musnad (22785).","chapter_en":"A Muslim’s Supplication Is Answered So Long as He Does Not Become Impatient, Supplicate for Sin, or Sever Family Ties","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["ʿUbādah ibn al-Ṣāmit narrated that the Messenger of Allah ﷺ said: “There is no Muslim upon the earth who supplicates to Allah with a supplication except that Allah grants it to him or averts from him an equivalent amount of evil, so long as he does not supplicate for a sin or the severing of family ties.” A man from among the people said: “Then we shall supplicate abundantly.” He replied: “Allah has even more to give.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3573)، وعبد الله بن أحمد في زياداته على المسند (22785)."},{"num":10925,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ سَرَّهُ أَنْ يَسْتَجِيبَ اللَّهُ لَهُ عِنْدَ الشَّدَائِدِ وَالْكُرَبِ فَلْيُكْثِرِ الدُّعَاءَ فِي الرَّخَاءِ."],"takhrij":"حسن: رواه الترمذي (3382)، وأبو يعلى (6396)، والطبراني في الدعاء (45) كلهم من طريق عبيد بن واقد، ثنا سعيد بن عطية الليثي، عن شهر بن حوشب، عن أبي هريرة قال:فذكره.","grade":"حسن","chapter_ar":"باب الدعاء عند الرخاء من أسباب إجابة الدعاء في الشدائد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3382), Abū Yaʿlā (6396), and al-Ṭabarānī in al-Duʿāʾ (45).","chapter_en":"Supplicating during Ease Is among the Causes for Supplication Being Answered during Hardship","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever would be pleased for Allah to answer him during hardship and distress should supplicate abundantly during times of ease.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3382)، وأبو يعلى (6396)، والطبراني في الدعاء (45)."},{"num":10926,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَنْزِلُ رَبُّنَا تَبَارَكَ وَتَعَالَى كُلَّ لَيْلَةٍ إِلَى السَّمَاءِ الدُّنْيَا حِينَ يَبْقَى ثُلُثُ اللَّيْلِ الآخِرُ، يَقُولُ مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ، مَنْ يَسْأَلُنِي فَأُعْطِيَهُ، مَنْ يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ."],"takhrij":"متفق عليه: رواه مالك في القرآن (30) عن ابن شهاب، عن أبي عبدالله الأغرّ، وأبي سلمة، عن أبي هريرة، فذكره.ورواه البخاريّ في التهجد (1145) ومسلم في صلاة المسافرين (758) كلاهما من طريق مالك، به، مثله.","grade":"متفق عليه","chapter_ar":"باب الأوقات والأحوال التي ترجى فيها الإجابة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (30), al-Bukhārī (1145), and Muslim (758).","chapter_en":"Times and Circumstances in Which an Answer Is Hoped For","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Allah, Blessed and Exalted, descends every night to the lowest heaven when the final third of the night remains and says: ‘Who is calling upon Me so that I may answer him? Who is asking Me so that I may give him? Who is seeking My forgiveness so that I may forgive him?’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[299,2704,10758,13399],"tks":"متفق عليه: رواه مالك (30)، والبخاري (1145)، ومسلم (758)."},{"num":10927,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  إِنَّ فِي اللَّيْلِ لَسَاعَةً لَا يُوَافِقُهَا رَجُلٌ مُسْلِمٌ يَسْأَلُ اللَّهَ خَيْرًا مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ إِلَّا أَعْطَاهُ إِيَّاهُ، وَذَلِكَ كُلَّ لَيْلَةٍ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (757: 166) عن عثمان بن أبي شيبة، ثنا جرير، عن الأعمش، عن أبي سفيان، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب الأوقات والأحوال التي ترجى فيها الإجابة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (757/166).","chapter_en":"Times and Circumstances in Which an Answer Is Hoped For","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Jābir said: I heard the Prophet ﷺ say: “There is an hour during every night in which no Muslim man asks Allah for any good relating to this world or the Hereafter except that He grants it to him. This occurs every night.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2708,10761],"tks":"صحيح: رواه مسلم (757: 166)."},{"num":10928,"demo":false,"sanad":"","matn":["عَنْ مُعَاذِ بْنِ جَبَلٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا مِنْ مُسْلِمٍ يَبِيتُ عَلَى ذِكْرٍ طَاهِرًا فَيَتَعَارُّ مِنَ اللَّيْلِ فَيَسْأَلُ اللَّهَ خَيْرًا مِنَ الدُّنْيَا وَالآخِرَةِ إِلاَّ أَعْطَاهُ."],"takhrij":"حسن: رواه النسائي في عمل اليوم والليلة (806) عن إبراهيم بن يعقوب قال: حدثنا عفان، قال: حدثنا حماد قال: كنت أنا وعاصم وثابت فحدث عاصم عن شهر، عن أبي ظبية، عن معاذ بن جبل فذكره.","grade":"حسن","chapter_ar":"باب الأوقات والأحوال التي ترجى فيها الإجابة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (806), Abū Dāwūd (5042), Ibn Mājah (3881), and Aḥmad (22048).","chapter_en":"Times and Circumstances in Which an Answer Is Hoped For","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Muʿādh ibn Jabal narrated that the Messenger of Allah ﷺ said: “No Muslim goes to sleep in a state of purity while remembering Allah, then awakens during the night and asks Allah for some good of this world or the Hereafter, except that Allah grants it to him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في عمل اليوم والليلة (806)، وأبو داود (5042)، وابن ماجه (3881)، وأحمد (22048)."},{"num":10929,"demo":false,"sanad":"","matn":["عن عَمْرِو بْنِ عَبَسَةَ يَقُولُ: قُلْتُ: يَا رَسُولَ اللَّهِ! هَلْ مِنْ سَاعَةٍ أَقْرَبُ مِنَ الأُخْرَى؟ أَوْ هَلْ مِنْ سَاعَةٍ يُبْتَغَى ذِكْرُهَا؟ قَالَ: نَعَمْ، إِنَّ أَقْرَبَ مَا يَكُونُ الرَّبُّ عَزَّ وَجَلَّ مِنَ الْعَبْدِ جَوْفُ اللَّيْلِ الآخِرِ، فَإِنِ اسْتَطَعْتَ أَنْ تَكُونَ مِمَّنْ يَذْكُرُ اللَّهَ عَزَّ وَجَلَّ فِي تِلْكَ السَّاعَةِ فَكُنْ، فَإِنَّ الصَّلاَةَ مَحْضُورَةٌ مَشْهُودَةٌ إِلَى طُلُوعِ الشَّمْسِ."],"takhrij":"صحيح: رواه النسائي (572) عن عمرو بن منصور، أخبرنا آدم بن أبي إياس، حدثنا الليث بن سعد، حدثنا معاوية بن صالح، قال: أخبرني أبو يحيى سُليم بن عامر وضمرة بن حبيب وأبو طلحة نعيم بن زياد قالوا: سمعنا أبا أمامة الباهلي يقول: سمعت عمرو بن عَبَسَة يقول: فذكره.","grade":"صحيح","chapter_ar":"باب الأوقات والأحوال التي ترجى فيها الإجابة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (572).","chapter_en":"Times and Circumstances in Which an Answer Is Hoped For","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["ʿAmr ibn ʿAbasah said: I asked: “O Messenger of Allah, is there a time in which Allah is nearer than at other times, or a time in which His remembrance should especially be sought?” He replied: “Yes. The time in which the Lord, Mighty and Majestic, is nearest to the servant is during the depth of the final part of the night. Therefore, if you are able to be among those who remember Allah, Mighty and Majestic, during that hour, then do so, for the prayer at that time is attended and witnessed until sunrise.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2706],"tks":"صحيح: رواه النسائي (572)."},{"num":10930,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إن الدُّعَاءُ لاَ يُرد بَيْنَ الأَذَانِ وَالإِقَامَةِ فادعوا."],"takhrij":"حسن: رواه أبو داود (521) والترمذي (212، 3594) والنسائي في اليوم والليلة (68،69،70)، وأحمد (12584، 13357)، وصحّحه ابن خزيمة (425-427)، وابن حبان (1696) كلهم من طرق عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب الأوقات والأحوال التي ترجى فيها الإجابة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (521), al-Tirmidhī (212, 3594), and al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (68, 69, 70).","chapter_en":"Times and Circumstances in Which an Answer Is Hoped For","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “Supplication is not rejected between the call to prayer and the commencement of the prayer, so supplicate.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10762],"tks":"حسن: رواه أبو داود (521)، والترمذي (212، 3594)، والنسائي في عمل اليوم والليلة (68، 69، 70)."},{"num":10931,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ:  كَشَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ السِّتَارَةَ - وَالنَّاسُ صُفُوفٌ خَلْفَ أَبِي بَكْرٍ - فَقَالَ: أَيُّهَا النَّاسُ إِنَّهُ لَمْ يَبْقَ مِنْ مُبَشِّرَاتِ النُّبُوَّةِ إِلَّا الرُّؤْيَا الصَّالِحَةُ يَرَاهَا الْمُسْلِمُ، أَوْ تُرَى لَهُ. أَلَا وَإِنِّي نُهِيتُ أَنْ أَقْرَأَ الْقُرْآنَ رَاكِعًا أَوْ سَاجِدًا، فَأَمَّا الرُّكُوعُ فَعَظِّمُوا فِيهِ الرَّبَّ عَزَّ وَجَلَّ وَأَمَّا السُّجُودُ فَاجْتَهِدُوا فِي الدُّعَاءِ فَقَمِنٌ أَنْ يُسْتَجَابَ لَكُمْ."],"takhrij":"صحيح: رواه مسلم في الصلاة (479) من طرق عن سفيان بن عيينة، أخبرني سليمان بن سحيم، عن إبراهيم بن عبدالله بن معبد، عن أبيه، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب الأوقات والأحوال التي ترجى فيها الإجابة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (479).","chapter_en":"Times and Circumstances in Which an Answer Is Hoped For","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Messenger of Allah ﷺ drew back the curtain while the people were standing in rows behind Abū Bakr, and said: “O people, nothing remains of the glad tidings of prophethood except a righteous dream which a Muslim sees or which is seen concerning him. Indeed, I have been forbidden from reciting the Qur’an while bowing or prostrating. As for bowing, glorify the Lord, Mighty and Majestic, during it. As for prostration, strive earnestly in supplication, for it is especially deserving of being answered for you.”"]}},"tuhfa":{},"voc":["seerah",1514],"full":1,"rep":[771,2108,2111,11814],"tks":"صحيح: رواه مسلم (479)."},{"num":10932,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ فَأَكْثِرُوا الدُّعَاءَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (482) من طريق سُمي مولى أبي بكر، أنه سمع ابا صالح ذكوان، يحدث عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الأوقات والأحوال التي ترجى فيها الإجابة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (482).","chapter_en":"Times and Circumstances in Which an Answer Is Hoped For","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The servant is nearest to his Lord while he is prostrating, so supplicate abundantly.”"]}},"tuhfa":{},"full":1,"rep":[2112],"tks":"صحيح: رواه مسلم (482)."},{"num":10933,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَكَرَ يَوْمَ الْجُمُعَةِ فَقَالَ: فِيهَا سَاعَةٌ لاَ يُوَافِقُهَا عبدٌ مُسْلِمٌ وَهْوَ قَائِمٌ يصلِّي، يَسْأَلُ اللَّهَ شَيْئًا إلاَّ أَعْطَاهُ إيَّاه.وَأَشَارَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ يُقلِّلها."],"takhrij":"متفق عليه: رواه مالك في الجمعة (15) عن أبي الزناد، عن الأعرج، عن أبي هريرة، فذكره.ورواه البخاري في الجمعة (935)، ومسلم في الجمعة (852) كلاهما من طريق مالكٍ به.","grade":"متفق عليه","chapter_ar":"باب الأوقات والأحوال التي ترجى فيها الإجابة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (15), al-Bukhārī (935), and Muslim (852).","chapter_en":"Times and Circumstances in Which an Answer Is Hoped For","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah narrated: The Messenger of Allah ﷺ mentioned Friday and said: “During it there is an hour which no Muslim servant encounters while standing in prayer and asking Allah for something except that Allah grants it to him.” The Messenger of Allah ﷺ gestured with his hand to indicate that this period is brief."]}},"tuhfa":{},"full":1,"rep":[3228,10755],"tks":"متفق عليه: رواه مالك (15)، والبخاري (935)، ومسلم (852)."},{"num":10934,"demo":false,"sanad":"","matn":["عَنْ أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى الْأَشْعَرِيِّ. قَالَ:  قَالَ لِي عَبْدُ اللَّهِ بْنُ عُمَرَ: أَسَمِعْتَ أَبَاكَ يُحَدِّثُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي شَأْنِ سَاعَةِ الْجُمُعَةِ؟ قَالَ: قُلْتُ: نَعَمْ. سَمِعْتُهُ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: هِيَ مَا بَيْنَ أَنْ يَجْلِسَ الْإِمَامُ إِلَى أَنْ تُقْضَى الصَّلَاةُ."],"takhrij":"صحيح: رواه مسلم في الجمعة (853) من طريق وهب، عن مخرمة بن بكير، عن أبيه، عن أبي بردة، فذكره.","grade":"صحيح","chapter_ar":"باب الأوقات والأحوال التي ترجى فيها الإجابة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (853).","chapter_en":"Times and Circumstances in Which an Answer Is Hoped For","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Abū Burdah ibn Abī Mūsā al-Ashʿarī narrated: ʿAbdullāh ibn ʿUmar asked me: “Did you hear your father narrate anything from the Messenger of Allah ﷺ concerning the hour on Friday?” I replied: “Yes. I heard him say: ʿI heard the Messenger of Allah ﷺ say: “It is the period between the imam’s sitting down and the completion of the prayer.”’”"]}},"tuhfa":{},"full":1,"rep":[3234,10756],"tks":"صحيح: رواه مسلم (853)."},{"num":10935,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، أَنَّهُ قَالَ: خَرَجْتُ إِلَى الطُّورِ، فَلَقِيتُ كَعْبَ الأَحْبَارِ، فَجَلَسْتُ مَعَهُ، فَحَدَّثَنِي عَنِ التَّوْرَاةِ، وَحَدَّثْتُهُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَكَانَ فِيمَا حَدَّثْتُهُ، أَنْ قُلْتُ: لَهُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَيْرُ يَوْمٍ طَلَعَتْ عَلَيْهِ الشَّمْسُ يَوْمُ الْجُمُعَةِ، فِيهِ خُلِقَ آدَمُ، وَفِيهِ أُهْبِطَ، وَفِيهِ مَاتَ، وَفِيهِ تِيبَ عَلَيْهِ، وَفِيهِ تَقُومُ السَّاعَةُ، وَمَا مِنْ دَابَّةٍ إِلَاّ وَهِيَ مُصِيخَةٌ يَوْمَ الْجُمُعَةِ، مِنْ حِينِ تُصْبِحُ، حَتَّى تَطْلُعَ الشَّمْسُ، شَفَقًا مِنَ السَّاعَةِ، إِلَاّ الْجِنَّ، وَالإِنْسَ، وَفِيهِ سَاعَةٌ لَا يُصَادِفُهَا عَبْدٌ مُسْلِمٌ، وَهُوَ يُصَلِّي يَسْأَلُ اللَّهَ شَيْئًا إِلَاّ أَعْطَاهُ إِيَّاهُ، قَالَ كَعْبٌ: ذَلِكَ فِي كُلِّ سَنَةٍ يَوْمٌ، فَقُلْتُ: بَلْ فِي كُلِّ جُمُعَةٍ، قَالَ: فَقَرَأَ كَعْبٌ التَّوْرَاةَ، فَقَالَ: صَدَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.","قَالَ أَبُو هُرَيْرَةَ: ثُمَّ لَقِيتُ عبدالله بْنَ سَلَامٍ فَحَدَّثْتُهُ بِمَجْلِسِي مَعَ كَعْبِ الأَحْبَارِ، وَمَا حَدَّثْتُهُ بِهِ فِي يَوْمِ الْجُمُعَةِ، فَقُلْتُ: قَالَ كَعْبٌ: ذَلِكَ فِي كُلِّ سَنَةٍ يومٌ.قال: قَالَ عبدالله بْنُ سَلَامٍ: كَذَبَ كعبٌ.فقلت: ثُمَّ قَرَأَ كَعْبٌ التَّوْرَاةَ فَقَالَ: بَلْ هِيَ فِي كُلِّ جمعةٍ.فقال عبدالله بْنُ سَلَامٍ: صَدَقَ كعبٌ.ثمَّ قَالَ عبدالله بْنُ سَلَامٍ: قَدْ عَلِمْتُ أَيَّةَ سَاعَةٍ هيَ.قال أَبُو هُرَيْرَةَ: فَقُلْتُ لَهُ: أَخْبِرْنِي بِهَا وَلَا تَضَنَّ عليَّ.فقال عبدالله بْنُ سَلَامٍ: هِيَ آخِرُ سَاعَةٍ فِي يَوْمِ الجمعةِ.قال أَبُو هُرَيْرَةَ: فَقُلْتُ: وَكَيْفَ تَكُونُ آخِرُ سَاعَةٍ فِي يَوْمِ الْجُمُعَةِ وَقَدْ قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: لَا يُصَادِفُهَا عَبْدٌ مُسْلِمٌ وَهُوَ يصلِّي.وتلك السَّاعَةُ سَاعَةٌ لَا يُصَلَّي فِيهَا؟ فَقَالَ عبدالله بْنُ سَلَامٍ: أَلَمْ يَقُلْ رَسُولُ اللهِ صلى الله عليه وسلم: مَنْ جَلَسَ مَجْلِسًا يَنْتَظِرُ الصَّلَاةَ فَهُوَ فِي صَلَاةٍ حَتَّى يُصَلِّيَ؟ قَالَ أَبُو هُرَيْرَةَ: فَقُلْتُ: بلى.قال: فَهُوَ ذَلِكَ."],"takhrij":"صحيح: رواه مالك في الجمعة (16) عن يزيد بن عبدالله بن الهاد، عن محمد بن إبراهيم بن الحارث التيمي، عن أبي سلمة بن عبدالرحمن بن عوف، عن أبي هريرةَ فذكره.","grade":"صحيح","chapter_ar":"باب الأوقات والأحوال التي ترجى فيها الإجابة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (16), Abū Dāwūd (1046), and al-Tirmidhī (491), and authenticated by Ibn Ḥibbān (2772) and al-Ḥākim (1/178).","chapter_en":"Times and Circumstances in Which an Answer Is Hoped For","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah said: I went out to Mount al-Ṭūr and met Kaʿb al-Aḥbār. I sat with him, and he narrated to me from the Torah, while I narrated to him from the Messenger of Allah ﷺ. Among what I narrated to him was that the Messenger of Allah ﷺ said: “The best day upon which the sun rises is Friday. On it Adam was created, on it he was sent down from Paradise, on it his repentance was accepted, on it he died, and on it the Hour will be established. There is no creature except that it listens attentively on Friday from morning until sunrise, fearing the establishment of the Hour, except the jinn and humankind. During it there is an hour which no Muslim servant encounters while praying and asking Allah for something except that Allah grants it to him.” Kaʿb asked: “Does that occur on one day of every year?” I replied: “Rather, it occurs every Friday.” Kaʿb read the Torah and then said: “The Messenger of Allah ﷺ spoke the truth.” Abū Hurayrah continued: I later met ʿAbdullāh ibn Salām and told him about my gathering with Kaʿb al-Aḥbār and what I had narrated to him concerning Friday. I told him that Kaʿb had initially said: “It occurs on one day of every year.”","ʿAbdullāh ibn Salām said: “Kaʿb was mistaken.” I then told him that Kaʿb had read the Torah and said: “Rather, it occurs every Friday.” ʿAbdullāh ibn Salām said: “Kaʿb spoke the truth.” He then said: “I know which hour it is.” Abū Hurayrah said: I told him: “Tell me which hour it is, and do not withhold it from me.” ʿAbdullāh ibn Salām replied: “It is the final hour of Friday.” I asked: “How can it be the final hour of Friday when the Messenger of Allah ﷺ said, ‘No Muslim servant encounters it while praying,’ while that is a time in which prayer is not performed?” ʿAbdullāh ibn Salām replied: “Did the Messenger of Allah ﷺ not say, ‘Whoever sits waiting for the prayer remains in a state of prayer until he performs it’?” Abū Hurayrah said: “Yes.” He replied: “That is what is meant.”"]},"buhuth":{"en":["The word “muṣīkhah” means listening attentively and expectantly while anticipating the establishment of the Hour."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (16)، وأبو داود (1046)، والترمذي (491)، وصححه ابن حبان (2772)، والحاكم (1030)."},{"num":10936,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: الْتَمِسُوا السَّاعَةَ الَّتِي تُرْجَى فِي يَوْمِ الْجُمُعَةِ بَعْدَ الْعَصْرِ إِلَى غَيْبُوبَةِ الشَّمْسِ."],"takhrij":"حسن: رواه الترمذي (489) عن عبد الله بن الصباح الهاشمي البصري، قال: حدثنا عبيد الله بن عبد المجيد الحنفي، قال: حدثنا محمد بن أبي حميد، قال: حدثنا موسى بن وردان، عن أنس، فذكره.","grade":"حسن","chapter_ar":"باب الأوقات والأحوال التي ترجى فيها الإجابة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (489) and al-Ṭabarānī in al-Muʿjam al-Awsaṭ (136).","chapter_en":"Times and Circumstances in Which an Answer Is Hoped For","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “Seek the hour in which an answer is hoped for on Friday after the ʿAṣr prayer until sunset.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3235],"tks":"حسن: رواه الترمذي (489)، والطبراني في الأوسط (136)."},{"num":10937,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: يَوْمُ الْجُمُعَةِ ثِنْتَا عَشْرَةَ. يُرِيدُ: سَاعَةً لاَ يُوجَدُ مُسْلِمٌ يَسْأَلُ اللَّهَ عَزَّ وَجَلَّ شَيْئًا إِلاَّ آتَاهُ اللَّهُ عَزَّ وَجَلَّ، فَالْتَمِسُوهَا آخِرَ سَاعَةٍ بَعْدَ الْعَصْرِ."],"takhrij":"حسن: رواه أبو داود (1048) والنسائي (1389) كلاهما من طريق ابن وهب، عن عمرو بن الحارث، عن الجلاح – مولى عبد العزيز -، أنَّ أبا سلمة حدَّثه، عن جابر بن عبدالله، فذكره.","grade":"حسن","chapter_ar":"باب الأوقات والأحوال التي ترجى فيها الإجابة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (1048) and al-Nasā’ī (1389).","chapter_en":"Times and Circumstances in Which an Answer Is Hoped For","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Jābir narrated that the Messenger of Allah ﷺ said: “Friday consists of twelve hours. There is an hour during it in which no Muslim asks Allah, Mighty and Majestic, for anything except that Allah grants it to him. Therefore, seek it during the final hour after the ʿAṣr prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3236,10757],"tks":"حسن: رواه أبو داود (1048)، والنسائي (1389)."},{"num":10938,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن سلام، قَالَ: قُلْتُ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ: إنَّا لَنَجِدُ فِي كِتَابِ اللَّهِ فِي يَوْمِ الْجُمُعَةِ سَاعَةٌ لاَ يُوَافِقُهَا عبدٌ مُؤْمِنٌ يصلِّي يَسْأَلُ اللَّهَ فِيهَا شَيْئًا إلاَّ قَضَى لَهُ حَاجَتَهُ.","قال عبدالله: فأشار إليَّ رسول الله صلى الله عليه وسلم: أو بعض ساعة.فقلت: صدقتَ، أو بعض ساعة.قلتُ: أي ساعة هي؟ قال: هي آخر ساعات النهار.قلت: إنَّها ليست ساعة صلاة.قال: بلى.إنَّ العبد المؤمن إذا صلَّى ثمَّ جلس، لا يحبسه إلاَّ الصلاة فهو في الصلاة."],"takhrij":"حسن: رواه ابن ماجه (1139) عن عبدالرحمن بن إبراهيم الدمشقي، ثنا ابن أبي فُديك، عن الضحاك بن عثمان، عن أبي النضر، عن أبي سلمة، عن عبدالله بن سلام، فذكره.وإسناده حسن؛ من أجل الضحاك بن عثمان فإنه صدوق.","grade":"حسن","chapter_ar":"باب الأوقات والأحوال التي ترجى فيها الإجابة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (1139).","chapter_en":"Times and Circumstances in Which an Answer Is Hoped For","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullāh ibn Salām said: While the Messenger of Allah ﷺ was seated, I said: “We find in the Book of Allah that on Friday there is an hour which no believing servant encounters while praying and asking Allah for something except that Allah fulfills his need.” ʿAbdullāh said: The Messenger of Allah ﷺ gestured to me and said: “Or part of an hour.” I replied: “You have spoken the truth—part of an hour.” I asked: “Which hour is it?” He replied: “It is the final hour of the day.”","I said: “That is not an hour of prayer.” He replied: “Indeed it is. When a believing servant performs the prayer and then remains seated, with nothing keeping him there except his anticipation of the next prayer, he remains in a state of prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3237],"tks":"حسن: رواه ابن ماجه (1139)."},{"num":10939,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَوْ أَبِي سَعِيدٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ لِلَّهِ عُتَقَاءَ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ، لِكُلِّ عَبْدٍ مِنْهُمْ دَعْوَةٌ مُسْتَجَابَةٌ."],"takhrij":"صحيح: رواه أحمد (7450) عن أبي معاوية، حدثنا الأعمش، عن أبي صالح، عن أبي هريرة أو أبي سعيد فذكره.","grade":"صحيح","chapter_ar":"باب الأوقات والأحوال التي ترجى فيها الإجابة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (7450).","chapter_en":"Times and Circumstances in Which an Answer Is Hoped For","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah—or Abū Saʿīd—narrated that the Messenger of Allah ﷺ said: “Allah has people whom He frees from the Fire every day and night, and every one of them has a supplication that is answered.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (7450)."},{"num":10940,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ للَّهِ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ عُتَقَاءَ مِنَ النَّارِ فِي شَهْرِ رَمَضَانَ، وَإِنَّ لِكُلِّ مُسْلِمٍ دَعْوَةً يَدْعُو بِهَا فَيُسْتَجَابُ لَهُ."],"takhrij":"حسن: رواه البزار (كشف الأستار 3142) عن محمد بن أبي غالب، حدثنا أبو صالح الفراء محبوب بن موسى، حدثنا أبو إسحاق الفزاري، عن الأعمش، عن أبي صالح، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب الأوقات والأحوال التي ترجى فيها الإجابة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār in Kashf al-Astār (3142).","chapter_en":"Times and Circumstances in Which an Answer Is Hoped For","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Jābir narrated that the Messenger of Allah ﷺ said: “During the month of Ramadan, Allah frees people from the Fire every day and night, and every Muslim has a supplication which he offers and which is answered.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (3142)."},{"num":10941,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثَلاَثَةٌ لاَ تُرَدُّ دَعْوَتُهُمُ: الإِمَامُ الْعَادِلُ، وَالصَّائِمُ حَتَّى يُفْطِرَ، وَدَعْوَةُ الْمَظْلُومِ يَرْفَعُهَا اللَّهُ دُونَ الْغَمَامِ يَوْمَ الْقِيَامَةِ، وَتُفْتَحُ لَهَا أَبْوَابُ السَّمَاءِ وَيَقُولُ بِعِزَّتِي لأَنْصُرَنَّكِ وَلَوْ بَعْدَ حِينٍ."],"takhrij":"حسن: رواه ابن ماجه (1752)، والترمذي (3598)، وأحمد (10183).وصحّحه ابن خزيمة (1901)، وابن حبان (3428)كلّهم من حديث سعدان الجهني، عن سعد أبي مجاهد الطائيّ ، عن أبي مدلة، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب من يستجاب دعاؤه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (1752), al-Tirmidhī (3598), and Aḥmad (8043), and authenticated by Ibn Khuzaymah (1901).","chapter_en":"Those Whose Supplications Are Answered","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The supplications of three people are not rejected: the just ruler, the fasting person until he breaks his fast, and the oppressed person. Allah raises the supplication of the oppressed beneath the clouds on the Day of Resurrection, the gates of heaven are opened for it, and He says: ‘By My might, I will surely support you, even if it is after some time.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4390],"tks":"حسن: رواه ابن ماجه (1752)، والترمذي (3598)، وأحمد (10183)، وصححه ابن خزيمة (1901)."},{"num":10942,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثَلَاثُ دَعَوَاتٍ لَا تُرَدُّ، دَعْوَةُ الْوَالِدِ، وَدَعْوَةُ الصَّائِمِ، وَدَعْوَةُ الْمُسَافِرِ."],"takhrij":"حسن: رواه البيهقي (6392)، والضياء في المختارة (2057) كلاهما من طريق أبي العباس محمد بن يعقوب، حدّثنا إبراهيم بن بكر المروزي، حدثنا السهمي عبدالله بن بكر، حدثنا حميد الطويل، عن أنس بن مالك، قال (فذكر الحديث).","grade":"حسن","chapter_ar":"باب من يستجاب دعاؤه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqī (3/345) and al-Ḍiyāʾ in al-Mukhtārah (2057).","chapter_en":"Those Whose Supplications Are Answered","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":11,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “Three supplications are not rejected: the supplication of a parent, the supplication of a fasting person, and the supplication of a traveler.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4391],"tks":"حسن: رواه البيهقي (6392)، والضياء في المختارة (2057)."},{"num":10943,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ زَيْدِ بْنِ عَمْرِو بْنِ نُفَيْلٍ:  أَنَّ أَرْوَى خَاصَمَتْهُ فِي بَعْضِ دَارِهِ، فَقَالَ: دَعُوهَا وَإِيَّاهَا، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ أَخَذَ شِبْرًا مِنَ الْأَرْضِ بِغَيْرِ حَقِّهِ، طُوِّقَهُ فِي سَبْعِ أَرَضِينَ يَوْمَ الْقِيَامَةِ. اللَّهُمَّ إِنْ كَانَتْ كَاذِبَةً فَأَعْمِ بَصَرَهَا، وَاجْعَلْ قَبْرَهَا فِي دَارِهَا.","قَالَ: فَرَأَيْتُهَا عَمْيَاءَ تَلْتَمِسُ الجُدُرَ تَقُولُ: أَصَابَتْنِي دَعْوَةُ سَعِيدِ بْنِ زَيْدٍ، فَبَيْنَمَا هِي تَمْشِي فِي الدَّارِ، مَرَّتْ عَلَى بِئْرٍ فِي الدَّارِ، فَوَقَعَتْ فِيهَا فَكَانَتْ قَبْرَهَا."],"takhrij":"متفق عليه: رواه مسلم في المساقاة والمزارعة (1610: 138) عن حرملة بن يحيى، أخبرنا عبدالله بن وهب، حدثني عمر بن محمد، أن أباه حدثه، عن سعيد بن زيد بن عمرو بن نفيل فذكره.ورواه البخاري في المظالم (2452) من وجه آخر عن سعيد بن زيد فذكر المرفوع منه.","grade":"متفق عليه","chapter_ar":"باب من يستجاب دعاؤه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1610/138) and al-Bukhārī (2452).","chapter_en":"Those Whose Supplications Are Answered","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":11,"content":{"translation":{"en":["Saʿīd ibn Zayd ibn ʿAmr ibn Nufayl narrated that Arwā disputed with him concerning part of his house. He said: “Leave it to her, for I heard the Messenger of Allah ﷺ say: ‘Whoever wrongfully takes even a handspan of land will have it hung around his neck from seven earths on the Day of Resurrection.’ He then supplicated: “O Allah, if she is lying, blind her sight and make her grave inside her own house.” He said: I later saw her blind, feeling her way along the walls and saying: “The supplication of Saʿīd ibn Zayd has afflicted me.”","While she was walking inside the house, she passed by a well located there, fell into it, and it became her grave."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (1610: 138)، والبخاري (2452)."},{"num":10944,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ مُعَاذًا إِلَى الْيَمَنِ، فَقَالَ: اتَّقِ دَعْوَةَ الْمَظْلُومِ، فَإِنَّهَا لَيْسَ بَيْنَهَا وَبَيْنَ اللَّهِ حِجَابٌ."],"takhrij":"متفق عليه: رواه البخاري في المظالم (2448) عن يحيى بن موسى، ثنا وكيع، ثنا زكريا بن إسحاق المكي، عن يحيى بن عبد الله بن صيفي، عن أبي معبد مولى ابن عباس، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب اتقاء دعوة المظلوم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2448) and Muslim (19).","chapter_en":"Guarding against the Supplication of the Oppressed","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Prophet ﷺ sent Muʿādh to Yemen and said: “Beware of the supplication of the oppressed, for there is no barrier between it and Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[5912],"tks":"متفق عليه: رواه البخاري (2448)، ومسلم (19)."},{"num":10945,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اتَّقُوا دَعَوَاتِ الْمَظْلُومِ فَإِنَّهَا تَصْعَدُ إِلَى السَّمَاءِ كَأَنَّهَا شَرَارٌ."],"takhrij":"حسن: رواه الحاكم (81) من طرق عن أبي كريب، حدثنا حسين بن علي، عن زائدة، عن عاصم بن كليب، عن محارب بن دثار، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب اتقاء دعوة المظلوم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ḥākim (81).","chapter_en":"Guarding against the Supplication of the Oppressed","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “Beware of the supplications of the oppressed, for they rise toward heaven like sparks.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[277],"tks":"حسن: رواه الحاكم (81)."},{"num":10946,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّهَا النَّاسُ إِنَّ اللَّهَ طَيِّبٌ لَا يَقْبَلُ إِلَّا طَيِّبًا، وَإِنَّ اللَّهَ أَمَرَ الْمُؤْمِنِينَ بِمَا أَمَرَ بِهِ الْمُرْسَلِينَ فَقَالَ: ﴿يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا إِنِّي بِمَا تَعْمَلُونَ عَلِيمٌ﴾ [سورة المؤمنون: 51] [الْمُؤْمِنُونَ : 51] وَقَالَ: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ وَاشْكُرُوا لِلَّهِ إِنْ كُنْتُمْ إِيَّاهُ تَعْبُدُونَ﴾ [البقرة: 172 ] ثُمَّ ذَكَرَ الرَّجُلَ يُطِيلُ السَّفَرَ أَشْعَثَ أَغْبَرَ، يَمُدُّ يَدَيْهِ إِلَى السَّمَاءِ، يَا رَبِّ يَا رَبِّ، وَمَطْعَمُهُ حَرَامٌ، وَمَشْرَبُهُ حَرَامٌ، وَمَلْبَسُهُ حَرَامٌ، وَغُذِيَ بِالْحَرَامِ، فَأَنَّى يُسْتَجَابُ لِذَلِكَ."],"takhrij":"صحيح: رواه مسلم في الزكاة (1015) عن أبي كريب محمد بن العلاء، ثنا أبو أسامة، ثنا فضيل بن مرزوق، حدثني عدي بن ثابت، عن أبي حازم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب من لا يستجاب له الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1015).","chapter_en":"Those Whose Supplications Are Not Answered","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “O people, Allah is Pure and accepts only that which is pure. Allah has commanded the believers with the same command that He gave to the messengers. He said: ‘O messengers, eat from the good things and perform righteous deeds. Indeed, I am fully aware of what you do.’ [Sūrat al-Muʾminūn 23:51] And He said: ‘O you who believe, eat from the good things with which We have provided you, and give thanks to Allah if it is truly Him whom you worship.’ [Sūrat al-Baqarah 2:172] He then mentioned a man who travels for a long time, disheveled and covered in dust, stretching his hands toward the sky and saying: “O Lord! O Lord!” Yet his food is unlawful, his drink is unlawful, his clothing is unlawful, and he has been nourished with what is unlawful. The Prophet ﷺ said: “How, then, could his supplication be answered?”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1015)."},{"num":10947,"demo":false,"sanad":"","matn":["عن عُثْمَانَ بن أَبِي الْعَاصِ الثقفيّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: تُفْتَحُ أَبْوَابُ السَّمَاءِ نِصْفَ اللَّيْلِ، فَيُنَادِي مُنَادٍ: هَلْ مِنْ دَاعٍ فَيُسْتَجَابُ لَهُ؟ هَلْ مِنْ سَائِلٍ فَيُعْطَى؟ هَلْ مِنْ مَكْرُوبٍ فَيُفَرَّجُ عَنْهُ؟ فَلَا يَبْقَى مُسْلِمٌ يَدْعُو بِدَعْوَةٍ إِلَّا اسْتَجَابَ اللَّهُ لَهُ، إِلَّا زَانِيَةً تَسْعَى بِفَرْجِهَا أَوْ عَشَّارًا."],"takhrij":"حسن: رواه الطبرانيّ في الكبير (8391)، وفي الأوسط (مجمع البحرين 1381) عن إبراهيم بن هاشم البغوي، ثنا عبدالرحمن بن سلاّم الجمحيّ، ثنا داود بن عبدالرحمن العطّار، عن هشام بن حسان، عن محمد بن سيرين، عن عثمان بن أبي العاص، فذكره.","grade":"حسن","chapter_ar":"باب من لا يستجاب له الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (9/59) and in al-Muʿjam al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (1381).","chapter_en":"Those Whose Supplications Are Not Answered","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":13,"content":{"translation":{"en":["ʿUthmān ibn Abī al-ʿĀṣ al-Thaqafī narrated that the Prophet ﷺ said: “The gates of heaven are opened at midnight, and a caller announces: ‘Is there anyone supplicating so that he may be answered? Is there anyone asking so that he may be given? Is there anyone in distress so that his distress may be relieved?’ No Muslim remains who offers a supplication except that Allah, Mighty and Majestic, answers him—except a prostitute who earns through her immorality or an unjust tax collector.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4019],"tks":"حسن: رواه الطبراني في الكبير (8391)، وفي الأوسط، كما في مجمع البحرين (1381)."},{"num":10948,"demo":false,"sanad":"","matn":["عَنْ صَفْوَانَ بن عبدالله بْنِ صَفْوَانَ وَكَانَتْ تَحْتَهُ الدَّرْدَاءِ (وهي بِنْتُ أَبِي الدَّرْدَاءُ) قَالَ: قَدِمْتُ الشَّامَ، فَأَتَيْتُ أَبَا الدَّرْدَاءِ فِي مَنْزِلِهِ فَلَمْ أَجِدْهُ، وَوَجَدْتُ أُمَّ الدَّرْدَاءِ، فَقَالَتْ: أَتُرِيدُ الْحَجَّ الْعَامَ؟ فَقُلْتُ: نَعَمْ قَالَتْ: فَادْعُ اللَّهَ لَنَا بِخَيْرٍ، فَإِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: دَعْوَةُ الْمُسْلِمِ لِأَخِيهِ بِظَهْرِ الْغَيْبِ مُسْتَجَابَةٌ، عِنْدَ رَأْسِهِ مَلَكٌ مُوَكَّلٌ، كُلَّمَا دَعَا لِأَخِيهِ بِخَيْرٍ قَالَ الْمَلَكُ الْمُوَكَّلُ بِهِ: آمِينَ، وَلَكَ بِمِثْلٍ.","قَالَ: فَخَرَجْتُ إِلَى السُّوقِ فَلَقِيتُ أَبَا الدَّرْدَاءِ، فَقَالَ لِي مِثْلَ ذَلِكَ يَرْوِيهِ عَنِ النَّبِيِّ صلى الله عليه وسلم."],"takhrij":"صحيح: رواه مسلم في الذكر والدعاء (2733) عن إسحاق بن إبراهيم، أخبرنا عيسى بن يونس، حدثنا عبدالملك بن أبي سليمان، عن أبي الزبير، عن صفوان بن عبدالله بن صفوان فذكره.","grade":"صحيح","chapter_ar":"باب فضل الدعاء بظهر الغيب","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2733).","chapter_en":"The Virtue of Supplicating for Someone in Their Absence","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["Ṣafwān ibn ʿAbdullāh ibn Ṣafwān, who was married to al-Dardāʾ, the daughter of Abū al-Dardāʾ, narrated: I traveled to Syria and went to the home of Abū al-Dardāʾ, but I did not find him there. I found Umm al-Dardāʾ instead. She asked: “Do you intend to perform pilgrimage this year?” I replied: “Yes.” She said: “Then supplicate to Allah for good on our behalf, for the Prophet ﷺ used to say: ʿThe supplication of a Muslim for his brother in his absence is answered. At his head is an appointed angel. Whenever he supplicates for goodness for his brother, the appointed angel says: “Āmīn, and may you receive the same.”’”","I then went out to the marketplace and met Abū al-Dardāʾ, who narrated the same statement to me from the Prophet ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2733)."},{"num":10949,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ لَيَرْفَعُ الدَّرَجَةَ لِلْعَبْدِ الصَّالِحِ فِي الْجَنَّةِ فَيَقُولُ: يَا رَبِّ أَنَّى لِي هَذِهِ؟ فَيَقُولُ بِاسْتِغْفَارِ وَلَدِكَ لَكَ.وَفِي لفظ: بدعاء وَلَدِكَ لَكَ."],"takhrij":"حسن: رواه ابن ماجه (3660)، وأحمد (10610)، والبزار (9024) كلهم من طريق حمـاد بن سلمة، عن عاصم بن أبي النجود، عن أبي صالح، عن أبي هريرة قال: فذكره.واللفظ لأحمد، والرواية الثانية للبزار.","grade":"حسن","chapter_ar":"باب رفع الدرجات في الجنة بدعاء الولد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (3660), Aḥmad (10610), and al-Bazzār (9024).","chapter_en":"Ranks in Paradise Being Raised through a Child’s Supplication","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Allah, Mighty and Majestic, will raise the rank of a righteous servant in Paradise. He will ask: ‘My Lord, how did I attain this?’ Allah will say: ‘Through your child’s seeking forgiveness for you.’” Another wording states: “Through your child’s supplication for you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13407],"tks":"حسن: رواه ابن ماجه (3660)، وأحمد (10610)، والبزار (9024)."},{"num":10950,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنْ أُمِّ سُلَيْمٍ، أَنَّهَا قَالَتْ: يَا رَسُولَ اللَّهِ أَنَسٌ، خَادِمُكَ ادْعُ اللَّهَ لَهُ، قَالَ اللَّهُمَّ أَكْثِرْ مَالَهُ وَوَلَدَهُ، وَبَارِكْ لَهُ فِيمَا أَعْطَيْتَهُ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6378)ومسلم في فضائل الصحابة (2480) كلاهما من طريق شعبة قـال: سمعت قتادة، يحدث عن أنس، عن أم سليم فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الدعاء لكثرة المال والولد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6378) and Muslim (2480).","chapter_en":"Supplicating for an Increase in Wealth and Children","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":16,"content":{"translation":{"en":["Anas narrated that Umm Sulaym said: “O Messenger of Allah, Anas is your servant, so supplicate to Allah for him.” He said: “O Allah, increase his wealth and children, and bless him in what You have given him.”"]}},"tuhfa":{},"full":1,"rep":[10103],"tks":"متفق عليه: رواه البخاري (6378)، ومسلم (2480)."},{"num":10951,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ قَالَ: سِرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ بَطْنِ بُوَاطٍ، وَهُوَ يَطْلُبُ الْمَجْدِيَّ بْنَ عَمْرٍو الْجُهَنِيَّ، وَكَانَ النَّاضِحُ يَعْتَقِبُهُ مِنَّا الْخَمْسَةُ وَالسِّتَّةُ وَالسَّبْعَةُ، فَدَارَتْ عُقْبَةُ رَجُلٍ مِنَ الْأَنْصَارِ عَلَى نَاضِحٍ لَهُ، فَأَنَاخَهُ، فَرَكِبَهُ، ثُمَّ بَعَثَهُ فَتَلَدَّنَ عَلَيْهِ بَعْضَ التَّلَدُّنِ، فَقَالَ لَهُ: شَأْ، لَعَنَكَ اللهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ هَذَا اللَّاعِنُ بَعِيرَهُ؟. قَالَ: أَنَا يَا رَسُولَ اللَّهِ. قَالَ: انْزِلْ عَنْهُ، فَلَا تَصْحَبْنَا بِمَلْعُونٍ، لَا تَدْعُوا عَلَى أَنْفُسِكُمْ، وَلَا تَدْعُوا عَلَى أَوْلَادِكُمْ، وَلَا تَدْعُوا عَلَى أَمْوَالِكُمْ، لَا تُوَافِقُوا مِنَ اللَّهِ سَاعَةً يُسْأَلُ فِيهَا عَطَاءٌ فَيَسْتَجِيبُ لَكُمْ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (3009) من طرق عن حاتم بن إسماعيل، عن يعقوب بن مجاهد، عن عبادة بن الوليد بن عبادة بن الصامت، عن جابر في سياق طويل.","grade":"صحيح","chapter_ar":"باب النهي عن الدعاء على النفس والولد والمال","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (3009).","chapter_en":"The Prohibition of Supplicating against Oneself, One’s Children, or One’s Wealth","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":17,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: We traveled with the Messenger of Allah ﷺ during the expedition of Baṭn Buwāṭ while he was seeking al-Majdī ibn ʿAmr al-Juhanī. Five, six, or seven men would take turns riding a single camel. When the turn of a man from the Anṣār came, he made his camel kneel, mounted it, and then urged it forward. The camel hesitated somewhat, so he said: “Move! May Allah curse you!” The Messenger of Allah ﷺ asked: “Who is the one who cursed his camel?” The man replied: “It was I, O Messenger of Allah.” He said: “Dismount from it, for a cursed animal must not accompany us. Do not supplicate against yourselves, do not supplicate against your children, and do not supplicate against your wealth, lest you coincide with an hour in which Allah grants whatever is asked of Him, and your supplication is answered.”"]}},"tuhfa":{},"full":1,"rep":[12642,14671,14811],"tks":"صحيح: رواه مسلم (3009)."},{"num":10952,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ:  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَادَ رَجُلًا مِنَ الْمُسْلِمِينَ، قَدْ خَفَتَ فَصَارَ مِثْلَ الْفَرْخِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلْ كُنْتَ تَدْعُو بِشَيْءٍ أَوْ تَسْأَلُهُ إِيَّاهُ؟ قَالَ: نَعَمْ، كُنْتُ أَقُولُ: اللَّهُمَّ مَا كُنْتَ مُعَاقِبِي بِهِ فِي الْآخِرَةِ فَعَجِّلْهُ لِي فِي الدُّنْيَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سُبْحَانَ اللَّهِ لَا تُطِيقُهُ أَوْ لَا تَسْتَطِيعُهُ أَفَلَا قُلْتَ: اللَّهُمَّ ﴿آتِنَا فِي الدُّنْيَا حَسَنَةً، وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ﴾؟ قَالَ: فَدَعَا اللهَ لَهُ، فَشَفَاهُ."],"takhrij":"صحيح: رواه مسلم في الذكر والدعاء (2688) عن أبي الخطاب زياد بن يحيى الحساني حدثنا محمد بن أبي عدي عن حميد عن ثابت عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب كراهية الدعاء بتعجيل العقوبة في الدنيا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2688).","chapter_en":"The Dislike of Supplicating for Punishment to Be Hastened in This World","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":18,"content":{"translation":{"en":["Anas ibn Mālik narrated: The Messenger of Allah ﷺ visited a Muslim man who had become so weak that he resembled a small bird. The Messenger of Allah ﷺ asked him: “Were you supplicating for something or asking Allah for anything?” He replied: “Yes. I used to say: ‘O Allah, whatever punishment You intended for me in the Hereafter, hasten it for me in this world.’” The Messenger of Allah ﷺ said: “Glory be to Allah! You could not bear it—or you are unable to bear it. Why did you not say: ‘O Allah, grant us good in this world and good in the Hereafter, and protect us from the punishment of the Fire’?” He then supplicated to Allah for him, and Allah healed him."]}},"tuhfa":{},"full":1,"rep":[3483],"tks":"صحيح: رواه مسلم (2688)."},{"num":10953,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ أَبِي حَازِمٍ قَالَ:  دَخَلْنَا عَلَى خَبَّابٍ، وَقَدِ اكْتَوَى سَبْعَ كَيَّاتٍ فِي بَطْنِهِ فَقَالَ: لَوْمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَانَا أَنْ نَدْعُوَ بِالْمَوْتِ لَدَعَوْتُ بِهِ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6349، 6345)، ومسلم في الذكر (2681) كلاهما من طريق إسماعيل بن أبي خالد، عن قيس بن أبي حازم فذكره.والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن الدعاء بالموت","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6345, 6349) and Muslim (2681). The wording cited here is that of Muslim.","chapter_en":"The Prohibition of Supplicating for Death","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":19,"content":{"translation":{"en":["Qays ibn Abī Ḥāzim narrated: We entered upon Khabbāb after he had been cauterized seven times upon his abdomen. He said: “Had the Messenger of Allah ﷺ not forbidden us from supplicating for death, I would have supplicated for it.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6345، 6349)، ومسلم (2681)، والسياق لمسلم."},{"num":10954,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ يَتَمَنَّيَنَّ أَحَدٌ مِنْكُمُ الْمَوْتَ لِضُرٍّ نَزَلَ بِهِ، فَإِنْ كَانَ لاَ بُدَّ مُتَمَنِّيًا لِلْمَوْتِ فَلْيَقُلِ: اللَّهُمَّ أَحْيِنِي مَا كَانَتِ الْحَيَاةُ خَيْرًا لِي، وَتَوَفَّنِي إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِي."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6351)، ومسلم في الذكر والدعاء (2680) كلاهما من طريق إسماعيل بن علية، عن عبد العزيز بن صهيب، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن الدعاء بالموت","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6351) and Muslim (2680).","chapter_en":"The Prohibition of Supplicating for Death","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":19,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “None of you should wish for death because of a hardship that has afflicted him. Should he feel that he must do so, then let him say: ‘O Allah, keep me alive for as long as life is better for me, and cause me to die when death is better for me.’”"]}},"tuhfa":{},"full":1,"rep":[3526],"tks":"متفق عليه: رواه البخاري (6351)، ومسلم (2680)."},{"num":10955,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ ـ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يَتَمَنَّى أَحَدُكُمُ الْمَوْتَ، إِمَّا مُحْسِنًا فَلَعَلَّهُ يَزْدَادُ، وَإِمَّا مُسِيئًا فَلَعَلَّهُ يَسْتَعْتِبُ."],"takhrij":"صحيح: رواه البخاري في التمني (7235) عن عبدالله بن محمد، ثنا هشام بن يوسف، أخبرنا معمر، عن الزهري، عن أبي عبيد –اسمه سعد بن عبيد مولى عبد الرحمن بن أزهر-، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الدعاء بالموت","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5673, 7235).","chapter_en":"The Prohibition of Supplicating for Death","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":19,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “None of you should wish for death. If he is a doer of good, perhaps he will increase in goodness; and if he is a sinner, perhaps he will seek Allah’s forgiveness and turn back to Him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5673، 7235)."},{"num":10956,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَتَمَنَّى أَحَدُكُمُ الْمَوْتَ وَلَا يَدْعُ بِهِ مِنْ قَبْلِ أَنْ يَأْتِيَهُ، إِنَّهُ إِذَا مَاتَ أَحَدُكُمُ انْقَطَعَ عَمَلُهُ وَإِنَّهُ لَا يَزِيدُ الْمُؤْمِنَ عُمُْرُهُ إِلَّا خَيْرًا."],"takhrij":"صحيح: رواه مسلم في الذكر والدعاء (2682) عن محمد بن رافع، حدثنا عبدالرزاق، أخبرنا معمر، عن همام بن منبه قال: هذا ما حدثنا أبو هريرة عن رسول الله صلى الله عليه وسلم فذكر أحاديث منها هذا الحديث.","grade":"صحيح","chapter_ar":"باب النهي عن الدعاء بالموت","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2682).","chapter_en":"The Prohibition of Supplicating for Death","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":19,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “None of you should wish for death or supplicate for it before it comes to him. When one of you dies, his deeds come to an end, and an increase in the believer’s lifespan only increases him in goodness.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2682)."},{"num":10957,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَدِمَ الطُّفَيْلُ بْنُ عَمْرٍو عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ دَوْسًا قَدْ عَصَتْ وَأَبَتْ، فَادْعُ اللَّهَ عَلَيْهَا. فَظَنَّ النَّاسُ أَنَّهُ يَدْعُو عَلَيْهِمْ، فَقَالَ: اللَّهُمَّ اهْدِ دَوْسًا وَأْتِ بِهِمْ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6397)، ومسلم في فضائل الصحابة (2524) كلاهما من طريق أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب الدعاء للمشركين بالهداية","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6397) and Muslim (2524).","chapter_en":"Supplicating for the Guidance of the Polytheists","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":20,"content":{"translation":{"en":["Abū Hurayrah narrated: Al-Ṭufayl ibn ʿAmr came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, the tribe of Daws has disobeyed and refused to accept the truth, so supplicate against them.” The people thought that he would supplicate against them, but he said: “O Allah, guide Daws and bring them to me.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6397)، ومسلم (2524)."},{"num":10958,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كُنْتُ أَدْعُو أُمِّي إِلَى الْإِسْلَامِ وَهِيَ مُشْرِكَةٌ، فَدَعَوْتُهَا يَوْمًا، فَأَسْمَعَتْنِي فِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا أَكْرَهُ، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا أَبْكِي، قُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي كُنْتُ أَدْعُو أُمِّي إِلَى الْإِسْلَامِ فَتَأْبَى عَلَيَّ، فَدَعَوْتُهَا الْيَوْمَ، فَأَسْمَعَتْنِي فِيكَ مَا أَكْرَهُ، فَادْعُ اللَّهَ أَنْ يَهْدِيَ أُمَّ أَبِي هُرَيْرَةَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اللَّهُمَّ اهْدِ أُمَّ أَبِي هُرَيْرَةَ.فَخَرَجْتُ مُسْتَبْشِرًا بِدَعْوَةِ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ...الحديث بِطُولِهِ."],"takhrij":"صحيح: رواه مسلم في فضائل الصحابة (2491) عن عمرو الناقد، ثنا عمر بن يونس اليمامي، ثنا عكرمة بن عمار، عن أبي كثير، حدثني أبو هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الدعاء للمشركين بالهداية","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2491).","chapter_en":"Supplicating for the Guidance of the Polytheists","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":20,"content":{"translation":{"en":["Abū Hurayrah narrated: I used to call my mother to Islam while she was still a polytheist. One day I invited her to Islam, and she said something about the Messenger of Allah ﷺ that I hated to hear. I went to the Messenger of Allah ﷺ weeping and said: “O Messenger of Allah, I have been calling my mother to Islam, but she refuses. Today I called her again, and she said something about you that I hated. Supplicate to Allah to guide the mother of Abū Hurayrah.” The Messenger of Allah ﷺ said: “O Allah, guide the mother of Abū Hurayrah.” I left rejoicing because of the supplication of the Prophet of Allah ﷺ. This forms part of the hadith."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2491)."},{"num":10959,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن مَسْعُودٍ كَأَنِّي أَنْظُرُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحْكِي نَبِيًّا مِنَ الأَنْبِيَاءِ ضَرَبَهُ قَوْمُهُ فَأَدْمَوْهُ، وَهْوَ يَمْسَحُ الدَّمَ عَنْ وَجْهِهِ، وَيَقُولُ: اللَّهُمَّ اغْفِرْ لِقَوْمِي فَإِنَّهُمْ لاَ يَعْلَمُونَ."],"takhrij":"متفق عليه: رواه البخاري في أحاديث الأنبياء (3477) ومسلم في الجهاد (1792) كلاهما من حديث الأعمش، قال: حدثني شقيق، عن عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب دعاء النبي ﷺ لقومه بالعفو","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3477) and Muslim (1792).","chapter_en":"The Prophet’s Supplication for His People to Be Pardoned","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":21,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated: It is as though I can still see the Messenger of Allah ﷺ describing one of the prophets whose people struck him until they caused him to bleed. As he wiped the blood from his face, he said: “O Allah, forgive my people, for they do not know.”"]}},"tuhfa":{},"full":1,"rep":[8492,8869],"tks":"متفق عليه: رواه البخاري (3477)، ومسلم (1792)."},{"num":10960,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اللهُمَّ اغْفِرْ لِقَوْمِي فَإِنَّهُمْ لَا يَعْلَمُونَ."],"takhrij":"حسن: رواه الفسوي في المعرفة والتاريخ (1/338)، والطبراني في الكبير (5694)، وصحّحه ابن حبان (973) كلهم من طريق إبراهيم بن المنذر الحزامي، حدثنا محمد بن فليح، عن موسى بن عقبة، عن الزهري، عن سهل بن سعد.","grade":"حسن","chapter_ar":"باب دعاء النبي ﷺ لقومه بالعفو","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Fasawī in al-Maʿrifah wa al-Tārīkh (1/338), and authenticated by Ibn Ḥibbān (973).","chapter_en":"The Prophet’s Supplication for His People to Be Pardoned","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":21,"content":{"translation":{"en":["Sahl ibn Saʿd al-Sāʿidī narrated that on the Day of Uḥud, the Messenger of Allah ﷺ said: “O Allah, forgive my people, for they do not know.”"]},"buhuth":{"en":["The words “Forgive my people” refer to pardoning the harm they had committed against him personally. They do not mean seeking forgiveness for those among his people who died as polytheists, because Allah, the Exalted, prohibited that in His words:","“It is not for the Prophet and those who believe to seek forgiveness for the polytheists, even if they are close relatives, after it has become clear to them that they are the inhabitants of the Hellfire.”","[Sūrat al-Tawbah 9:113]","The words “after it has become clear to them” mean after it becomes clear that they died upon polytheism. During their lifetimes, however, supplication may be made for their guidance."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الفسوي في المعرفة والتاريخ (1/338)، وصححه ابن حبان (973)."},{"num":10961,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ. فِي الرَّكْعَةِ الآخِرَةِ مِنْ صَلاَةِ الْعِشَاءِ قَنَتَ: اللَّهُمَّ أَنْجِ عَيَّاشَ بْنَ أَبِي رَبِيعَةَ، اللَّهُمَّ أَنْجِ الْوَلِيدَ بْنَ الْوَلِيدِ، اللَّهُمَّ أَنْجِ سَلَمَةَ بْنَ هِشَامٍ، اللَّهُمَّ أَنْجِ الْمُسْتَضْعَفِينَ مِنَ الْمُؤْمِنِينَ، اللَّهُمَّ اشْدُدْ وَطْأَتَكَ عَلَى مُضَرَ، اللَّهُمَّ اجْعَلْهَا سِنِينَ كَسِنِي يُوسُفَ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6393)، ومسلم في المساجد (675: 295) كلاهما من طريق يحيى بن أبي كثير، عن أبي سلمة (هو ابن عبد الرحمن بن عوف)، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب في الدعاء على المشركين والكافرين الظلمة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6393) and Muslim (675/295).","chapter_en":"Supplicating against the Polytheists and Unjust Disbelievers","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":22,"content":{"translation":{"en":["Abū Hurayrah narrated: When the Prophet ﷺ said, “Allah hears the one who praises Him,” during the final unit of the ʿIshāʾ prayer, he would recite the qunūt: “O Allah, rescue ʿAyyāsh ibn Abī Rabīʿah. O Allah, rescue al-Walīd ibn al-Walīd. O Allah, rescue Salamah ibn Hishām. O Allah, rescue the oppressed believers. O Allah, intensify Your punishment upon Muḍar. O Allah, inflict upon them years of famine like the years of Joseph.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6393)، ومسلم (675: 295)."},{"num":10962,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: لأُقَرِّبَنَّ صَلاَةَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَكَانَ أَبُو هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ يَقْنُتُ فِي الرَّكْعَةِ الآخِرَةِ مِنْ صَلاَةِ الظُّهْرِ، وَصَلاَةِ الْعِشَاءِ، وَصَلاَةِ الصُّبْحِ، بَعْدَ مَا يَقُولُ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ. فَيَدْعُو لِلْمُؤْمِنِينَ، وَيَلْعَنُ الْكُفَّارَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (797)، ومسلم في المساجد (676) كلاهما من طريق هشام (هو الدستوائي)، عن يحيى بن أبي كثير، ثنا أبو سلمة بن عبد الرحمن، أنه سمع أبا هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب في الدعاء على المشركين والكافرين الظلمة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (797) and Muslim (676).","chapter_en":"Supplicating against the Polytheists and Unjust Disbelievers","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":22,"content":{"translation":{"en":["Abū Hurayrah said: “I will show you the prayer that most closely resembles the prayer of the Prophet ﷺ.” Abū Hurayrah would recite the qunūt in the final unit of the Ẓuhr, ʿIshāʾ, and Fajr prayers after saying: “Allah hears the one who praises Him.” He would supplicate for the believers and invoke Allah’s curse upon the disbelievers."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (797)، ومسلم (676)."},{"num":10963,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَنَتَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَ الرُّكُوعِ شَهْرًا يَدْعُو عَلَى رِعْلٍ وَذَكْوَانَ وَيَقُولُ: عُصَيَّةُ عَصَتِ اللَّهَ وَرَسُولَهُ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4094)، ومسلم في المساجد (677: 299) كلاهما من طريق سليمان التيمي، عن أبي مجلز، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب في الدعاء على المشركين والكافرين الظلمة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4094) and Muslim (677/299).","chapter_en":"Supplicating against the Polytheists and Unjust Disbelievers","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":22,"content":{"translation":{"en":["Anas ibn Mālik narrated: The Prophet ﷺ recited the qunūt after bowing for one month, supplicating against the tribes of Riʿl and Dhakwān and saying: “ʿUṣayyah has disobeyed Allah and His Messenger.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4094)، ومسلم (677: 299)."},{"num":10964,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن أَبِي أَوْفَى قَالَ: دَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الأَحْزَابِ فَقَالَ: اللَّهُمَّ مُنْزِلَ الْكِتَابِ، سَرِيعَ الْحِسَابِ، اهْزِمِ الأَحْزَابَ، اهْزِمْهُمْ وَزَلْزِلْهُمْ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6392)، ومسلم في الجهاد (1742: 21) كلاهما من طريق إسماعيل بن أبي خالد، عن عبد الله بن أبي أوفى فذكره.","grade":"متفق عليه","chapter_ar":"باب في الدعاء على المشركين والكافرين الظلمة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6392) and Muslim (1742/21).","chapter_en":"Supplicating against the Polytheists and Unjust Disbelievers","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":22,"content":{"translation":{"en":["ʿAbdullāh ibn Abī Awfā narrated: The Messenger of Allah ﷺ supplicated against the confederate armies and said: “O Allah, Revealer of the Book, Swift in reckoning, defeat the confederates. Defeat them and shake them severely.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6392)، ومسلم (1742: 21)."},{"num":10965,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا سَأَلَ أَحَدُكُمْ فَلْيُكْثِرْ، فَإِنَّما يَسْأَلُ رَبَّهُ."],"takhrij":"صحيح: رواه ابن حبان (889) عن الحسن بن سفيان، حدثنا محمود بن غيلان، حدثنا أبو أحمد الزبيري، حدثنا سفيان (هو الثوري) عن هشام بن عروة، عن أبيه، عن عائشة قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب الإكثار من الدعاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Ḥibbān (889), ʿAbd ibn Ḥumayd (1496), and al-Ṭabarānī in al-Muʿjam al-Awsaṭ (2040).","chapter_en":"Supplicating Abundantly","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أحكام الدعاء","group_en":"Collection of Narrations Concerning the Rulings of Supplication","part_no":54,"group_no":5,"chapter_no":23,"content":{"translation":{"en":["ʿĀ’ishah narrated that the Messenger of Allah ﷺ said: “When one of you asks, let him ask abundantly, for he is asking his Lord.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان (889)، وعبد بن حميد (1496)، والطبراني في الأوسط (2040)."},{"num":10966,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب الأسلمي أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمِعَ رَجُلاً يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ أَنِّي أَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لاَ إِلَهَ إِلاَّ أَنْتَ الأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ، وَلَمْ يُولَدْ، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ.فَقَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَقَدْ سَأَلْتَ اللَّهَ بِالاِسْمِ الَّذِي إِذَا سُئِلَ بِهِ أَعْطَى، وَإِذَا دُعي بِهِ أَجَابَ."],"takhrij":"صحيح: رواه أبو داود (1493، 1494)، وابن ماجه (3857)، والترمذي (3475)، وصحّحه ابن حبان (891)، والحاكم (1858) كلهم من طريق مالك بن مغول، عن عبد الله بن بريدة، عن أبيه فذكر الحديث.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب التوسل إلى اللّٰه تعالى في الدعاء بأسمائه الحسنى وصفاته العلى","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1493, 1494), Ibn Mājah (3857), and al-Tirmidhī (3475), and authenticated by Ibn Ḥibbān (891).","chapter_en":"Seeking Nearness to Allah in Supplication through His Most Beautiful Names and Exalted Attributes","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في التوسل الشرعي في الدعاء","group_en":"Collection of Narrations Concerning Lawful Means of Seeking Nearness to Allah in Supplication","part_no":54,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Buraydah al-Aslamī narrated: The Messenger of Allah ﷺ heard a man saying: “O Allah, I ask You by my testimony that You are Allah. There is no deity worthy of worship except You, the One, the Self-Sufficient Master, who neither begets nor was born, and there is none comparable to Him.” The Messenger of Allah ﷺ said: “You have asked Allah by the Name through which, when He is asked, He gives, and when He is called upon, He answers.”"]},"intro_majmu":{"ar":["قال اللّٰه تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللّٰهَ وَابْتَغُوا إِلَيْهِ الْوَسِيلَةَ وَجَاهِدُوا فِي سَبِيلِهِ لَعَلَّكُمْ تُفْلِحُونَ﴾ [سورة المائدة: ٣٥].","وقال تعالى: ﴿أُولَئِكَ الَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَىٰ رَبِّهِمُ الْوَسِيلَةَ أَيُّهُمْ أَقْرَبُ، وَيَرْجُونَ رَحْمَتَهُ وَيَخَافُونَ عَذَابَهُ، إِنَّ عَذَابَ رَبِّكَ كَانَ مَحْذُورًا﴾ [الإسراء: ٥٧].","والوسيلة: هي القربة."],"en":["Allah, the Exalted, said:","“O you who believe, fear Allah, seek the means of nearness to Him, and strive in His path so that you may succeed.”","[Sūrat al-Māʾidah 5:35]","And He, the Exalted, said:","“Those whom they invoke themselves seek the means of nearness to their Lord, striving to see which of them will be nearer. They hope for His mercy and fear His punishment. Indeed, the punishment of your Lord is something to be feared.”","[Sūrat al-Isrāʾ 17:57]","The word al-wasīlah means a means of drawing near to Allah."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَلِلّٰهِ الْأَسْمَاءُ الْحُسْنَىٰ فَادْعُوهُ بِهَا﴾ [الأعراف: ١٨٠]."],"en":["Allah, the Exalted, said:","“To Allah belong the Most Beautiful Names, so call upon Him by them.”","[Sūrat al-Aʿrāf 7:180]"]}},"tuhfa":{},"full":1,"rep":[2186,10899,11035],"tks":"صحيح: رواه أبو داود (1493، 1494)، وابن ماجه (3857)، والترمذي (3475)، وصححه ابن حبان (891)."},{"num":10967,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا أَصَابَ عَبْدًا قطّ همٌّ وَلَا غمٌّ وَلَا حزنٌ، فَقَالَ: اللهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، ماضٍ فيَّ حُكْمُكَ، عدلٌ فيَّ قَضَاؤُكَ، أَسْأَلُكَ بكلّ اسْمٍ هُوَ لَكَ، سمّيتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجِلَاءَ حُزْنِي، وَذَهَابَ همّي وغمّي، إلاّ أَذْهَبَ اللهُ همَّه وغمَّه، وَأَبْدَلَهُ مَكَانَهُ فَرَحًا قَالُوا: يَا رَسُولَ اللَّهِ، أفلا نتعلمهنّ؟ قَالَ: بَلَى، يَنْبَغِي لِمَنْ يسمعهنّ أَنْ يتعلمهنّ."],"takhrij":"حسن: رواه أحمد (3712)، وأبو يعلى (5297)، والطبراني في الكبير (10352)، والبيهقي في الأسماء والصفات (7)، وصحّحه ابن حبان (972)، والحاكم (1877) كلهم من طريق فضيل بن مرزوق، قال: حدثنا أبو سلمة الجهني، عن القاسم بن عبدالرحمن، عن أبيه، عن ابن مسعود، فذكره.","grade":"حسن","chapter_ar":"باب التوسل إلى اللّٰه تعالى في الدعاء بأسمائه الحسنى وصفاته العلى","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (3712), Abū Yaʿlā (5297), al-Ṭabarānī in al-Muʿjam al-Kabīr (10/209–210), and al-Bayhaqī in al-Asmāʾ wa al-Ṣifāt (7), and authenticated by Ibn Ḥibbān (972) and al-Ḥākim (1877).","chapter_en":"Seeking Nearness to Allah in Supplication through His Most Beautiful Names and Exalted Attributes","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في التوسل الشرعي في الدعاء","group_en":"Collection of Narrations Concerning Lawful Means of Seeking Nearness to Allah in Supplication","part_no":54,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “No servant is ever afflicted by anxiety, grief, or sorrow and then says: ‘O Allah, I am Your servant, the son of Your male servant and the son of Your female servant. My forelock is in Your hand. Your judgment concerning me is always carried out, and Your decree concerning me is just. I ask You by every name that belongs to You—by which You have named Yourself, which You have revealed in Your Book, which You have taught to any of Your creation, or which You have kept exclusively with Yourself in the knowledge of the unseen—to make the Qur’an the spring of my heart, the light of my chest, the removal of my sorrow, and the departure of my anxiety and grief,’ except that Allah removes his anxiety and grief and replaces them with joy.” They asked: “O Messenger of Allah, should we not learn these words?” He replied: “Certainly. Whoever hears them should learn them.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11287],"tks":"حسن: رواه أحمد (3712)، وأبو يعلى (5297)، والطبراني في الكبير (10309)، والبيهقي في الأسماء والصفات (7)، وصححه ابن حبان (972)، والحاكم (1877)."},{"num":10968,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ:  بَيْنَمَا ثَلَاثَةُ نَفَرٍ يَتَمَشَّوْنَ أَخَذَهُمُ الْمَطَرُ، فَأَوَوْا إِلَى غَارٍ فِي جَبَلٍ فَانْحَطَّتْ عَلَى فَمِ غَارِهِمْ صَخْرَةٌ مِنَ الْجَبَلِ، فَانْطَبَقَتْ عَلَيْهِمْ، فَقَالَ بَعْضُهُمْ لِبَعْضٍ: انْظُرُوا أَعْمَالًا عَمِلْتُمُوهَا صَالِحَةً لِلهِ، فَادْعُوا اللَّهَ تَعَالَى بِهَا، لَعَلَّ اللَّهَ يَفْرُجُهَا عَنْكُمْ. فَقَالَ أَحَدُهُمُ: اللَّهُمَّ إِنَّهُ كَانَ لِي وَالِدَانِ شَيْخَانِ كَبِيرَانِ، وَامْرَأَتِي، وَلِي صِبْيَةٌ صِغَارٌ أَرْعَى عَلَيْهِمْ، فَإِذَا أَرَحْتُ عَلَيْهِمْ، حَلَبْتُ فَبَدَأْتُ بِوَالِدَيَّ، فَسَقَيْتُهُمَا قَبْلَ بَنِيَّ، وَأَنَّهُ نَأَى بِي ذَاتَ يَوْمٍ الشَّجَرُ، فَلَمْ آتِ حَتَّى أَمْسَيْتُ، فَوَجَدْتُهُمَا قَدْ نَامَا، فَحَلَبْتُ كَمَا كُنْتُ أَحْلُبُ، فَجِئْتُ بِالْحِلَابِ، فَقُمْتُ عِنْدَ رُءُوسِهِمَا أَكْرَهُ أَنْ أُوقِظَهُمَا مِنْ نَوْمِهِمَا، وَأَكْرَهُ أَنْ أَسْقِيَ الصِّبْيَةَ قَبْلَهُمَا، وَالصِّبْيَةُ يَتَضَاغَوْنَ عِنْدَ قَدَمَيَّ، فَلَمْ يَزَلْ ذَلِكَ دَأْبِي وَدَأْبَهُمْ حَتَّى طَلَعَ الْفَجْرُ، فَإِنْ كُنْتَ تَعْلَمُ أَنِّي فَعَلْتُ ذَلِكَ ابْتِغَاءَ وَجْهِكَ، فَافْرُجْ لَنَا مِنْهَا فُرْجَةً، نَرَى مِنْهَا السَّمَاءَ، فَفَرَجَ اللَّهُ مِنْهَا فُرْجَةً، فَرَأَوْا مِنْهَا السَّمَاءَ. وَقَالَ الْآخَرُ: اللَّهُمَّ إِنَّهُ كَانَتْ لِيَ ابْنَةُ عَمٍّ أَحْبَبْتُهَا كَأَشَدِّ مَا يُحِبُّ الرِّجَالُ النِّسَاءَ، وَطَلَبْتُ إِلَيْهَا نَفْسَهَا فَأَبَتْ حَتَّى آتِيَهَا بِمِائَةِ دِينَارٍ فَتَعِبْتُ حَتَّى جَمَعْتُ مِائَةَ دِينَارٍ، فَجِئْتُهَا بِهَا، فَلَمَّا وَقَعْتُ بَيْنَ رِجْلَيْهَا قَالَتْ: يَا عَبْدَ اللَّهِ اتَّقِ اللَّهَ، وَلَا تَفْتَحِ الْخَاتَمَ إِلَّا بِحَقِّهِ، فَقُمْتُ عَنْهَا، فَإِنْ كُنْتَ تَعْلَمُ أَنِّي فَعَلْتُ ذَلِكَ ابْتِغَاءَ وَجْهِكَ فَافْرُجْ لَنَا مِنْهَا فُرْجَةً، فَفَرَجَ لَهُمْ. وَقَالَ الْآخَرُ: اللَّهُمَّ إِنِّي كُنْتُ اسْتَأْجَرْتُ أَجِيرًا بِفَرَقِ أَرُزٍّ، فَلَمَّا قَضَى عَمَلَهُ قَالَ: أَعْطِنِي حَقِّي فَعَرَضْتُ عَلَيْهِ فَرَقَهُ فَرَغِبَ عَنْهُ، فَلَمْ أَزَلْ أَزْرَعُهُ حَتَّى جَمَعْتُ مِنْهُ بَقَرًا وَرِعَاءَهَا، فَجَاءَنِي فَقَالَ: اتَّقِ اللَّهَ، وَلَا تَظْلِمْنِي حَقِّي قُلْتُ: اذْهَبْ إِلَى تِلْكَ الْبَقَرِ وَرِعَائِهَا فَخُذْهَا فَقَالَ: اتَّقِ اللَّهَ، وَلَا تَسْتَهْزِئْ بِي فَقُلْتُ: إِنِّي لَا أَسْتَهْزِئُ بِكَ خُذْ ذَلِكَ الْبَقَرَ وَرِعَاءَهَا فَأَخَذَهُ، فَذَهَبَ بِهِ فَإِنْ كُنْتَ تَعْلَمُ أَنِّي فَعَلْتُ ذَلِكَ ابْتِغَاءَ وَجْهِكَ فَافْرُجْ لَنَا مَا بَقِيَ، فَفَرَجَ اللَّهُ مَا بَقِيَ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2215) ومسلم في الذكر (2743) كلاهما من حديث موسى بن عقبة، عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب التوسل إلى اللّٰه تعالى بالأعمال الصالحة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2215) and Muslim (2743).","chapter_en":"Seeking Nearness to Allah through Righteous Deeds","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في التوسل الشرعي في الدعاء","group_en":"Collection of Narrations Concerning Lawful Means of Seeking Nearness to Allah in Supplication","part_no":54,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “While three men were walking, rain overtook them, so they sought shelter in a cave within a mountain. A rock fell from the mountain over the entrance of their cave and completely sealed them inside. They said to one another: ‘Consider the righteous deeds that you performed sincerely for Allah, and call upon Allah through them. Perhaps Allah will remove this rock from you.’ One of them said: ʿO Allah, I had two elderly parents, a wife, and young children for whom I used to tend livestock. Whenever I returned to them in the evening, I would milk the animals and begin by giving my parents milk before my children. One day, the trees and grazing grounds took me far away, and I did not return until evening. I found that my parents had fallen asleep. I milked the animals as I normally did and brought the vessel of milk. I stood beside their heads, disliking to awaken them from their sleep and disliking to give my children milk before them. Meanwhile, the children were crying from hunger at my feet. This continued to be my condition and theirs until dawn broke. O Allah, if You know that I did this seeking Your pleasure, then open for us a gap through which we may see the sky.’ Allah opened a gap for them, and they could see the sky through it. The second man said: ʿO Allah, I had a female cousin whom I loved as intensely as a man could love a woman. I sought to have relations with her, but she refused unless I brought her one hundred dinars. I labored until I had gathered one hundred dinars and brought the money to her. When I had positioned myself between her legs, she said: “O servant of Allah, fear Allah and do not break the seal except lawfully.” I immediately rose and left her. O Allah, if You know that I did this seeking Your pleasure, then open another gap for us.’ Allah opened another gap for them. The third man said: ʿO Allah, I once hired a laborer in return for a faraq of rice. When he had completed his work, he said: “Give me my wages.” I offered him his faraq, but he rejected it and left. I continued cultivating and investing it until it produced cattle and their herdsmen. He later came to me and said: “Fear Allah and do not wrong me regarding my wages.” I told him: “Go to those cattle and their herdsmen and take them.” He replied: “Fear Allah and do not mock me.” I said: “I am not mocking you. Take those cattle and their herdsmen.” He took all of them and departed. O Allah, if You know that I did this seeking Your pleasure, then remove what remains of the rock.’” Allah removed the remainder of the rock."]},"buhuth":{"en":["The word “naʾā” means that something became distant.","The word “al-ḥilāb” refers to the vessel into which milk is drawn, large enough to contain the milk of one she-camel.","The expression “yataḍāghawn” means that the children were crying out and seeking relief because of hunger.","A faraq is a vessel that holds three ṣāʿs."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿رَبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا، رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا، وَكَفِّرْ عَنَّا سَيِّئَاتِنَا، وَتَوَفَّنَا مَعَ الْأَبْرَارِ﴾ [سورة آل عمران: ١٩٣]."],"en":["Allah, the Exalted, said:","“Our Lord, indeed we heard a caller calling to faith, saying, ‘Believe in your Lord,’ and so we believed. Our Lord, forgive us our sins, erase from us our evil deeds, and cause us to die among the righteous.”","[Sūrat Āl ʿImrān 3:193]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[5468,8286],"tks":"متفق عليه: رواه البخاري (2215)، ومسلم (2743)."},{"num":10969,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّ ثَلَاثَةَ نَفَرٍ فِيمَا سَلَفَ مِنَ النَّاسِ، انْطَلَقُوا يَرْتَادُونَ لِأَهْلِهِمْ، فَأَخَذَتْهُمُ السَّمَاءُ، فَدَخَلُوا غَارًا، فَسَقَطَ عَلَيْهِمْ حَجَرٌ مُتَجَافٍ، حَتَّى مَا يَرَوْنَ مِنْهُ حُصَاصَةً، فَقَالَ بَعْضُهُمْ لِبَعْضٍ: قَدْ وَقَعَ الْحَجَرُ، وَعَفَا الْأَثَرُ، وَلَا يَعْلَمُ بِمَكَانِكُمْ إِلَّا اللَّهُ، فَادْعُوا اللَّهَ بِأَوْثَقِ أَعْمَالِكُمْ.","قَالَ: فَقَالَ رَجُلٌ مِنْهُمْ: اللهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّهُ قَدْ كَانَ لِي وَالِدَانِ، فَكُنْتُ أَحْلِبُ لَهُمَا فِي إِنَائِهِمَا، فَآتِيهُمَا، فَإِذَا وَجَدْتُهُمَا رَاقِدَيْنِ قُمْتُ عَلَى رُءُوسِهِمَا كَرَاهِيَةَ أَنْ أَرُدَّ سِنَتَهُمَا فِي رُءُوسِهِمَا، حَتَّى يَسْتَيْقِظَا مَتَى اسْتَيْقَظَا، اللهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنِّي إِنَّمَا فَعَلْتُ ذَلِكَ رَجَاءَ رَحْمَتِكَ، وَمَخَافَةَ عَذَابِكَ، فَفَرِّجْ عَنَّا، قَالَ: فَزَالَ ثُلُثُ الْحَجَرِ.","وَقَالَ الْآخَرُ: اللهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنِّي اسْتَأْجَرْتُ أَجِيرًا عَلَى عَمَلٍ يَعْمَلُهُ، فَأَتَانِي يَطْلُبُ أَجْرَهُ، وَأَنَا غَضْبَانُ فَزَبَرْتُهُ، فَانْطَلَقَ فَتَرَكَ أَجْرَهُ ذَلِكَ، فَجَمَعْتُهُ وَثَمَّرْتُهُ حَتَّى كَانَ مِنْهُ كُلُّ الْمَالِ، فَأَتَانِي يَطْلُبُ أَجْرَهُ، فَدَفَعْتُ إِلَيْهِ ذَلِكَ كُلَّهُ، وَلَوْ شِئْتُ لَمْ أُعْطِهِ، إِلَّا أَجْرَهُ الْأَوَّلَ، اللهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنِّي إِنَّمَا فَعَلْتُ ذَلِكَ رَجَاءَ رَحْمَتِكَ، وَمَخَافَةَ عَذَابِكَ، فَفَرِّجْ عَنَّا، قَالَ: فَزَالَ ثُلُثَا الْحَجَرِ.","وَقَالَ الثَّالِثُ: اللهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّهُ أَعْجَبَتْهُ امْرَأَةٌ، فَجَعَلَ لَهَا جُعْلًا، فَلَمَّا قَدَرَ عَلَيْهَا وَقَّرَ لَهَا نَفْسَهَا وَسَلَّمَ لَهَا جُعْلَهَا، اللهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنِّي إِنَّمَا فَعَلْتُ ذَلِكَ رَجَاءَ رَحْمَتِكَ، وَمَخَافَةَ عَذَابِكَ، فَفَرِّجْ عَنَّا، فَزَالَ الْحَجَرُ، وَخَرَجُوا مَعَانِيقَ يَتَمَاشَوْنَ."],"takhrij":"صحيح: رواه أحمد (12454)، وأبو يعلى (2938)، والبزار (7189) كلهم من طرق عن أبي عوانة، عن قتادة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب التوسل إلى اللّٰه تعالى بالأعمال الصالحة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (12454), Abū Yaʿlā (2938), and al-Bazzār (7189).","chapter_en":"Seeking Nearness to Allah through Righteous Deeds","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في التوسل الشرعي في الدعاء","group_en":"Collection of Narrations Concerning Lawful Means of Seeking Nearness to Allah in Supplication","part_no":54,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “Three men from among the people of the past went out seeking provisions for their families. Rain overtook them, so they entered a cave. A large rock fell over them until they could see no opening through it. They said to one another: ‘The rock has fallen, all traces of us have been erased, and none knows your location except Allah. Therefore, call upon Allah through the deeds in which you had the greatest confidence.’” One of them said: “O Allah, You know that I had two parents. I would milk for them into their vessel and bring it to them. If I found them asleep, I would stand beside their heads, disliking to disturb their sleep, until one of them awoke. O Allah, if You know that I did this hoping for Your mercy and fearing Your punishment, then grant us relief.” One-third of the rock moved away. The second man said: “O Allah, You know that I hired a laborer to perform some work. He came to me asking for his wages while I was angry, so I rebuked him. He left without taking his wages. I collected and invested them until they became a great amount of wealth. He later came asking for his wages, so I gave all of it to him, although I could have given him only his original wage. O Allah, if You know that I did this hoping for Your mercy and fearing Your punishment, then grant us relief.”","Two-thirds of the rock moved away. The third man said: “O Allah, You know that I was attracted to a woman and offered her payment. When I gained power over her and she had surrendered herself to me, I left her and gave her the payment. O Allah, if You know that I did this hoping for Your mercy and fearing Your punishment, then grant us relief.” The rock moved away completely, and they emerged walking quickly together."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (12454)، وأبو يعلى (2938)، والبزار (7189)."},{"num":10970,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَرَجَ ثَلَاثَةٌ فِيمَنْ كَانَ قَبْلَكُمْ يَرْتَادُونَ لأَهْلِيهِمْ، فَأَصَابَتْهُمُ السَّمَاءُ، فَلَجَؤُوا إِلَى جَبَلٍ، فَوَقَعَتْ عَلَيْهِمْ صَخْرَةٌ، فَقَالَ بَعْضُهُمْ لِبَعْضٍ: عَفَا الأَثَرُ، وَوَقَعَ الْحَجَرُ، وَلَا يَعْلَمُ مَكَانَكُمْ إِلَاّ اللَّهُ، ادْعُوا اللهَ بِأَوْثَقِ أَعْمَالِكُمْ، فَقَالَ أَحَدُهُمُ: اللهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّهُ كَانَتِ امْرَأَةٌ تُعْجِبُنِي، فَطَلَبْتُهَا، فَأَبَتْ عَلَيَّ، فَجَعَلْتُ لَهَا جُعْلًا، فَلَمَّا قَرَّبَتْ نَفْسَهَا، تَرَكْتُهَا، فَإِنْ كُنْتَ تَعْلَمُ أَنِّي إِنَّمَا فَعَلْتُ ذَلِكَ رَجَاءَ رَحْمَتِكَ، وَخَشْيَةَ عَذَابِكَ، فَافْرُجْ عَنَّا، فَزَالَ ثُلُثُ الحجر، فَقَالَ الآخَرُ: اللهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّهُ كَانَ لِي وَالِدَانِ، وَكُنْتُ أَحْلُبُ لَهُمَا فِي إِنَائِهِمَا، فَإِذَا أَتَيْتُهُمَا، وَهُمَا نَائِمَانِ، قُمْتُ قَائِمًا حَتَّى يَسْتَيْقِظَا، فَإِذَا اسْتَيْقَظَا شَرِبَا، فَإِنْ كُنْتَ تَعْلَمُ أَنِّي فَعَلْتُ ذَلِكَ رَجَاءَ رَحْمَتِكَ وَخَشْيَةَ عَذَابِكَ فَافْرُجْ عَنَّا، فَزَالَ ثُلُثُ الْحَجَرِ، فَقَالَ الثَّالِثُ: اللهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنِّي اسْتَأْجَرْتُ أَجِيرًا يَوْمًا فَعَمِلَ لِي نِصْفَ النَّهَارِ، فَأَعْطَيْتُهُ أَجْرَهُ فَتَسَخَّطَهُ وَلَمْ يَأْخُذْهُ، فَوَفَّرْتُهَا عَلَيْهِ حَتَّى صَارَ مِنْ كُلِّ الْمَالِ، ثُمَّ جَاءَ يَطْلُبُ أَجْرَهُ، فَقُلْتُ: خُذْ هَذَا كُلَّهُ، وَلَوْ شِئْتُ لَمْ أُعْطِهِ إِلَاّ أَجْرَهُ الأول، فَإِنْ كُنْتَ تَعْلَمُ أَنِّي فَعَلْتُ ذَلِكَ رَجَاءَ رَحْمَتِكَ وَخَشْيَةَ عَذَابِكَ فَافْرُجْ عَنَّا، قَالَ: فَزَالَ الْحَجَرُ وَخَرَجُوا يَتَمَاشَوْنَ."],"takhrij":"حسن: رواه الطيالسي (2126)، والبزار (9556)، وصحّحه ابن حبان (971)، كلهم من طريق عمران القطان، عن قتادة، عن سعيد بن أبي الحسن، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب التوسل إلى اللّٰه تعالى بالأعمال الصالحة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭayālisī (2126) and al-Bazzār (9556), and authenticated by Ibn Ḥibbān (971).","chapter_en":"Seeking Nearness to Allah through Righteous Deeds","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في التوسل الشرعي في الدعاء","group_en":"Collection of Narrations Concerning Lawful Means of Seeking Nearness to Allah in Supplication","part_no":54,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Three men from among the people before you went out seeking provisions for their families. Rain overtook them, so they sought refuge in a mountain cave. A rock fell upon them and blocked the entrance. They said to one another: ‘Every trace has been erased, the rock has fallen, and none knows your location except Allah. Call upon Allah through your most dependable righteous deeds.’” One of them said: “O Allah, You know that there was a woman whom I greatly admired. I sought her, but she refused me, so I offered her payment. When she brought herself near to me, I left her. If You know that I did this hoping for Your mercy and fearing Your punishment, then grant us relief.” One-third of the rock moved. The second man said: “O Allah, You know that I had two parents. I would milk for them into their vessel. If I came to them while they were asleep, I would remain standing until they awakened, and when they awoke, they would drink. If You know that I did this hoping for Your mercy and fearing Your punishment, then grant us relief.” Another third of the rock moved. The third man said: “O Allah, You know that I once hired a laborer for a day. He worked for me for half the day, but when I gave him his wages, he was displeased with them and refused to take them. I preserved and invested the wages for him until they became all kinds of wealth. He later came asking for his wages, so I said: ‘Take all of this.’ Although I could have given him only his original wages, I gave him everything. If You know that I did this hoping for Your mercy and fearing Your punishment, then grant us relief.” The rock moved away, and they emerged walking together."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطيالسي (2126)، والبزار (9556)، وصححه ابن حبان (971)."},{"num":10971,"demo":false,"sanad":"","matn":["عن النُّعْمَانِ بْنِ بَشِيرٍ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَذْكُرُ الرَّقِيمَ فَقَالَ: إِنَّ ثَلَاثَةً نَفَرٍ كَانُوا فِي كَهْفٍ، فَوَقَعَ الْجَبَلُ عَلَى بَابِ الْكَهْفِ، فَأُوصِدَ عَلَيْهِمْ، قَالَ قَائِلٌ مِنْهُمْ: تَذَاكَرُوا أَيُّكُمْ عَمِلَ حَسَنَةً، لَعَلَّ اللَّهَ عَزَّ وَجَلَّ بِرَحْمَتِهِ يَرْحَمُنَا، فَقَالَ رَجُلٌ مِنْهُمْ: قَدْ عَمِلْتُ حَسَنَةً مَرَّةً: كَانَ لِي أُجَرَاءُ يَعْمَلُونَ، فَجَاءَنِي عُمَّالٌ لِي، اسْتَأْجَرْتُ كُلَّ رَجُلٍ مِنْهُمْ بِأَجْرٍ مَعْلُومٍ، فَجَاءَنِي رَجُلٌ ذَاتَ يَوْمٍ وَسَطَ النَّهَارِ، فَاسْتَأْجَرْتُهُ بِشَرْطِ أَصْحَابِهِ، فَعَمِلَ فِي بَقِيَّةِ نَهَارِهِ، كَمَا عَمِلَ كُلُّ رَجُلٍ مِنْهُمْ فِي نَهَارِهِ كُلِّهِ، فَرَأَيْتُ عَلَيَّ فِي الذِّمَامِ أَنْ لَا أُنْقِصَهُ مِمَّا اسْتَأْجَرْتُ بِهِ أَصْحَابَهُ، لِمَا جَهِدَ فِي عَمَلِهِ، فَقَالَ رَجُلٌ مِنْهُمْ: أَتُعْطِي هَذَا مِثْلَ مَا أَعْطَيْتَنِي وَلَمْ يَعْمَلْ إِلَّا نِصْفَ نَهَارٍ؟ فَقُلْتُ: يَا عَبْدَ اللَّهِ، لَمْ أَبْخَسْكَ شَيْئًا مِنْ شَرْطِكَ، وَإِنَّمَا هُوَ مَالِي أَحْكُمُ فِيهِ مَا شِئْتُ، قَالَ: فَغَضِبَ، وَذَهَبَ، وَتَرَكَ أَجْرَهُ، قَالَ: فَوَضَعْتُ حَقَّهُ فِي جَانِبٍ مِنَ الْبَيْتِ مَا شَاءَ اللَّهُ، ثُمَّ مَرَّتْ بِي بَعْدَ ذَلِكَ بَقَرٌ، فَاشْتَرَيْتُ بِهِ فَصِيلَةً مِنَ الْبَقَرِ، فَبَلَغَتْ مَا شَاءَ اللَّهُ، فَمَرَّ بِي بَعْدَ حِينٍ شَيْخًا ضَعِيفًا لَا أَعْرِفُهُ، فَقَالَ: إِنَّ لِي عِنْدَكَ حَقًّا فَذَكَّرَنِيهِ حَتَّى عَرَفْتُهُ، فَقُلْتُ: إِيَّاكَ أَبْغِي، هَذَا حَقُّكَ، فَعَرَضْتُهَا عَلَيْهِ جَمِيعَهَا، فَقَالَ: يَا عَبْدَ اللَّهِ، لَا تَسْخَرْ بِي إِنْ لَمْ تَصَدَّقْ عَلَيَّ، فَأَعْطِنِي حَقِّي، قَالَ: وَاللهِ مَا أَسْخَرُ بِكَ: إِنَّهَا لَحَقُّكَ مَا لِي مِنْهَا شَيْءٌ: فَدَفَعْتُهَا إِلَيْهِ جَمِيعًا. اللهُمَّ إِنْ كُنْتُ فَعَلْتُ ذَلِكَ لِوَجْهِكَ، فَافْرُجْ عَنَّا. قَالَ: فَانْصَدَعَ الْجَبَلُ حَتَّى رَأَوْا مِنْهُ، وَأَبْصَرُوا.","قَالَ الْآخَرُ: قَدْ عَمِلْتُ حَسَنَةً مَرَّةً كَانَ لِي فَضْلٌ، فَأَصَابَتِ النَّاسَ شِدَّةٌ، فَجَاءَتْنِي امْرَأَةٌ تَطْلُبُ مِنِّي مَعْرُوفًا، قَالَ: فَقُلْتُ: وَاللهِ مَا هُوَ دُونَ نَفْسِكِ، فَأَبَتْ عَلَيَّ، فَذَهَبَتْ، ثُمَّ رَجَعَتْ، فَذَكَّرَتْنِي بِاللهِ، فَأَبَيْتُ عَلَيْهَا وَقُلْتُ: لَا وَاللهِ مَا هُوَ دُونَ نَفْسِكِ، فَأَبَتْ عَلَيَّ، وَذَهَبَتْ، فَذَكَرَتْ لِزَوْجِهَا، فَقَالَ لَهَا: أَعْطِيهِ نَفْسَكِ، وَأَغْنِي عِيَالَكِ، فَرَجَعَتْ إِلَيَّ، فَنَاشَدَتْنِي بِاللهِ، فَأَبَيْتُ عَلَيْهَا، وَقُلْتُ: وَاللهِ مَا هُوَ دُونَ نَفْسِكِ، فَلَمَّا رَأَتْ ذَلِكَ أَسْلَمَتْ إِلَيَّ نَفْسَهَا، فَلَمَّا تَكَشَّفْتُهَا، وَهَمَمْتُ بِهَا، ارْتَعَدَتْ مِنْ تَحْتِي، فَقُلْتُ لَهَا: مَا شَأْنُكِ ؟ قَالَتْ: أَخَافُ اللهَ رَبَّ الْعَالَمِينَ، قُلْتُ: لَهَا خِفْتِيهِ فِي الشِّدَّةِ، وَلَمْ أَخَفْهُ فِي الرخاء.فتركتها وَأَعْطَيْتُهَا مَا يَحِقُّ عَلَيَّ بِمَا تكشفتها.اللهم إِنْ كُنْتُ فَعَلْتُ ذَلِكَ لِوَجْهِكَ، فَافْرُجْ عنا.قال: فَانْصَدَعَ حَتَّى عَرَفُوا وَتَبَيَّنَ لَهُمْ.","قَالَ الْآخَرُ: عَمِلْتُ حَسَنَةً مَرَّةً، كَانَ لِي أَبَوَانِ شَيْخَانِ كَبِيرَانِ، وَكَانَتْ لِي غَنَمٌ، فَكُنْتُ أُطْعِمُ أَبَوَيَّ وَأَسْقِيهِمَا، ثُمَّ رَجَعْتُ إِلَى غَنَمِي، قَالَ: فَأَصَابَنِي يَوْمًا غَيْثٌ حَبَسَنِي ، فَلَمْ أَبْرَحْ حَتَّى أَمْسَيْتُ، فَأَتَيْتُ أَهْلِي وَأَخَذْتُ مِحْلَبِي، فَحَلَبْتُ وَغَنَمِي قَائِمَةٌ، فَمَضَيْتُ إِلَى أَبَوَيَّ، فَوَجَدْتُهُمَا قَدْ نَامَا، فَشَقَّ عَلَيَّ أَنْ أُوقِظَهُمَا، وَشَقَّ عَلَيَّ أَنْ أَتْرُكَ غَنَمِي، فَمَا بَرِحْتُ جَالِسًا، وَمِحْلَبِي عَلَى يَدِي حَتَّى أَيْقَظَهُمَا الصُّبْحُ، فسقيتهما.اللهم إِنْ كُنْتُ فَعَلْتُ ذَلِكَ لِوَجْهِكَ، فَافْرُجْ عَنَّا.","قَالَ النُّعْمَانُ: لَكَأَنِّي أَسْمَعُ هَذِهِ مِنْ رَسُولِ اللهِ صلى الله عليه وسلم، قَالَ: الْجَبَلُ طَاقْ، فَفَرَّجَ اللهُ عَنْهُمْ، فَخَرَجُوا."],"takhrij":"حسن: رواه أحمد (18417)، والطبراني في الدعاء (190) كلاهما من حديث إسماعيل بن عبد الكريم بن معقل بن منبه، حدثني عبد الصمد –يعني ابن معقل- قال: سمعت وهبا يقول: حدثني النعمان بن بشير فذكره.","grade":"حسن","chapter_ar":"باب التوسل إلى اللّٰه تعالى بالأعمال الصالحة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (18417) and al-Ṭabarānī in al-Duʿāʾ (190).","chapter_en":"Seeking Nearness to Allah through Righteous Deeds","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في التوسل الشرعي في الدعاء","group_en":"Collection of Narrations Concerning Lawful Means of Seeking Nearness to Allah in Supplication","part_no":54,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr narrated that he heard the Messenger of Allah ﷺ mention al-Raqīm and say: “Three men were inside a cave when part of the mountain fell upon its entrance and sealed them inside. One of them said: ‘Recall which of you has performed a righteous deed. Perhaps Allah, Mighty and Majestic, will have mercy upon us through His mercy.’” One man said: “I once performed a righteous deed. I had laborers working for me, each of whom I hired for a known wage. One day, a man came to me at midday, and I hired him on the same terms as his companions. He worked during the remainder of the day as hard as each of the others had worked for the entire day. I considered myself morally bound not to give him less than the others because of the effort he had exerted. One of the other laborers said: ‘Will you give this man the same as you gave me, although he worked only half a day?’ I replied: ‘Servant of Allah, I have not deprived you of anything stipulated in your agreement. This is my wealth, and I may dispose of it as I wish.’ He became angry, departed, and left his wages behind. I placed his wages in a part of the house for as long as Allah willed. Later, some cattle passed by me, so I used his wages to purchase a young calf. It multiplied until it became as much as Allah willed. After a long time, an elderly and weak man passed by me whom I did not recognize. He said: ‘I have a right with you.’ He reminded me until I recognized him. I said: ‘You are the person I have been seeking. This is your property.’ I presented all of it to him. He said: ‘Servant of Allah, do not mock me. If you do not wish to give me charity, then give me my actual wages.’ I replied: ‘By Allah, I am not mocking you. All of this belongs to you, and none of it belongs to me.’ I handed it all over to him. O Allah, if I did this for Your sake, then grant us relief.” The mountain split enough for them to see through it. The second man said: “I once performed a righteous deed. I possessed surplus wealth when the people were afflicted by severe hardship. A woman came to me seeking assistance. I said: ‘By Allah, I will not give it to you unless you surrender yourself to me.’ She refused and left. She later returned and reminded me of Allah, but I refused and said: ‘By Allah, I will not give it to you unless you surrender yourself to me.’ She again refused and left. She mentioned the matter to her husband, who told her: ‘Give him what he wants and provide for your children.’","She returned to me and implored me by Allah, but I still refused, saying: ‘By Allah, I will not give it to you unless you surrender yourself to me.’ When she saw my determination, she surrendered herself to me. When I uncovered her and was about to commit the act, she trembled beneath me. I asked: ‘What is wrong with you?’ She replied: ‘I fear Allah, Lord of the worlds.’ I said: ‘You feared Him during hardship, while I did not fear Him during ease!’ I left her and gave her the amount I owed her because I had uncovered her. O Allah, if I did this for Your sake, then grant us relief.”","The mountain split further until their surroundings became clear to them. The third man said: “I once performed a righteous deed. I had two elderly parents and some sheep. I would feed and give drink to my parents before returning to my sheep. One day, rain detained me, and I could not leave until evening. I returned to my family, took my milking vessel, and milked while my sheep were standing. I went to my parents and found them asleep. It was difficult for me to wake them, and it was also difficult for me to leave my sheep. I remained seated with the vessel in my hand until morning awakened them.” Al-Nuʿmān said: “It is as though I can still hear these words directly from the Messenger of Allah ﷺ.” The Prophet ﷺ said: “The mountain formed an opening, Allah granted them relief, and they emerged.”"]},"buhuth":{"en":["The phrase stating that the Messenger of Allah ﷺ mentioned al-Raqīm does not refer to the Companions of the Cave mentioned in Allah’s words:","“Or did you think that the Companions of the Cave and al-Raqīm were among Our wondrous signs?”","[Sūrat al-Kahf 18:9]","In that verse, al-Raqīm refers to a stone tablet upon which the story of the Companions of the Cave was written and which was then placed at the entrance of their cave. In this hadith, however, al-Raqīm is the name of the valley in which the cave was located."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (18417)، والطبراني في الدعاء (190)."},{"num":10972,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، قَالَ : قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ ثَلاثَةَ نَفَرٍ انْطَلَقُوا إِلَى حَاجَةٍ لَهُمْ فآووا إِلَى جَبَلٍ فَسَقَطَ عَلَيْهِمْ فَقَالُوا : يَا هَؤُلاءِ يَعْنِي بَعْضُهُمْ لِبَعْضٍ تَفَكَّرُوا فِي أَحْسَنِ أَعْمَالِكُمْ فَادْعُوا اللَّهَ بِهَا لَعَلَّ اللَّهَ أن يُفَرِّجُ عَنْكُمْ، فَقَالَ أَحَدُهُمْ: اللَّهُمَّ إِنَّهُ كَانَتْ لَهُ امرأة صَدِيقَةٌ أُطِيلُ الاخْتِلافَ إِلَيْهَا حَتَّى أدركت حَاجَتِي مِنْهَا، فقالت: أُذَكِّرُكَ الله أن تركب مني مَا حَرَّمَ اللَّهُ عليك فَقُلْتُ: أَنَا أَحَقُّ أَنْ أَخَافُ فَتَرَكْتُهَا مِنْ مَخَافَتِكَ وَابْتِغَاءَ مَرْضَاتِكَ، فَإِنْ كُنْتَ تَعْلَمُ ذَلِكَ فَفَرِّجْ عَنَّا قَالَ: فَانْصَدَعَ الْجَبَلُ عَنْهُمْ حَتَّى طَمِعُوا فِي الْخُرُوجِ وَلَمْ يَسْتَطِيعُوا الْخُرُوجَ. وَقَالَ الثَّانِي : اللَّهُمَّ إِنَّهُ كَانَ أُجَرَاءُ يَعْمَلُونَ عَمَلا أَحْسِبُهُ قَالَ: فَأَخَذَ كُلُّ وَاحِدٍ مِنْهُمْ أَجْرَهُ، وَتَرَكَ وَاحِدٌ أَجْرَهُ، وَزَعِمَ أَنَّ أَجْرَهُ أَكْثَرُ مِنْ أُجُورِ أَصْحَابِهِ فَعَزَلْتُ أَجْرَهُ مِنْ مَالِي حَتَّى كَانَ خَيْرًا وَمَاشِيَةً فَأَتَانِي بَعْدَ مَا افْتَقَرَ وَكَبِرَ، فَقَالَ: أُذَكِّرُكَ اللَّهَ فِي أجرتي فَإِنِّي أَحْوَجُ مَا كُنْتُ إِلَيْهِ فَانْطَلَقْتُ فَوْقَ بَيْتٍ فَأَرَيْتُهُ مَا أَنْمَى اللَّهُ مِنْ أَجِرِه فِي الْمَالِ، وَالْمَاشِيَةِ فِي الْغَائِطِ يَعْنِي فِي الصحاري فَقُلْتُ : هَذَا لَكَ فَقَالَ: لِمَ تَسْخَرُ بِي أَصْلَحَكَ اللَّهُ ؟ كُنْتُ أُرِيدُ عَلَى أَقَلِّ مِنْ هَذَا فَتَأْبَى عَلَيَّ، فَدَفَعْتُ إِلَيْهِ يَا رَبِّ مِنْ مَخَافَتِكَ وَابْتِغَاءِ مَرْضَاتِكَ فَإِنْ كُنْتَ تَعْلَمُ ذَلِكَ فَفَرِّجْ عَنَّا فَانْصَدَعَ الْجَبَلُ عَنْهُمْ وَلَمْ يَسْتَطِيعُوا أَنْ يَخْرُجُوا. وَقَالَ الثَّالِثُ: يَا رَبِّ إِنَّهُ كَانَ لِي أَبَوَانِ كَبِيرَانِ فَقِيرَانِ، لَيْسَ لَهُمَا خَادِمٌ وَلا رَاعٍ وَلا وَالٍ غَيْرِي، أرعي لَهُمَا بِالنَّهَارِ، وَآوِي إِلَيْهِمَا بِاللَّيْلِ، وَإِنَّ الْكَلَأ تَبَاعَدَ فَتَبَاعَدْتُ بِالْمَاشِيَةِ، فَأَتَيْتُهُمَا يَعْنِي لَيْلَةً بَعْدَ مَا ذَهَبَ مِنَ اللَّيْلِ، وناما فَحَلَبْتُ يَعْنِي فِي الإِنَاءِ، ثُمَّ جَلَسْتُ عِنْدَ رؤوسهما بِالإِنَاءِ كَرَاهِيَةَ أَنْ أُوقِظَهُمَا حَتَّى يَسْتَيْقِظَا مِنْ قِبَلِ أَنْفُسِهِمَا، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنِّي فَعَلْتُ ذَلِكَ، مِنْ مَخَافَتِكَ وَابْتِغَاءِ مَرْضَاتِكَ فَفَرِّجْ عَنَّا، فَانْصَدَعَ الْجَبَلُ وَخَرَجُوا."],"takhrij":"حسن: رواه البزار (906)، وأبو عوانة في مسنده (5582) كلاهما من طريق عبد الصمد بن النعمان قال: حدثنا حنش بن الحارث، عن أبيه، عن علي فذكره.","grade":"حسن","chapter_ar":"باب التوسل إلى اللّٰه تعالى بالأعمال الصالحة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār (906) and Abū ʿAwānah in his Musnad (5582).","chapter_en":"Seeking Nearness to Allah through Righteous Deeds","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في التوسل الشرعي في الدعاء","group_en":"Collection of Narrations Concerning Lawful Means of Seeking Nearness to Allah in Supplication","part_no":54,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["ʿAlī narrated that the Messenger of Allah ﷺ said: “Three men set out to fulfill a need of theirs and took shelter in a mountain cave, but a rock fell over them. They said to one another: ‘Consider the best deeds you have performed and call upon Allah through them. Perhaps Allah will grant you relief.’” The first man said: “O Allah, I had a woman with whom I maintained a close relationship and whom I visited repeatedly. When I was finally able to fulfill my desire with her, she said: ‘I remind you of Allah—do not take from me what Allah has forbidden you.’ I said to myself: ‘I have greater reason to fear Him.’ I therefore left her out of fear of You and in pursuit of Your pleasure. If You know that I did this for that reason, then grant us relief.” The mountain split open enough for them to hope that they might escape, but they were still unable to leave. The second man said: “O Allah, I had laborers working for me. Each of them took his wages except one man, who left his wages behind, claiming that his pay should have been greater than that of his companions. I set aside his wages from my own wealth and invested them until they became horses and livestock. He later came to me after becoming poor and elderly and said: ‘I remind you of Allah regarding my wages, for I have never been in greater need of them.’ I took him to an elevated place and showed him what Allah had caused his wages to grow into—wealth and livestock spread throughout the open land. I said: ‘All of this belongs to you.’ He replied: ‘May Allah rectify you! Are you mocking me? I once asked you for much less than this, but you refused me.’ I handed everything over to him, O Lord, out of fear of You and in pursuit of Your pleasure. If You know that I did this for that reason, then grant us relief.” The mountain split further, but they were still unable to escape. The third man said: “O Lord, I had two elderly and poor parents. They had no servant, shepherd, or caretaker other than me. I would tend their animals during the day and return to them at night. One day, the pasture was far away, so I traveled a great distance with the livestock. I did not return until part of the night had passed, and I found them asleep. I milked into a vessel and then sat beside their heads holding it, disliking to awaken them, until they awoke on their own. O Allah, if You know that I did this out of fear of You and in pursuit of Your pleasure, then grant us relief.” The mountain split open, and they emerged."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (906)، وأبو عوانة في مسنده (5582)."},{"num":10973,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ قَالَ: أَصَابَتِ النَّاسَ سَنَةٌ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَبَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ عَلَى الْمِنْبَرِ يَوْمَ الْجُمُعَةِ، قَامَ أَعْرَابِيٌّ فَقَالَ: يَا رَسُولَ اللَّهِ، هَلَكَ الْمَالُ، وَجَاعَ الْعِيَالُ، فَادْعُ اللَّهَ لَنَا أَنْ يَسْقِيَنَا. قَالَ: فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ، وَمَا فِي السَّمَاءِ قَزَعَةٌ، قَالَ: فَثَارَ سَحَابٌ أَمْثَالُ الْجِبَالِ، ثُمَّ لَمْ يَنْزِلْ عَنْ مِنْبَرِهِ حَتَّى رَأَيْتُ الْمَطَرَ يَتَحَادَرُ عَلَى لِحْيَتِهِ، قَالَ: فَمُطِرْنَا يَوْمَنَا ذَلِكَ، وَفِي الْغَدِ، وَمِنْ بَعْدِ الْغَدِ، وَالَّذِي يَلِيهِ إِلَى الْجُمُعَةِ الأُخْرَى، فَقَامَ ذَلِكَ الأَعْرَابِيُّ، أَوْ رَجُلٌ غَيْرُهُ، فَقَالَ: يَا رَسُولَ اللَّهِ، تَهَدَّمَ الْبِنَاءُ، وَغَرِقَ الْمَالُ، فَادْعُ اللَّهَ لَنَا. فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ وَقَالَ: اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا. قَالَ فَمَا جَعَلَ يُشِيرُ بِيَدِهِ إِلَى نَاحِيَةٍ مِنَ السَّمَاءِ إِلاَّ تَفَرَّجَتْ، حَتَّى صَارَتِ الْمَدِينَةُ فِي مِثْلِ الْجَوْبَةِ، حَتَّى سَالَ الْوَادِي ـ وَادِي قَنَاةَ ـ شَهْرًا. قَالَ: فَلَمْ يَجِئْ أَحَدٌ مِنْ نَاحِيَةٍ إِلاَّ حَدَّثَ بِالْجَوْدِ."],"takhrij":"متفق عليه: رواه البخاري في الاستسقاء (1033)، ومسلم في الاستسقاء (897/9) كلاهما من طريق الأوزاعي قال: حدثنا إسحاق بن عبدالله بن أبي طلحة الأنصاري، قال: حدثني أنس بن مالك فذكره واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب التوسل إلى اللّٰه تعالى بدعاء الرجل الصالح الحي","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1033) and Muslim (897/9).","chapter_en":"Seeking Nearness to Allah through the Supplication of a Living Righteous Person","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في التوسل الشرعي في الدعاء","group_en":"Collection of Narrations Concerning Lawful Means of Seeking Nearness to Allah in Supplication","part_no":54,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Mālik narrated: The people were afflicted by drought during the time of the Messenger of Allah ﷺ. While the Messenger of Allah ﷺ was delivering the Friday sermon from the pulpit, a Bedouin stood and said: “O Messenger of Allah, the wealth has been destroyed and the families are hungry. Supplicate to Allah to send us rain.” The Messenger of Allah ﷺ raised his hands, although there was not even a small cloud in the sky. Clouds then arose like mountains, and before he had descended from the pulpit, I saw the rain flowing down his beard. It continued raining that day, the following day, the day after that, and the day after that, until the next Friday. The same Bedouin—or another man—stood and said: “O Messenger of Allah, the buildings have collapsed and the wealth has been flooded. Supplicate to Allah for us.” The Messenger of Allah ﷺ raised his hands and said: “O Allah, let it fall around us and not upon us.” Whenever he pointed toward any part of the sky, the clouds dispersed from that area, until Madinah became like an open circular space surrounded by clouds. The valley of Qanāh continued flowing for a month. No one arrived from any direction except that he reported abundant rainfall."]}},"tuhfa":{},"full":1,"rep":[2965,9700],"tks":"متفق عليه: رواه البخاري (1033)، ومسلم (897/9)."},{"num":10974,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ كَانَ إِذَا قَحَطُوا اسْتَسْقَى بِالْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ فَقَالَ اللَّهُمَّ إِنَّا كُنَّا نَتَوَسَّلُ إِلَيْكَ بِنَبِيِّنَا فَتَسْقِينَا، وَإِنَّا نَتَوَسَّلُ إِلَيْكَ بِعَمِّ نَبِيِّنَا فَاسْقِنَا. قَالَ: فَيُسْقَوْنَ."],"takhrij":"صحيح: رواه البخاري في الاستسقاء (1010) عن الحسن بن محمد، حدثنا محمد بن عبد الله الأنصاري، حدثني أبي عبد الله بن المثنى، عن ثمامة بن عبد الله بن أنس، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب التوسل إلى اللّٰه تعالى بدعاء الرجل الصالح الحي","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1010).","chapter_en":"Seeking Nearness to Allah through the Supplication of a Living Righteous Person","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في التوسل الشرعي في الدعاء","group_en":"Collection of Narrations Concerning Lawful Means of Seeking Nearness to Allah in Supplication","part_no":54,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Anas narrated: Whenever the people suffered drought, ʿUmar ibn al-Khaṭṭāb would seek rain through the supplication of al-ʿAbbās ibn ʿAbd al-Muṭṭalib. He would say: “O Allah, we formerly sought nearness to You through our Prophet, and You gave us rain. Now we seek nearness to You through the uncle of our Prophet, so grant us rain.” Anas said: “They would then be given rain.”"]},"buhuth":{"en":["The words “We formerly sought nearness to You through our Prophet” mean: through the supplication of our Prophet.","This practice continued afterward as well. Ibn Ḥajar stated in the biography of Yazīd ibn al-Aswad al-Jurashī in al-Iṣābah (9434, third section):","“Abū Zurʿah al-Dimashqī and Yaʿqūb ibn Sufyān narrated in their respective histories, through an authentic chain from Sulaym ibn ʿĀmir, that when the people of Damascus suffered drought, Muʿāwiyah went out to seek rain through the supplication of Yazīd ibn al-Aswad, and they were given rain.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2970],"tks":"صحيح: رواه البخاري (1010)."},{"num":10975,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ حُنَيْفٍ، أَنَّ رَجُلاً، ضَرِيرَ الْبَصَرِ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: ادْعُ اللَّهَ أَنْ يُعَافِيَنِي. قَالَ: إِنْ شِئْتَ دَعَوْتُ وَإِنْ شِئْتَ صَبَرْتَ فَهُوَ خَيْرٌ لَكَ. قَالَ فَادْعُهُ. قَالَ فَأَمَرَهُ أَنْ يَتَوَضَّأَ فَيُحْسِنَ وُضُوءَهُ وَيَدْعُوَ بِهَذَا الدُّعَاءِ: اللَّهُمَّ إِنِّي أَسْأَلُكَ وَأَتَوَجَّهُ إِلَيْكَ بِنَبِيِّكَ مُحَمَّدٍ نَبِيِّ الرَّحْمَةِ، إِنِّي تَوَجَّهْتُ بِكَ إِلَى رَبِّي فِي حَاجَتِي هَذِهِ لِتُقْضَى لِي، اللَّهُمَّ فَشَفِّعْهُ فِيَّ."],"takhrij":"صحيح: رواه الترمذي (3578)، والنسائي في عمل اليوم والليلة (659)، وابن ماجه (1385)، وأحمد (17240)، وصحّحه ابن خزيمة (1219)، والحاكم (1909) كلهم من طريق شعبة، عن أبي جعفر المدني، عن عمارة بن خزيمة بن ثابت، عن عثمان بن حنيف فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب التوسل إلى اللّٰه تعالى بدعاء الرجل الصالح الحي","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (3578), al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (659), Ibn Mājah (1385), and Aḥmad (17240).","chapter_en":"Seeking Nearness to Allah through the Supplication of a Living Righteous Person","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في التوسل الشرعي في الدعاء","group_en":"Collection of Narrations Concerning Lawful Means of Seeking Nearness to Allah in Supplication","part_no":54,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["ʿUthmān ibn Ḥunayf narrated: A blind man came to the Prophet ﷺ and said: “Supplicate to Allah to restore my well-being.” He replied: “If you wish, I will supplicate for you; and if you wish, you may delay that, and it will be better.” The man said: “Supplicate to Him.” The Prophet ﷺ instructed him to perform ablution thoroughly, pray two units of prayer, and then say: “O Allah, I ask You and turn toward You through Your Prophet Muḥammad, the Prophet of mercy. O Muḥammad, I have turned through you to my Lord concerning this need of mine, so that it may be fulfilled for me. O Allah, accept his intercession concerning me.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3009],"tks":"صحيح: رواه الترمذي (3578)، والنسائي في عمل اليوم والليلة (659)، وابن ماجه (1385)، وأحمد (17240)."},{"num":10976,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ الْخَلاَءَ قَالَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (142) عن آدم قال: حدثنا شعبة، عن عبد العزيز بن صهيب قال: سمعت أنسا يقول..فذكره.","grade":"متفق عليه","chapter_ar":"باب ما يقول إذا أراد دخول الخلاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (142) and Muslim (375).","chapter_en":"What One Should Say When Intending to Enter the Lavatory","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الطهارة","group_en":"Collection of Narrations Concerning Supplications of Purification","part_no":54,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Anas narrated: When the Prophet ﷺ entered the lavatory, he would say: “O Allah, I seek refuge in You from the male and female devils.”"]},"buhuth":{"en":["Another narration states:","“When he intended to enter.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1350],"tks":"متفق عليه: رواه البخاري (142)، ومسلم (375). وفي رواية: ((إذا أراد أن يدخل))."},{"num":10977,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ أَرْقَمَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ هَذِهِ الْحُشُوشَ مُحْتَضَرَةٌ، فَإِذَا أَتَى أَحَدُكُمُ الْخَلاَءَ فَلْيَقُلْ: أَعُوذُ بِاللَّهِ مِنَ الْخُبُثِ وَالْخَبَائِثِ."],"takhrij":"صحيح: رواه أبو داود (6) وابن ماجه (296) وصحّحه ابن خزيمة (69) وابن حبان (1408)، والحاكم (668) كلُّهم من طريق شعبة، عن قتادة، عن النضر بن أنس، عن زيد بن أرقم، فذكر مثله.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما يقول إذا أراد دخول الخلاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (6) and Ibn Mājah (296), and authenticated by Ibn Khuzaymah (69), Ibn Ḥibbān (1408), and al-Ḥākim (668).","chapter_en":"What One Should Say When Intending to Enter the Lavatory","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الطهارة","group_en":"Collection of Narrations Concerning Supplications of Purification","part_no":54,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Zayd ibn Arqam narrated that the Messenger of Allah ﷺ said: “These lavatories are attended by devils. Therefore, when one of you goes to the lavatory, let him say: ‘I seek refuge in Allah from the male and female devils.’”"]},"buhuth":{"en":["The word al-ḥushūsh refers to lavatories. The original meaning of al-ḥushsh is a dense cluster of palm trees. Before lavatories were built inside houses, people would go to such places to relieve themselves.","The word muḥtaḍarah means that devils are present there. This explanation was given by al-Khaṭṭābī."]}},"tuhfa":{},"full":1,"dr":1,"rep":[1351,8228],"tks":"صحيح: رواه أبو داود (6)، وابن ماجه (296)، وصححه ابن خزيمة (69)، وابن حبان (1408)، والحاكم (668)."},{"num":10978,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: إن النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَرَجَ مِنَ الْغَائِطِ قَالَ: غُفْرَانَكَ."],"takhrij":"حسن: رواه أبو داود (30)، والترمذي (7)، وابن ماجه (300)، وصحّحه ابن خزيمة (90)، وابن حبان (1444)، والحاكم (562) كلهم من طريق إسرائيل بن يونس، عن يوسف بن أبي بردة، عن أبيه، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب ما يقول إذا خرج من الخلاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (30), al-Tirmidhī (7), and Ibn Mājah (300), and authenticated by Ibn Khuzaymah (90) and Ibn Ḥibbān (1444).","chapter_en":"What One Should Say upon Leaving the Lavatory","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الطهارة","group_en":"Collection of Narrations Concerning Supplications of Purification","part_no":54,"group_no":7,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah narrated: When the Prophet ﷺ left the place of relieving himself, he would say: “I seek Your forgiveness.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1352],"tks":"حسن: رواه أبو داود (30)، والترمذي (7)، وابن ماجه (300)، وصححه ابن خزيمة (90)، وابن حبان (1444)."},{"num":10979,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: طَلَبَ بَعْضُ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَضُوءًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلْ مَعَ أَحَدٍ مِنْكُمْ مَاءٌ. فَوَضَعَ يَدَهُ فِي الْمَاءِ وَيَقُولُ: تَوَضَّئُوا بِسْمِ اللَّهِ. فَرَأَيْتُ الْمَاءَ يَخْرُجُ مِنْ بَيْنِ أَصَابِعِهِ حَتَّى تَوَضَّئُوا مِنْ عِنْدِ آخِرِهِمْ. قَالَ ثَابِتٌ: قُلْتُ لأَنَسٍ: كَمْ تُرَاهُمْ؟ قَالَ: نَحْوًا مِنْ سَبْعِينَ."],"takhrij":"صحيح: رواه النسائي (78) وأحمد (12694) وصحّحه ابن خزيمة (144) كلهم من حديث عبدالرزاق -وهو في مصنفه (20535)- قال: حدَّثنا معمر، عن ثابت وقتادة، عن أنس فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما يقول إذا أراد أن يتوضأ","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (78) and Aḥmad (12694), and authenticated by Ibn Khuzaymah (144).","chapter_en":"What One Should Say When Intending to Perform Ablution","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الطهارة","group_en":"Collection of Narrations Concerning Supplications of Purification","part_no":54,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Anas narrated: Some of the Companions of the Prophet ﷺ sought water for ablution. The Messenger of Allah ﷺ asked: “Does anyone among you have water?” He placed his hand into the water and said: “Perform ablution in the name of Allah.” I saw water flowing from between his fingers until every one of them had performed ablution. Thābit said: I asked Anas: “Approximately how many were they?” He replied: “About seventy.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1543],"tks":"صحيح: رواه النسائي (78)، وأحمد (12694)، وصححه ابن خزيمة (144)."},{"num":10980,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ قَالَ:  كَانَتْ عَلَيْنَا رِعَايَةُ الْإِبِلِ، فَجَاءَتْ نَوْبَتِي، فَرَوَّحْتُهَا بِعَشِيٍّ، فَأَدْرَكْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمًا يُحَدِّثُ النَّاسَ، فَأَدْرَكْتُ مِنْ قَوْلِهِ: مَا مِنْ مُسْلِمٍ يَتَوَضَّأُ فَيُحْسِنُ وُضُوءَهُ، ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ مُقْبِلٌ عَلَيْهِمَا بِقَلْبِهِ وَوَجْهِهِ إِلَّا وَجَبَتْ لَهُ الْجَنَّةُ، قَالَ: فَقُلْتُ: مَا أَجْوَدَ هَذِهِ، فَإِذَا قَائِلٌ بَيْنَ يَدَيَّ يَقُولُ: الَّتِي قَبْلَهَا أَجْوَدُ، فَنَظَرْتُ فَإِذَا عُمَرُ! قَالَ: إِنِّي قَدْ رَأَيْتُكَ جِئْتَ آنِفًا، قَالَ: مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ فَيُبْلِغُ - أَوْ فَيُسْبِغُ - الْوَُضُوءَ، ثُمَّ يَقُولُ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا عَبْدُ اللَّهِ وَرَسُولُهُ، إِلَّا فُتِحَتْ لَهُ أَبْوَابُ الْجَنَّةِ الثَّمَانِيَةُ يَدْخُلُ مِنْ أَيِّهَا شَاءَ.","وفي رواية قال: أشهد أن لا إله إلاَّ الله وحده لا شريك له، وأشهد أن محمداً عبده ورسوله.وزاد في رواية بعد التشهد: اللهمّ اجعلني من التّوابين، واجعلني من المتطهّرين."],"takhrij":"صحيح: رواه مسلم في الطهارة (234)، عن محمد بن حاتم بن ميمون، ثنا ابن مهدي، ثنا معاوية بن صالح، عن ربيعة يعني بن يزيد، عن أبي إدريس الخولاني، عن عقبة بن عامر (ح) وحدثني أبو عثمان، عن جبير بن نفير، عن عقبة بن عامر فذكره.","grade":"صحيح","chapter_ar":"باب ما يقال بعد الفراغ من الوضوء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (234).","chapter_en":"What Should Be Said after Completing Ablution","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الطهارة","group_en":"Collection of Narrations Concerning Supplications of Purification","part_no":54,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir narrated: We used to take turns tending the camels. When my turn came, I brought them back in the evening and found the Messenger of Allah ﷺ standing and speaking to the people. I heard him say: “No Muslim performs ablution and perfects it, then stands and prays two units, devoting his heart and face to them, except that Paradise becomes obligatory for him.” I said: “How excellent this is!” A person in front of me said: “The statement before it was even better.” I looked and saw that it was ʿUmar. He said: “I saw that you arrived only recently.” The Prophet ﷺ had said: “No one performs ablution and completes—or perfects—his ablution and then says, ‘I testify that there is no deity worthy of worship except Allah and that Muḥammad is His servant and Messenger,’ except that the eight gates of Paradise are opened for him, and he may enter through whichever of them he wishes.” Another narration states: “I testify that there is no deity worthy of worship except Allah alone, without partner, and I testify that Muḥammad is His servant and Messenger.”"]},"buhuth":{"en":["Al-Tirmidhī added after the testimony of faith:","“O Allah, make me among those who constantly repent and make me among those who purify themselves.”","Its chain of transmission is authentic."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (234)."},{"num":10981,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا سَمِعْتُمُ النِّدَاءَ فَقُولُوا مِثْلَ مَا يَقُولُ الْمُؤَذِّنُ."],"takhrij":"متفق عليه: رواه مالك في الصلاة (2) عن ابن شهاب، عن عطاء بن يزيد الليثي، عن أبي سعيد الخدري فذكره.ورواه البخاري في الأذان (611)، ومسلم في الصلاة (383) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب ما يقول إذا سمع النداء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (2), al-Bukhārī (611), and Muslim (383).","chapter_en":"What One Should Say upon Hearing the Call to Prayer","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “When you hear the call to prayer, repeat what the caller to prayer says.”"]}},"tuhfa":{},"full":1,"rep":[1896],"tks":"متفق عليه: رواه مالك (2)، والبخاري (611)، ومسلم (383)."},{"num":10982,"demo":false,"sanad":"","matn":["عن عُمَرَ بن الْخَطَّابِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِذَا قَالَ الْمُؤَذِّنُ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، فَقَالَ أَحَدُكُمُ: اللهُ أَكْبَرُ اللَّهُ أَكْبَرُ. ثُمَّ قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ. ثُمَّ قَالَ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، قَالَ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ. ثُمَّ قَالَ: حَيَّ عَلَى الصَّلَاةِ، قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ. ثُمَّ قَالَ: حَيَّ عَلَى الْفَلَاحِ، قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ. ثُمَّ قَالَ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، قَالَ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ. ثُمَّ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، قَالَ: لَا إِلَهَ إِلَّا اللَّهُ مِنْ قَلْبِهِ دَخَلَ الْجَنَّةَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (385) عن إسحاق بن منصور، أخبرنا أبو جعفر محمد بن جَهْضَم الثقفي، حدثنا إسماعيل بن جعفر، عن عُمارة بن غَزية، عن خُبيب بن عبدالرحمن بن أساف، عن حفص بن عاصم بن عمر بن الخطاب، عن أبيه، عن جده قال:فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا سمع النداء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (385).","chapter_en":"What One Should Say upon Hearing the Call to Prayer","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb narrated that the Messenger of Allah ﷺ said: “When the caller to prayer says, ‘Allah is the Greatest, Allah is the Greatest,’ and one of you says, ‘Allah is the Greatest, Allah is the Greatest’; then he says, ‘I testify that there is no deity worthy of worship except Allah,’ and one says, ‘I testify that there is no deity worthy of worship except Allah’; then he says, ‘I testify that Muḥammad is the Messenger of Allah,’ and one says, ‘I testify that Muḥammad is the Messenger of Allah’; then he says, ‘Come to prayer,’ and one says, ‘There is no power and no strength except through Allah’; then he says, ‘Come to success,’ and one says, ‘There is no power and no strength except through Allah’; then he says, ‘Allah is the Greatest, Allah is the Greatest,’ and one says, ‘Allah is the Greatest, Allah is the Greatest’; then he says, ‘There is no deity worthy of worship except Allah,’ and one says sincerely from his heart, ‘There is no deity worthy of worship except Allah,’ he will enter Paradise.”"]}},"tuhfa":{},"full":1,"rep":[1898,1908],"tks":"صحيح: رواه مسلم (385)."},{"num":10983,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ، قَالَ: سَمِعْتُ مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ،، وَهُوَ جَالِسٌ عَلَى الْمِنْبَرِ، أَذَّنَ الْمُؤَذِّنُ قَالَ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ. قَالَ مُعَاوِيَةُ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ. قَالَ: أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ. فَقَالَ مُعَاوِيَةُ: وَأَنَا. فَقَالَ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ. فَقَالَ مُعَاوِيَةُ: وَأَنَا. فَلَمَّا أَنْ قَضَى التَّأْذِينَ قَالَ: يَا أَيُّهَا النَّاسُ، إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى هَذَا الْمَجْلِسِ حِينَ أَذَّنَ الْمُؤَذِّنُ يَقُولُ مَا سَمِعْتُمْ مِنِّي مِنْ مَقَالَتِي."],"takhrij":"صحيح: رواه البخاري في الجمعة (914) عن ابن مقاتل: قال: أخبرنا عبدالله (وهو: ابن المبارك) قال: أخبرنا أبو بكر بن عثمان بن سهل بن حُنيف، عن أبي أمامة بن سهل بن حُنَيف فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما يقول إذا سمع النداء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (914).","chapter_en":"What One Should Say upon Hearing the Call to Prayer","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Abū Umāmah ibn Sahl ibn Ḥunayf said: I heard Muʿāwiyah ibn Abī Sufyān while he was seated upon the pulpit. When the caller to prayer said: “Allah is the Greatest, Allah is the Greatest,” Muʿāwiyah said: “Allah is the Greatest, Allah is the Greatest.” When he said: “I testify that there is no deity worthy of worship except Allah,” Muʿāwiyah said: “And I testify to that.” When he said: “I testify that Muḥammad is the Messenger of Allah,” Muʿāwiyah said: “And I testify to that.” When the caller had completed the call to prayer, Muʿāwiyah said: “O people, I heard the Messenger of Allah ﷺ, while seated in this very place, say what you heard me say when the caller to prayer made the call.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1902,3310],"tks":"صحيح: رواه البخاري (914)."},{"num":10984,"demo":false,"sanad":"","matn":["عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  إِذَا سَمِعْتُمُ الْمُؤَذِّنَ فَقُولُوا مِثْلَ مَا يَقُولُ، ثُمَّ صَلُّوا عَلَيَّ؛ فَإِنَّهُ مَنْ صَلَّى عَلَيَّ صَلَاةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا، ثُمَّ سَلُوا اللَّهَ لِي الْوَسِيلَةَ؛ فَإِنَّهَا مَنْزِلَةٌ فِي الْجَنَّةِ لَا تَنْبَغِي إِلَّا لِعَبْدٍ مِنْ عِبَادِ اللَّهِ، وَأَرْجُو أَنْ أَكُونَ أَنَا هُوَ. فَمَنْ سَأَلَ لِي الْوَسِيلَةَ حَلَّتْ لَهُ الشَّفَاعَةُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (384) من طريق كعب بن علقمة، عن عبدالرحمن بن جبير، عن عبدالله بن عمرو بن العاص فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا سمع النداء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (384).","chapter_en":"What One Should Say upon Hearing the Call to Prayer","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated that he heard the Prophet ﷺ say: “When you hear the caller to prayer, repeat what he says. Then send blessings upon me, for whoever sends one blessing upon me, Allah will send ten blessings upon him because of it. Then ask Allah to grant me al-Wasīlah, for it is a rank in Paradise suitable for only one servant from among the servants of Allah, and I hope that I will be that servant. Whoever asks Allah to grant me al-Wasīlah will become entitled to my intercession.”"]}},"tuhfa":{},"full":1,"rep":[10866],"tks":"صحيح: رواه مسلم (384)."},{"num":10985,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ قَالَ حِينَ يَسْمَعُ النِّدَاءَ: اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلاَةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ، حَلَّتْ لَهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه البخاري في الأذان (614) عن علي بن عياش، ثنا شعيب بن أبي حمزة، عن محمد بن المنكدر، عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا سمع النداء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (614).","chapter_en":"What One Should Say upon Hearing the Call to Prayer","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that the Messenger of Allah ﷺ said: “Whoever says upon hearing the call to prayer, ‘O Allah, Lord of this perfect call and the prayer about to be established, grant Muḥammad al-Wasīlah and excellence, and raise him to the Praised Station that You promised him,’ will become entitled to my intercession on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[913,1904],"tks":"صحيح: رواه البخاري (614)."},{"num":10986,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْوَسِيلَةُ دَرَجَةٌ عِنْدَ اللَّهِ، لَيْسَ فَوْقَهَا دَرَجَةٌ، فسلو اللهَ أَنْ يُؤْتِيَنِي الْوَسِيلَةَ."],"takhrij":"حسن: رواه الإمام أحمد (11783) عن موسى بن داود، حدثنا ابنُ لهيعة، عن موسى بن وردان، قال: سمعتُ أبا سعيد الخدري يقول: فذكره.","grade":"حسن","chapter_ar":"باب ما يقول إذا سمع النداء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Aḥmad (11783) and al-Ṭabarānī in al-Muʿjam al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (641).","chapter_en":"What One Should Say upon Hearing the Call to Prayer","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “Al-Wasīlah is a rank with Allah above which there is no rank. Therefore, ask Allah to grant me al-Wasīlah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (11783)، والطبراني في الأوسط، كما في مجمع البحرين (641)."},{"num":10987,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ:  مَنْ قَالَ حِينَ يَسْمَعُ الْمُؤَذِّنَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، رَضِيتُ بِاللهِ رَبًّا، وَبِمُحَمَّدٍ رَسُولًا، وَبِالْإِسْلَامِ دِينًا غُفِرَ لَهُ ذَنْبُهُ.","وَفِي رِوَايَةٍ: مَنْ قَالَ حِينَ يَسْمَعُ الْمُؤَذِّنُ: وَأَنَا أَشْهَدُ..."],"takhrij":"صحيح: رواه مسلم في الصلاة (386) من طريق الليث، عن الحُكيم بن عبدالله، عن عامر بن سعد بن أبي وقَّاص، عن سعد بن أبي وقَّاص، فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا سمع النداء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (386).","chapter_en":"What One Should Say upon Hearing the Call to Prayer","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ narrated that the Messenger of Allah ﷺ said: “Whoever says upon hearing the caller to prayer, ‘I testify that there is no deity worthy of worship except Allah alone, without partner, and that Muḥammad is His servant and Messenger. I am pleased with Allah as my Lord, with Muḥammad as Messenger, and with Islam as my religion,’ his sin will be forgiven.” Another narration states: “Whoever says upon hearing the caller to prayer: ‘And I testify…’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (386)."},{"num":10988,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عَبَّاسٍ أَنَّهُ رَقَدَ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاسْتَيْقَظَ فَتَسَوَّكَ وَتَوَضَّأَ وَهُوَ يَقُولُ: إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِأُولِي الْأَلْبَابِ [آل عِمْرَانَ :190 ] فَقَرَأَ هَؤُلَاءِ الْآيَاتِ، حَتَّى خَتَمَ السُّورَةَ، ثُمَّ قَامَ، فَصَلَّى رَكْعَتَيْنِ، فَأَطَالَ فِيهِمَا الْقِيَامَ وَالرُّكُوعَ وَالسُّجُودَ، ثُمَّ انْصَرَفَ، فَنَامَ حَتَّى نَفَخَ، ثُمَّ فَعَلَ ذَلِكَ ثَلَاثَ مَرَّاتٍ، سِتَّ رَكَعَاتٍ، كُلَّ ذَلِكَ يَسْتَاكُ وَيَتَوَضَّأُ وَيَقْرَأُ هَؤُلَاءِ الْآيَاتِ، ثُمَّ أَوْتَرَ بِثَلَاثٍ، فَأَذَّنَ الْمُؤَذِّنُ، فَخَرَجَ إِلَى الصَّلَاةِ وَهُوَ يَقُولُ: اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي لِسَانِي نُورًا، وَاجْعَلْ فِي سَمْعِي نُورًا، وَاجْعَلْ فِي بَصَرِي نُورًا، وَاجْعَلْ مِنْ خَلْفِي نُورًا، وَمِنْ أَمَامِي نُورًا، وَاجْعَلْ مِنْ فَوْقِي نُورًا، وَمِنْ تَحْتِي نُورًا، اللَّهُمَّ أَعْطِنِي نُورًا."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (763: 191) عن واصل بن عبدالأعلى، حدثنا محمد بن فضيل، عن حصين بن عبدالرحمن، عن حبيب بن أبي ثابت، عن محمد بن علي بن عبدالله بن عباس، عن أبيه، عن عبدالله بن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا توجه إلى المسجد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (763/191).","chapter_en":"What One Should Say When Going to the Mosque","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated that he spent the night with the Messenger of Allah ﷺ. The Prophet ﷺ awoke, cleaned his teeth with the tooth-stick, performed ablution, and recited: “Indeed, in the creation of the heavens and the earth and the alternation of night and day are signs for people of understanding.” [Sūrat Āl ʿImrān 3:190] He continued reciting these verses until he completed the sūrah. He then stood and prayed two units, prolonging the standing, bowing, and prostration. He then lay down and slept until the sound of his breathing could be heard. He repeated this three times, making a total of six units. Each time, he used the tooth-stick, performed ablution, and recited those verses. He then performed three units of Witr. When the caller to prayer made the call, he went out for the prayer while saying: “O Allah, place light within my heart and light upon my tongue. Place light within my hearing and light within my sight. Place light behind me and light before me. Place light above me and light beneath me. O Allah, grant me light.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (763: 191)."},{"num":10989,"demo":false,"sanad":"","matn":["عَنْ أَبِي حُمَيْدٍ، - أَوْ عَنْ أَبِي أُسَيْدٍ - قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِذَا دَخَلَ أَحَدُكُمُ الْمَسْجِدَ فَلْيَقُلِ: اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ، وَإِذَا خَرَجَ فَلْيَقُلِ: اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (713) عن يحيى بن يحيى، أخبرنا سليمان بن بلال، عن ربيعة بن أبي عبدالرحمن، عن عبد الملك بن سعيد، عن أبي حُميد، أو أبي أُسَيد فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا أراد الدخول في المسجد والخروج منه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (713).","chapter_en":"What One Should Say When Entering and Leaving the Mosque","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":3,"content":{"translation":{"en":["Abū Ḥumayd—or Abū Usayd—al-Anṣārī narrated that the Messenger of Allah ﷺ said: “When one of you enters the mosque, let him say: ‘O Allah, open for me the gates of Your mercy.’ When he leaves, let him say: ‘O Allah, I ask You from Your bounty.’”"]},"buhuth":{"en":["Abū Dāwūd also narrated it (465) and added at the beginning:","“When one of you enters the mosque, let him send greetings of peace upon the Prophet ﷺ and then say…”","This addition is authentic."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3038],"tks":"صحيح: رواه مسلم (713)."},{"num":10990,"demo":false,"sanad":"","matn":["عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ كَانَ إِذَا دَخَلَ الْمَسْجِدَ قَالَ: أَعُوذُ بِاللَّهِ الْعَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ. قَالَ: أَقَطُّ؟ قُلْتُ: نَعَمْ. قَالَ: فَإِذَا قَالَ ذَلِكَ: قَالَ الشَّيْطَانُ: حُفِظَ مِنِّي سَائِرَ الْيَوْمِ."],"takhrij":"حسن: رواه أبو داود (466) عن إسماعيل بن بشر بن منصور، حدثنا","grade":"حسن","chapter_ar":"باب ما يقول إذا أراد الدخول في المسجد والخروج منه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (466).","chapter_en":"What One Should Say When Entering and Leaving the Mosque","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated that when the Prophet ﷺ entered the mosque, he would say: “I seek refuge in Allah, the Magnificent, in His noble Face, and in His eternal authority from Satan, the accursed.” The narrator asked: “Is that all?” He replied: “Yes.” He then said: “When a person says that, Satan says: ‘He has been protected from me for the remainder of the day.’”"]},"buhuth":{"en":["The expression “Is that all?” means: “Only that?” The interrogative hamzah indicates that the narrator was asking whether this was the entirety of what had reached him. He was then informed of the additional virtue attached to the supplication."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3039],"tks":"حسن: رواه أبو داود (466)."},{"num":10991,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ  كَانَ إِذَا قَامَ إِلَى الصَّلَاةِ قَالَ: وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالْأَرْضَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ. ﴿إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا﴾ [سورة الأنعام: 162، 163] مِنَ الْمُسْلِمِينَ. اللَّهُمَّ أَنْتَ الْمَلِكُ، لَا إِلَهَ إِلَّا أَنْتَ، أَنْتَ رَبِّي وَأَنَا عَبْدُكَ، ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبِي جَمِيعًا، إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ. وَاهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ. لَبَّيْكَ وَسَعْدَيْكَ، وَالْخَيْرُ كُلُّهُ فِي يَدَيْكَ، وَالشَّرُّ لَيْسَ إِلَيْكَ. أَنَا بِكَ وَإِلَيْكَ. تَبَارَكْتَ وَتَعَالَيْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. وَإِذَا رَكَعَ قَالَ: اللَّهُمَّ لَكَ رَكَعْتُ وَبِكَ آمَنْتُ وَلَكَ أَسْلَمْتُ، خَشَعَ لَكَ سَمْعِي وَبَصَرِي وَمُخِّي وَعَظْمِي وَعَصَبِي. وَإِذَا رَفَعَ قَالَ: اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَاوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا بَيْنَهُمَا وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ. وَإِذَا سَجَدَ قَالَ: اللَّهُمَّ لَكَ سَجَدْتُ وَبِكَ آمَنْتُ وَلَكَ أَسْلَمْتُ. سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ وَصَوَّرَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ، تَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ. ثُمَّ يَكُونُ مِنْ آخِرِ مَا يَقُولُ بَيْنَ التَّشَهُّدِ وَالتَّسْلِيمِ: اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَسْرَفْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي. أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (771) عن محمد بن أبي بكر المقدمي، ثنا يوسف الماجشون، حدثني أبي، عن عبدالرحمن الأعرج، عن عبيدالله بن أبي رافع، عن علي بن أبي طالب، فذكره.","grade":"صحيح","chapter_ar":"باب ما يقال من أدعية الاستفتاح بعد تكبيرة الإحرام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (771).","chapter_en":"Opening Supplications Recited after the Opening Takbīr","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":4,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib narrated that when the Messenger of Allah ﷺ stood for prayer, he would say: “I have turned my face sincerely toward the One who originated the heavens and the earth, and I am not among the polytheists. Indeed, my prayer, my sacrifice, my life, and my death belong to Allah, Lord of the worlds. He has no partner. This is what I have been commanded, and I am among the Muslims. O Allah, You are the King. There is no deity worthy of worship except You. You are my Lord, and I am Your servant. I have wronged myself and acknowledged my sin, so forgive all my sins, for none forgives sins except You. Guide me to the best character, for none guides to the best of it except You. Turn its evil away from me, for none turns its evil away from me except You. I am ever obedient to You and ready to serve You. All goodness is in Your hands, and evil is not attributed to You. I exist through You and return to You. Blessed and Exalted are You. I seek Your forgiveness and repent to You.” When he bowed, he would say: “O Allah, for You I have bowed, in You I have believed, and to You I have submitted. My hearing, my sight, my mind, my bones, and my nerves have humbled themselves before You.” When he rose from bowing, he would say: “O Allah, our Lord, all praise belongs to You—enough to fill the heavens, enough to fill the earth, enough to fill what lies between them, and enough to fill whatever else You will.” When he prostrated, he would say: “O Allah, for You I have prostrated, in You I have believed, and to You I have submitted. My face has prostrated before the One who created and fashioned it and opened its hearing and sight. Blessed is Allah, the Best of creators.” Among the final things he would say between the tashahhud and the concluding greeting of peace was: “O Allah, forgive me for what I have sent ahead and what I have left behind, what I have concealed and what I have made public, what I have committed excessively, and what You know better about me than I do. You are the One who brings forward, and You are the One who delays. There is no deity worthy of worship except You.”"]},"buhuth":{"en":["Al-Tirmidhī also narrated it (3423) through ʿAlī ibn Abī Ṭālib from the Messenger of Allah ﷺ:","When he stood for an obligatory prayer, he would raise his hands level with his shoulders. He would also do this after completing his recitation when he intended to bow, and when he raised his head from bowing. He would not raise his hands during any part of the prayer while seated.","When he stood after two prostrations, he would similarly raise his hands and proclaim the takbīr. After the opening takbīr, he would say:","“I have turned my face toward the One who originated the heavens and the earth, sincerely, and I am not among the polytheists…”","The remainder is similar to Muslim’s narration.","Al-Tirmidhī then said:","“This is a good authentic hadith.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1949],"tks":"صحيح: رواه مسلم (771)."},{"num":10992,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ الله قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا اسْتَفْتَحَ الصَّلَاةَ كَبَّر،َ ثُمَّ ﴿قَالَ: إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لله رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا﴾ [سورة الأنعام: 162، 163] مِنْ المُسْلِمِينَ، اللَّهُمَّ اهْدِنِي لِأَحْسَنِ الْأَعْمَالِ وَأَحْسَنِ الْأَخْلَاقِ، لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَقِنِي سَيِّئَ الْأَعْمَالِ وَسَيِّئَ الْأَخْلَاقِ، لَا يَقِي سَيِّئَهَا إِلَّا أَنْتَ."],"takhrij":"صحيح: رواه النسائي (896) عن عمرو بن عثمان بن سعيد، قال: حدثنا شريح بن يزيد الحضرمي، قال: أخبرني شعيب بن أبي حمزة، قال: أخبرني محمد بن المنكدر، عن جابر بن عبد الله قال: فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما يقال من أدعية الاستفتاح بعد تكبيرة الإحرام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (896).","chapter_en":"Opening Supplications Recited after the Opening Takbīr","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":4,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: When the Prophet ﷺ began the prayer, he would proclaim the takbīr and then say: “Indeed, my prayer, my sacrifice, my life, and my death belong to Allah, Lord of the worlds. He has no partner. This is what I have been commanded, and I am among the Muslims. O Allah, guide me to the best deeds and the best character, for none guides to the best of them except You. Protect me from evil deeds and evil character, for none protects from their evil except You.”"]}},"tuhfa":{},"full":1,"rep":[1953],"tks":"صحيح: رواه النسائي (896)."},{"num":10993,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْكُتُ بَيْنَ التَّكْبِيرِ وَبَيْنَ الْقِرَاءَةِ إِسْكَاتَةً ـ قَالَ أَحْسِبُهُ قَالَ: هُنَيَّةً ـ فَقُلْتُ: بِأَبِي وَأُمِّي يَا رَسُولَ اللَّهِ، إِسْكَاتُكَ بَيْنَ التَّكْبِيرِ وَالْقِرَاءَةِ مَا تَقُولُ؟ قَالَ: أَقُولُ: اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَاىَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنَ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْ خَطَايَاىَ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (744)، ومسلم في المساجد (598) كلاهما من طريق عبد الواحد بن زياد، قال: حدثنا عُمارة بن القَعْقاع، قال: حدثنا أبو زرعة، قال: حدثنا أبو هريرة، فذكر الحديث، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما يقال من أدعية الاستفتاح بعد تكبيرة الإحرام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (744) and Muslim (598).","chapter_en":"Opening Supplications Recited after the Opening Takbīr","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated: The Messenger of Allah ﷺ would remain silent for a brief period between the opening takbīr and the recitation. The narrator said: “I think he described it as a short pause.” I asked: “May my father and mother be sacrificed for you, O Messenger of Allah. What do you say during your silence between the takbīr and the recitation?” He replied: “I say: ‘O Allah, distance me from my sins as You have distanced the east from the west. O Allah, purify me from sins as a white garment is purified from filth. O Allah, wash away my sins with water, snow, and hail.’”"]}},"tuhfa":{},"full":1,"rep":[1947],"tks":"متفق عليه: رواه البخاري (744)، ومسلم (598)."},{"num":10994,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ  أَنَّ رَجُلًا جَاءَ فَدَخَلَ الصَّفَّ، وَقَدْ حَفَزَهُ النَّفَسُ فَقَالَ: الْحَمْدُ لِلهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ. فَلَمَّا قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاتَهُ قَالَ: أَيُّكُمُ الْمُتَكَلِّمُ بِالْكَلِمَاتِ؟ فَأَرَمَّ الْقَوْمُ، فَقَالَ: أَيُّكُمُ الْمُتَكَلِّمُ بِهَا؟ فَإِنَّهُ لَمْ يَقُلْ بَأْسًا فَقَالَ رَجُلٌ: جِئْتُ وَقَدْ حَفَزَنِي النَّفَسُ فَقُلْتُهَا، فَقَالَ: لَقَدْ رَأَيْتُ اثْنَيْ عَشَرَ مَلَكًا يَبْتَدِرُونَهَا، أَيُّهُمْ يَرْفَعُهَا."],"takhrij":"صحيح: رواه مسلم في المساجد (600) عن زهير بن حرب، حدثنا عفان، حدثنا حماد، أخبرنا قتادة وثابت وحميد، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ما يقال من أدعية الاستفتاح بعد تكبيرة الإحرام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (600).","chapter_en":"Opening Supplications Recited after the Opening Takbīr","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":4,"content":{"translation":{"en":["Anas narrated: A man came and joined the row while he was breathing heavily. He said: “All praise belongs to Allah—abundant, pure, and blessed praise.” When the Messenger of Allah ﷺ completed the prayer, he asked: “Which of you spoke those words?” The people remained silent. He asked again: “Which of you said them? He did not say anything wrong.” A man replied: “I arrived while breathing heavily, so I said them.” The Prophet ﷺ said: “I saw twelve angels hastening toward those words, each seeking to be the one who raised them.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1950],"tks":"صحيح: رواه مسلم (600)."},{"num":10995,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ:  بَيْنَمَا نَحْنُ نُصَلِّي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ قَالَ رَجُلٌ مِنَ الْقَوْمِ: اللهُ أَكْبَرُ كَبِيرًا، وَالْحَمْدُ لِلهِ كَثِيرًا، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنِ الْقَائِلُ كَلِمَةَ كَذَا وَكَذَا؟ قَالَ رَجُلٌ مِنَ الْقَوْمِ: أَنَا يَا رَسُولَ اللَّهِ. قَالَ: عَجِبْتُ لَهَا! فُتِحَتْ لَهَا أَبْوَابُ السَّمَاءِ.","قَالَ ابْنُ عُمَرَ: فَمَا تَرَكْتُهُنَّ مُنْذُ سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَقُولُ ذَلِكَ."],"takhrij":"صحيح: رواه مسلم في المساجد (601) من حديث أبي الزبير، عن عون بن عبدالله بن عتبة، عن ابن عمر فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما يقال من أدعية الاستفتاح بعد تكبيرة الإحرام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (601).","chapter_en":"Opening Supplications Recited after the Opening Takbīr","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿUmar narrated: While we were praying with the Messenger of Allah ﷺ, a man from among the people said: “Allah is greater than everything in greatness. Abundant praise belongs to Allah, and glory be to Allah in the morning and evening.” The Messenger of Allah ﷺ asked: “Who said these particular words?” A man replied: “I did, O Messenger of Allah.” He said: “I was amazed by them. The gates of heaven were opened for them.” Ibn ʿUmar said: “I never abandoned these words after hearing the Messenger of Allah ﷺ say that.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (601)."},{"num":10996,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّ رَجُلًا قَالَ: ذَاتَ يَوْمٍ، وَدَخَلَ الصَّلَاةَ: الْحَمْدُ لِلَّهِ مِلْءَ السَّمَاءِ، وَسَبَّحَ وَدَعَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ قَائِلُهُنَّ؟ فَقَالَ الرَّجُلُ: أَنَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَقَدْ رَأَيْتُ الْمَلَائِكَةَ تَلَقَّى بِهِ بَعْضُهُمْ بَعْضًا."],"takhrij":"صحيح: رواه أحمد (6632، 7060)، والبزار (كشف الأستار-524) كلاهما من طريق حماد بن سلمة، عن عطاء بن السائب، عن أبيه، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب ما يقال من أدعية الاستفتاح بعد تكبيرة الإحرام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (6632, 7060) and al-Bazzār in Kashf al-Astār (524).","chapter_en":"Opening Supplications Recited after the Opening Takbīr","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated: One day, a man entered the prayer and said: “All praise belongs to Allah, enough to fill the heaven.” He then glorified Allah and supplicated. The Messenger of Allah ﷺ asked: “Who said these words?” The man replied: “I did.” The Prophet ﷺ said: “I saw the angels passing these words from one to another.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (6632، 7060)، والبزار في كشف الأستار (524)."},{"num":10997,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكْثِرُ أَنْ يَقُولَ فِي رُكُوعِهِ وَسُجُودِهِ: سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي. يَتَأَوَّلُ الْقُرْآنَ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4968)، ومسلم في الصلاة (484) كلاهما من طريق جرير، عن منصور، عن أبي الضُحى، عن مسروق، عن عائشة فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4968) and Muslim (484).","chapter_en":"What Should Be Said While Bowing and Prostrating","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["ʿĀ’ishah narrated: The Prophet ﷺ would frequently say while bowing and prostrating: “Glory be to You, O Allah, our Lord, and all praise belongs to You. O Allah, forgive me.” He was putting the Qur’an into practice."]},"buhuth":{"en":["Her words, “He was putting the Qur’an into practice,” refer to the words of Allah, the Exalted:","“When the victory of Allah and the conquest come, and you see the people entering the religion of Allah in multitudes, then glorify your Lord with praise and seek His forgiveness. Indeed, He is ever accepting of repentance.”","[Sūrat al-Naṣr]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13788],"tks":"متفق عليه: رواه البخاري (4968)، ومسلم (484)."},{"num":10998,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتِ: افْتَقَدْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَظَنَنْتُ أَنَّهُ ذَهَبَ إِلَى بَعْضِ نِسَائِهِ. فَتَحَسَّسْتُ ثُمَّ رَجَعْتُ فَإِذَا هُوَ رَاكِعٌ، - أَوْ سَاجِدٌ - يَقُولُ: سُبْحَانَكَ وَبِحَمْدِكَ، لَا إِلَهَ إِلَّا أَنْتَ. فَقُلْتُ: بِأَبِي أَنْتَ وَأُمِّي، إِنِّي لَفِي شَأْنٍ وَإِنَّكَ لَفِي آخَرَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (485) من طريق عبد الرزاق، أخبرنا ابن جريج قال: قلت لعطاء: كيف تقول أنت في الركوع؟ قال: أمَّا سبحانك وبحمدك لا إله إلا أنت.فأخبرني ابن أبي مليكة، عن عائشة قالت: فذكرتِ الحديث.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (485).","chapter_en":"What Should Be Said While Bowing and Prostrating","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["ʿĀ’ishah narrated: One night, I noticed that the Prophet ﷺ was absent. I thought that he had gone to one of his other wives, so I searched for him and then returned. I found him bowing or prostrating and saying: “Glory be to You and all praise belongs to You. There is no deity worthy of worship except You.” I said: “May my father and mother be sacrificed for you! I am occupied with one matter, while you are occupied with something entirely different.”"]}},"tuhfa":{},"full":1,"rep":[2122,6407],"tks":"صحيح: رواه مسلم (485)."},{"num":10999,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  فَقَدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً مِنَ الْفِرَاشِ، فَالْتَمَسْتُهُ فَوَقَعَتْ يَدِي عَلَى بَطْنِ قَدَمَيْهِ، وَهُوَ فِي الْمَسْجِدِ، وَهُمَا مَنْصُوبَتَانِ، وَهُوَ يَقُولُ: اللَّهُمَّ أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ. وَأَعُوذُ بِكَ مِنْكَ، لَا أُحْصِي ثَنَاءً عَلَيْكَ أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (486) عن أبي بكر بن أبي شيبة، ثنا أبو أسامة، حدثني عبيدالله بن عمر، عن محمد بن يحيى بن حبان، عن الأعرج، عن أبي هريرة، عن عائشة فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (486).","chapter_en":"What Should Be Said While Bowing and Prostrating","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["ʿĀ’ishah narrated: One night, I found that the Messenger of Allah ﷺ was no longer in bed, so I searched for him. My hand touched the soles of his feet while he was in the mosque, with both feet upright. He was saying: “O Allah, I seek refuge in Your pleasure from Your anger, in Your pardon from Your punishment, and in You from You. I cannot enumerate sufficient praise of You. You are as You have praised Yourself.”"]}},"tuhfa":{},"full":1,"rep":[2123],"tks":"صحيح: رواه مسلم (486)."}]);